const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:40,000", "arabic": "وَإِنِّي آلَيْتُ عَلَى نَفْسِي أَنْ أَسْمَحَ لِلنَّاسِ جَمِيعًا أَنْ يَخُوضُوا فِي كُلِّ مَسْأَلَةٍ لِلْعَقْلِ فِيهَا نَصِيبٌ", "segs": [{"ar": "وَإِنِّي آلَيْتُ عَلَى نَفْسِي أَنْ أَسْمَحَ لِلنَّاسِ جَمِيعًا", "uz": "Men o'zimga qasam ichdim — barcha odamlarga ruxsat beraman"}, {"ar": "أَنْ يَخُوضُوا فِي كُلِّ مَسْأَلَةٍ لِلْعَقْلِ فِيهَا نَصِيبٌ", "uz": "aqlning ulushi bo'lgan har bir masalada bahs yuritishga"}], "full_uz": "Men o'zimga qasam ichdim — barcha odamlarga aqlning ulushi bo'lgan har bir masalada bahs yuritishga ruxsat beraman.", "note": null},
  {"num": 4, "time": "00:00:40,000 --> 00:00:48,000", "arabic": "اَللَّهُمَّ إِلَّا مُلْحِدًا يُجَاهِرُ بِالْمُعَادَاةِ لِلَّهِ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Faqat Allohga subhonahu va taologa oshkora dushmanlik qiluvchi dahriydan boshqa.", "note": null},
  {"num": 5, "time": "00:00:48,000 --> 00:00:56,000", "arabic": "وَلَكِنْ أَلَا يَغْضَبُ هَذَا مَنْ لَا يَرَوْنَ لِلْعَقْلِ دَوْرًا", "segs": null, "full_uz": "Ammo bu — aqlga o'rin bermaydiganlarni g'azablantirmaydimi?", "note": null},
  {"num": 6, "time": "00:00:56,000 --> 00:01:04,719", "arabic": "وَاعْتَمَدُوا فِي دِينِهِمْ عَلَى النَّقْلِ فَحَسْبُ، فَظَلُّوا فِي فَهْمِ النُّصُوصِ وَأَضَلُّوا بِغَيْرِ عِلْمٍ", "segs": [{"ar": "وَاعْتَمَدُوا فِي دِينِهِمْ عَلَى النَّقْلِ فَحَسْبُ", "uz": "O'z dinlarida faqat naqlga tayanadiganlarni"}, {"ar": "فَظَلُّوا فِي فَهْمِ النُّصُوصِ وَأَضَلُّوا بِغَيْرِ عِلْمٍ", "uz": "ular matnlarni tushunishda adashib, ilmsizlikda boshqalarni ham yo'ldan urdilar"}], "full_uz": "Va o'z dinlarida faqat naqlga (rivoyatga) tayanadiganlarni — ular matnlarni tushunishda adashib, ilmsizlikda boshqalarni ham yo'ldan urdilar.", "note": null},
  {"num": 8, "time": "00:01:04,719 --> 00:01:10,920", "arabic": "مَنْ زَادُوا الطِّينَ بِلَّةً فَرَمَوْا بِالْبِدْعَةِ كُلَّ مَنْ لَمْ يَأْخُذْ بِرَأْيِهِمْ", "segs": [{"ar": "مَنْ زَادُوا الطِّينَ بِلَّةً", "uz": "Ishni battar chigallashtirganlar"}, {"ar": "فَرَمَوْا بِالْبِدْعَةِ كُلَّ مَنْ لَمْ يَأْخُذْ بِرَأْيِهِمْ", "uz": "o'z fikrlariga qo'shilmagan har kimni bid'atchilikda ayblashdi"}], "full_uz": "Ustiga ustak, o'z fikrlariga qo'shilmagan har kimni bid'atchilikda ayblab, ishni battar chigallashtirdilar.", "note": "«زَادَ الطِّينَ بِلَّةً» — allaqachon yomon bo'lgan ahvolni yanada yomonlashtirish ma'nosidagi mashhur ibora."},
  {"num": 9, "time": "00:01:10,920 --> 00:01:15,079", "arabic": "تَحْتَ دِثَارٍ يُسَمُّونَهُ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ", "segs": null, "full_uz": "«Ahli sunna va jamoa» deb ataydigan niqob ostida.", "note": null},
  {"num": 10, "time": "00:01:15,079 --> 00:01:20,079", "arabic": "فَلَا سُنَّةً أَقَامُوا وَلَا جَمَاعَةً أَبْقَوْا", "segs": null, "full_uz": "Na sunnatni to'g'ri o'rnatdilar, na jamoani saqlab qoldilar.", "note": null},
  {"num": 11, "time": "00:01:20,079 --> 00:01:28,099", "arabic": "سَأَحْرِصُ عَلَى أَلَّا يَتَعَرَّضَ أَحَدٌ مِنْ هَؤُلَاءِ الَّذِينَ تَتَحَدَّثُ عَنْهُمْ لِأَيِّ مَسْلَمِينَ بَعْدَ الْيَوْمِ", "segs": [{"ar": "سَأَحْرِصُ عَلَى أَلَّا يَتَعَرَّضَ أَحَدٌ مِنْ هَؤُلَاءِ الَّذِينَ تَتَحَدَّثُ عَنْهُمْ", "uz": "Siz gapirayotgan bu kishilardan hech biri tegmasligini ta'minlashga harakat qilaman"}, {"ar": "لِأَيِّ مَسْلَمِينَ بَعْدَ الْيَوْمِ", "uz": "bugundan boshlab hech qanday musulmonga"}], "full_uz": "Bugundan boshlab, siz gapirayotgan bu kishilardan hech biri hech qanday musulmonga tegishmasligini ta'minlashga harakat qilaman.", "note": null},
  {"num": 12, "time": "00:01:28,099 --> 00:01:35,099", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَمِيرَ الْمُؤْمِنِينَ، وَجَزَاكَ اللَّهُ خَيْرًا عَنِ الْإِسْلَامِ وَأَهْلِهِ", "segs": [{"ar": "بَارَكَ اللَّهُ فِيكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "uz": "Alloh sizga barakot bersin, Amir al-Mo'minin"}, {"ar": "وَجَزَاكَ اللَّهُ خَيْرًا عَنِ الْإِسْلَامِ وَأَهْلِهِ", "uz": "Alloh Islom va uning ahli nomidan sizga yaxshilik bersin"}], "full_uz": "Alloh sizga barakot bersin, Amir al-Mo'minin — Alloh Islom va uning ahli nomidan sizga yaxshilik bersin.", "note": null},
  {"num": 14, "time": "00:01:35,099 --> 00:01:45,179", "arabic": "أَعْطِنِيهِ عَنْكَ يَا أَحْمَدُ فَإِنَّهُ لَا يَدَعُكَ تَرْتَاحُ", "segs": null, "full_uz": "Uni menga ber, Ahmad — u seni tinch qo'ymayapti.", "note": null},
  {"num": 15, "time": "00:01:45,179 --> 00:01:50,879", "arabic": "دَعِيهِ يَا عَبَّاسَةُ فَقَلَّ مَا أَرَى، كَانَ اللَّهُ فِي عَوْنِكَ", "segs": [{"ar": "دَعِيهِ يَا عَبَّاسَةُ فَقَلَّ مَا أَرَى", "uz": "Qo'y, Abbosa — ko'rgan vaqtim kamayib qoldi"}, {"ar": "كَانَ اللَّهُ فِي عَوْنِكَ", "uz": "Alloh senga yordamchi bo'lsin"}], "full_uz": "Qo'y, Abbosa — ko'rgan vaqtim kamayib qoldi. Alloh senga yordamchi bo'lsin.", "note": null},
  {"num": 17, "time": "00:01:50,879 --> 00:01:55,959", "arabic": "لَا أَدْرِي مَتَى تَرْتَاحُ، فِي النَّهَارِ مَعَ طُلَّابِكَ", "segs": null, "full_uz": "Qachon dam olishingni bilmayman — kunduzi talabalaring bilan.", "note": null},
  {"num": 19, "time": "00:01:55,959 --> 00:02:00,280", "arabic": "وَفِي اللَّيْلِ فِي صَلَاتِكَ، هَذَا مِنْ فَضْلِ اللَّهِ عَلَيْنَا يَا عَبَّاسَةُ", "segs": [{"ar": "وَفِي اللَّيْلِ فِي صَلَاتِكَ", "uz": "Kechasi esa namozingda"}, {"ar": "هَذَا مِنْ فَضْلِ اللَّهِ عَلَيْنَا يَا عَبَّاسَةُ", "uz": "Bu bizga Allohning fazlidan, Abbosa"}], "full_uz": "Kechasi esa namozingda. Bu bizga Allohning fazlidan, Abbosa.", "note": null},
  {"num": 21, "time": "00:02:00,280 --> 00:02:14,840", "arabic": "فَمَا خَطَوْتُ خَطْوَةً إِلَّا كُتِبَ لَكِ مِثْلُ أَجْرِي، فَقَدْ تَحَمَّلْتِ مِنِّي الْكَثِيرَ وَمَا رَأَيْتُ مِنْكِ إِلَّا الصَّبْرَ الْجَمِيلَ", "segs": [{"ar": "فَمَا خَطَوْتُ خَطْوَةً إِلَّا كُتِبَ لَكِ مِثْلُ أَجْرِي", "uz": "Har bir qadamim uchun senga ham mening ajrim kabi yoziladi"}, {"ar": "فَقَدْ تَحَمَّلْتِ مِنِّي الْكَثِيرَ وَمَا رَأَيْتُ مِنْكِ إِلَّا الصَّبْرَ الْجَمِيلَ", "uz": "mendan ko'p narsani ko'targansan, sendan faqat go'zal sabr ko'rganman"}], "full_uz": "Har bir qadamim uchun senga ham mening ajrim kabi yoziladi — mendan ko'p narsani ko'targansan, sendan faqat go'zal sabr ko'rganman.", "note": null},
  {"num": 24, "time": "00:02:15,539 --> 00:02:20,259", "arabic": "إِنَّ كُلَّ مَا نَقُولُ بِهِ لَا يَتَعَدَّى تَنْزِيهَ اللَّهِ سُبْحَانَهُ وَتَعَالَى عَمَّا لَا يَلِيقُ بِهِ", "segs": [{"ar": "إِنَّ كُلَّ مَا نَقُولُ بِهِ لَا يَتَعَدَّى تَنْزِيهَ اللَّهِ سُبْحَانَهُ وَتَعَالَى", "uz": "Bizning aytgan hamma gapimiz Alloh subhonahu va taologa pok deb bilishdan boshqa narsa emas"}, {"ar": "عَمَّا لَا يَلِيقُ بِهِ", "uz": "Unga yarashmagan sifatlardan"}], "full_uz": "Bizning aytgan hamma gapimiz Alloh subhonahu va taologa yarashmagan sifatlardan Uni pok deb bilishdan boshqa narsa emas.", "note": null},
  {"num": 25, "time": "00:02:20,259 --> 00:02:26,599", "arabic": "أَنُوسَمُ بِالْخَطَإِ لِأَنَّنَا نُنَزِّهُ اللَّهَ سُبْحَانَهُ وَتَعَالَى عَمَّا يَقُولُهُ الْأَدْعِيَاءُ الضُّلَّالُ؟", "segs": [{"ar": "أَنُوسَمُ بِالْخَطَإِ لِأَنَّنَا نُنَزِّهُ اللَّهَ سُبْحَانَهُ وَتَعَالَى", "uz": "Allohni subhonahu va taologa pok deb bilganimiz uchun xatoga chiqarilamizmi"}, {"ar": "عَمَّا يَقُولُهُ الْأَدْعِيَاءُ الضُّلَّالُ؟", "uz": "adashgan da'vogarlar aytgan narsalardan?"}], "full_uz": "Adashgan da'vogarlar aytgan narsalardan Allohni subhonahu va taologa pok deb bilganimiz uchun xatoga chiqarilamizmi?", "note": null},
  {"num": 26, "time": "00:02:26,599 --> 00:02:32,239", "arabic": "وَقَوْلُنَا إِنَّ الْقُرْآنَ مَخْلُوقٌ مُؤَيَّدٌ بِالْأَدِلَّةِ وَالْبَرَاهِينِ", "segs": null, "full_uz": "Qur'on yaratilgandir, degan gapimiz dalil va isbotlar bilan qo'llab-quvvatlangan.", "note": null},
  {"num": 27, "time": "00:02:32,239 --> 00:02:37,680", "arabic": "أَمَّا إِنْكَارُ الْعَوَامِّ ذَلِكَ فَأَوْهَنُ مِنْ أَنْ يَدْعَمَهُ دَلِيلٌ", "segs": null, "full_uz": "Ommaning buni inkor etishi esa dalil bilan qo'llab-quvvatlanishdan ancha bo'shdir.", "note": null},
  {"num": 29, "time": "00:02:37,680 --> 00:02:48,259", "arabic": "قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ، فَهَلْ بَعْدَ هَذَا الْكَلَامِ كَلَامٌ؟", "segs": [{"ar": "قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ", "uz": "Ayt: agar rost so'zlovchi bo'lsangiz, dalilingizni keltiring"}, {"ar": "فَهَلْ بَعْدَ هَذَا الْكَلَامِ كَلَامٌ؟", "uz": "shu gapdan keyin yana gap qoladimi?"}], "full_uz": "Ayt: agar rost so'zlovchi bo'lsangiz, dalilingizni keltiring — shu gapdan keyin yana gap qoladimi?", "note": "«قُلْ هَاتُوا بُرْهَانَكُمْ» — Baqara surasi, 2:111-oyatdan iqtibos."},
  {"num": 31, "time": "00:02:48,259 --> 00:02:55,180", "arabic": "مَنْ تَقْصِدُ بِالْعَوَامِّ يَا أَيُّهَا الْجَاهِلُ؟ تَقْصِدُ بِهِمْ شُيُوخَ بَغْدَادَ وَعُلَمَاءَهَا؟", "segs": [{"ar": "مَنْ تَقْصِدُ بِالْعَوَامِّ يَا أَيُّهَا الْجَاهِلُ؟", "uz": "Ommadan kimni nazarda tutyapsan, ey jaholat sohibi?"}, {"ar": "تَقْصِدُ بِهِمْ شُيُوخَ بَغْدَادَ وَعُلَمَاءَهَا؟", "uz": "Bag'dodning shayxlari va olimlarini nazarda tutyapsanmi?"}], "full_uz": "Ommadan kimni nazarda tutyapsan, ey jaholat sohibi? Bag'dodning shayxlari va olimlarini nazarda tutyapsanmi?", "note": null},
  {"num": 33, "time": "00:02:55,180 --> 00:03:04,580", "arabic": "لَقَدْ أَضَلَّتْكُمْ عُقُولُكُمْ وَأَوْرَدَتْكُمْ حِيَاضَ الْبِدْعَةِ وَالْمُبْتَدِعَةِ، مَا تَقْصِدُ بِالْمُبْتَدِعَةِ أَيُّهَا الْأَحْمَقُ؟", "segs": [{"ar": "لَقَدْ أَضَلَّتْكُمْ عُقُولُكُمْ وَأَوْرَدَتْكُمْ حِيَاضَ الْبِدْعَةِ وَالْمُبْتَدِعَةِ", "uz": "Aqllaringiz sizlarni adashtirib, bid'at va bid'atchilar hovuziga tashlab yubordi"}, {"ar": "مَا تَقْصِدُ بِالْمُبْتَدِعَةِ أَيُّهَا الْأَحْمَقُ؟", "uz": "Bid'atchilardan nimani nazarda tutyapsan, ey ahmoq?"}], "full_uz": "Aqllaringiz sizlarni adashtirib, bid'at va bid'atchilar hovuziga tashlab yubordi. Bid'atchilardan nimani nazarda tutyapsan, ey ahmoq?", "note": null},
  {"num": 35, "time": "00:03:04,580 --> 00:03:11,800", "arabic": "غَفَرَ اللَّهُ لَكَ وَهَدَاكَ إِلَى الْحَقِّ، اَلْمُبْتَدِعَةُ هُمْ مَنْ مَلَأُوا صَحْنَ عَقْلِكَ هَذَا بِالشُّبُهَاتِ", "segs": [{"ar": "غَفَرَ اللَّهُ لَكَ وَهَدَاكَ إِلَى الْحَقِّ", "uz": "Alloh sizni kechirsin va haqqa hidoyat qilsin"}, {"ar": "اَلْمُبْتَدِعَةُ هُمْ مَنْ مَلَأُوا صَحْنَ عَقْلِكَ هَذَا بِالشُّبُهَاتِ", "uz": "Bid'atchilar sizning shu aqlingizni shubhalar bilan to'ldirganlardir"}], "full_uz": "Alloh sizni kechirsin va haqqa hidoyat qilsin — bid'atchilar sizning shu aqlingizni shubhalar bilan to'ldirganlardir.", "note": null},
  {"num": 37, "time": "00:03:11,800 --> 00:03:19,240", "arabic": "لِتُثِيرَ بَيْنَ النَّاسِ الْفِتْنَةَ فَتُفْسِدَ عَلَيْهِمْ دِينَهُمْ وَدُنْيَاهُمْ، أَمْسِكْ عَلَيْكَ لِسَانَكَ أَيُّهَا الضَّالُّ الْمُضِلُّ", "segs": [{"ar": "لِتُثِيرَ بَيْنَ النَّاسِ الْفِتْنَةَ فَتُفْسِدَ عَلَيْهِمْ دِينَهُمْ وَدُنْيَاهُمْ", "uz": "Odamlar orasida fitna qo'zg'atib, ularning dini va dunyosini buzish uchun"}, {"ar": "أَمْسِكْ عَلَيْكَ لِسَانَكَ أَيُّهَا الضَّالُّ الْمُضِلُّ", "uz": "Tilingni tiy, ey adashgan va adashtiruvchi"}], "full_uz": "Odamlar orasida fitna qo'zg'atib, ularning dini va dunyosini buzish uchun. Tilingni tiy, ey adashgan va adashtiruvchi.", "note": null},
  {"num": 39, "time": "00:03:19,240 --> 00:03:24,200", "arabic": "وَإِيَّاكَ أَنْ تَذْكُرَ مَشَايِخَنَا بِسُوءٍ يَا رَبِيبَ الْجَهَالَةِ وَالضَّلَالِ، هَيَّا انْصَرِفْ", "segs": [{"ar": "وَإِيَّاكَ أَنْ تَذْكُرَ مَشَايِخَنَا بِسُوءٍ يَا رَبِيبَ الْجَهَالَةِ وَالضَّلَالِ", "uz": "Shayxlarimizni yomonlab tilga olma, ey jaholat va zalolat tarbiyasidagi kishi"}, {"ar": "هَيَّا انْصَرِفْ", "uz": "Yur, ket bu yerdan"}], "full_uz": "Shayxlarimizni yomonlab tilga olma, ey jaholat va zalolat tarbiyasidagi kishi. Yur, ket bu yerdan.", "note": null},
  {"num": 41, "time": "00:03:24,200 --> 00:03:30,080", "arabic": "وَلَا تُنَجِّسْ مَسَاجِدَنَا بِفَسَادِ عَقَائِدِكَ وَضَلَالِ مَذَاهِبِكَ، اِذْهَبْ هَدَاكَ اللَّهُ", "segs": [{"ar": "وَلَا تُنَجِّسْ مَسَاجِدَنَا بِفَسَادِ عَقَائِدِكَ وَضَلَالِ مَذَاهِبِكَ", "uz": "Masjidlarimizni buzuq aqidalaring va adashgan mazhabing bilan iflos qilma"}, {"ar": "اِذْهَبْ هَدَاكَ اللَّهُ", "uz": "Ket, Alloh seni hidoyat qilsin"}], "full_uz": "Va masjidlarimizni buzuq aqidalaring va adashgan mazhabing bilan iflos qilma. Ket, Alloh seni hidoyat qilsin.", "note": null},
  {"num": 44, "time": "00:03:30,080 --> 00:03:34,980", "arabic": "اِذْهَبْ، اِهْدَأْ يَا أَبَا النَّصْرِ", "segs": null, "full_uz": "Ket. Tinchlaning, Abu an-Nasr.", "note": null},
  {"num": 46, "time": "00:03:34,980 --> 00:03:40,640", "arabic": "إِنَّهُمْ أَقَلُّ مِنْ أَنْ تَبْخَعَ نَفْسَكَ عَلَى أَثَرِهِمْ، مَلَأَ الْهَوَاءَ بِسُمُومِهِمْ", "segs": [{"ar": "إِنَّهُمْ أَقَلُّ مِنْ أَنْ تَبْخَعَ نَفْسَكَ عَلَى أَثَرِهِمْ", "uz": "Ular sen o'zingni ularning izidan bunday halok qilishga arzimaydi"}, {"ar": "مَلَأَ الْهَوَاءَ بِسُمُومِهِمْ", "uz": "Havoni o'z zaharlari bilan to'ldirdi"}], "full_uz": "Ular sen o'zingni ularning izidan bunday halok qilishga arzimaydi. Havoni o'z zaharlari bilan to'ldirdi.", "note": "بَخَعَ نَفْسَهُ — o'zini g'am-tashvishdan halok qilish darajasiga yetkazish."},
  {"num": 48, "time": "00:03:40,640 --> 00:03:45,020", "arabic": "حَتَّى مَسَاجِدُ الرَّحْمَنِ لَمْ تَسْلَمْ مِنِ ابْتِدَاعِهِمْ", "segs": null, "full_uz": "Hatto Rahmonning masjidlari ham ularning bid'atidan omon qolmadi.", "note": null},
  {"num": 50, "time": "00:03:45,020 --> 00:03:49,120", "arabic": "إِلَى هَذَا الْحَدِّ وَصَلَتْ وَقَاحَةُ أَهْلِ الِابْتِدَاعِ", "segs": null, "full_uz": "Bid'at ahlining beadabligi shu darajaga yetibdi.", "note": null},
  {"num": 52, "time": "00:03:49,120 --> 00:03:56,620", "arabic": "كُلُّ هَذَا بِسَبَبِ تَسَاهُلِ الْمَعْصُومِ، اِهْدَأْ يَا أَبَا نَصْرٍ", "segs": null, "full_uz": "Bularning barchasi ma'sum (hukmdor)ning yumshoqligi tufaylidir. Tinchlaning, Abu Nasr.", "note": "اَلْمَعْصُوم — bu yerda hukmdorga kesatib ishlatilgan, uni xato qilmaydigandek atash."},
  {"num": 54, "time": "00:03:56,620 --> 00:04:09,299", "arabic": "لِأَبِي عَبْدِ الرَّحْمَنِ الْفَضْلِ أَنْ شَرَّفَنِي بِرُؤْيَةِ وَجْهِ أَمِيرِ الْمُؤْمِنِينَ وَهَدَانِي إِلَى طَرِيقِ الْحَقِّ وَخَلَّصَنِي مِنْ طَرِيقِ الضَّلَالَةِ", "segs": [{"ar": "لِأَبِي عَبْدِ الرَّحْمَنِ الْفَضْلِ أَنْ شَرَّفَنِي بِرُؤْيَةِ وَجْهِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Abu Abd ar-Rahmon al-Fadlga tegishlidir — meni Amir al-Mo'minin yuzini ko'rish sharafiga muyassar qilgani"}, {"ar": "وَهَدَانِي إِلَى طَرِيقِ الْحَقِّ", "uz": "haq yo'liga hidoyat qilgani"}, {"ar": "وَخَلَّصَنِي مِنْ طَرِيقِ الضَّلَالَةِ", "uz": "va zalolat yo'lidan qutqargani"}], "full_uz": "Abu Abd ar-Rahmon al-Fadlga tegishlidir — meni Amir al-Mo'minin yuzini ko'rish sharafiga muyassar qilib, haq yo'liga hidoyat qilgani va zalolat yo'lidan qutqargani.", "note": null},
  {"num": 57, "time": "00:04:17,300 --> 00:04:26,620", "arabic": "إِذَنْ فَلِلشَّيْخِ الْمَرِيسِيِّ مُطْلَقُ الْوَلَاءِ وَنِهَايَةُ الْوَفَاءِ مِنْكَ يَا أَبَا الْعَبَّاسِ", "segs": [{"ar": "إِذَنْ فَلِلشَّيْخِ الْمَرِيسِيِّ مُطْلَقُ الْوَلَاءِ", "uz": "Demak, senda shayx al-Marisiyga mutlaq sodiqlik bor"}, {"ar": "وَنِهَايَةُ الْوَفَاءِ مِنْكَ يَا أَبَا الْعَبَّاسِ", "uz": "va sendan cheksiz vafo bor, Abu al-Abbos"}], "full_uz": "Demak, senda shayx al-Marisiyga mutlaq sodiqlik va cheksiz vafo bor, Abu al-Abbos.", "note": null},
  {"num": 59, "time": "00:04:26,620 --> 00:04:29,780", "arabic": "يَا مَوْلَايَ أَعَزَّكَ اللَّهُ", "segs": null, "full_uz": "Xo'jayinim, Alloh sizni aziz qilsin.", "note": null},
  {"num": 60, "time": "00:04:29,780 --> 00:04:36,060", "arabic": "إِنَّ مَحَبَّتِي لِأَبِي عَبْدِ الرَّحْمَنِ كَمَحَبَّةِ ابْنٍ لِأَبِيهِ", "segs": null, "full_uz": "Abu Abd ar-Rahmonga bo'lgan muhabbatim, farzandning otasiga bo'lgan muhabbati kabidir.", "note": null},
  {"num": 61, "time": "00:04:36,060 --> 00:04:46,260", "arabic": "فَإِنْ خَرَجَ أَبِي عَنْ طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ لَمْ يَبْقَ لَهُ فِي قَلْبِي مِثْقَالُ ذَرَّةٍ مِنَ الْمَحَبَّةِ وَالْوَفَاءِ", "segs": [{"ar": "فَإِنْ خَرَجَ أَبِي عَنْ طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Agar otam Amir al-Mo'mininga itoatdan chiqsa"}, {"ar": "لَمْ يَبْقَ لَهُ فِي قَلْبِي مِثْقَالُ ذَرَّةٍ مِنَ الْمَحَبَّةِ وَالْوَفَاءِ", "uz": "qalbimda unga zarracha muhabbat va vafo qolmaydi"}], "full_uz": "Agar otam Amir al-Mo'mininga itoatdan chiqsa, qalbimda unga zarracha muhabbat va vafo qolmaydi.", "note": null},
  {"num": 63, "time": "00:04:46,259 --> 00:04:56,759", "arabic": "إِنَّ وَلَائِي الْمُطْلَقَ لِأَمِيرِ الْمُؤْمِنِينَ فَحَسْبُ، وَلَنْ يُزَاحِمَ ذَلِكَ الْوَلَاءَ مَخْلُوقٌ", "segs": [{"ar": "إِنَّ وَلَائِي الْمُطْلَقَ لِأَمِيرِ الْمُؤْمِنِينَ فَحَسْبُ", "uz": "Mening mutlaq sodiqligim faqat Amir al-Mo'mininga"}, {"ar": "وَلَنْ يُزَاحِمَ ذَلِكَ الْوَلَاءَ مَخْلُوقٌ", "uz": "bu sodiqlikka hech qanday maxluq raqib bo'la olmaydi"}], "full_uz": "Mening mutlaq sodiqligim faqat Amir al-Mo'mininga — bu sodiqlikka hech qanday maxluq raqib bo'la olmaydi.", "note": null},
  {"num": 65, "time": "00:04:56,759 --> 00:05:07,259", "arabic": "أَيْنَ تَرَى نَفْسَكَ يَا أَبَا الْعَبَّاسِ؟", "segs": null, "full_uz": "O'zingni qayerda ko'rasan, Abu al-Abbos?", "note": null},
  {"num": 66, "time": "00:05:09,259 --> 00:05:16,259", "arabic": "لَا أَرَاهَا إِلَّا حَيْثُ يَرَانِي أَمِيرُ الْمُؤْمِنِينَ، أَنَا خَادِمُكَ وَعَبْدُكَ يَا مَوْلَايَ", "segs": [{"ar": "لَا أَرَاهَا إِلَّا حَيْثُ يَرَانِي أَمِيرُ الْمُؤْمِنِينَ", "uz": "Faqat Amir al-Mo'minin meni ko'rgan joyda ko'raman"}, {"ar": "أَنَا خَادِمُكَ وَعَبْدُكَ يَا مَوْلَايَ", "uz": "men sizning xizmatkoringiz va qulingizman, xo'jayinim"}], "full_uz": "Faqat Amir al-Mo'minin meni ko'rgan joyda ko'raman — men sizning xizmatkoringiz va qulingizman, xo'jayinim.", "note": null},
  {"num": 68, "time": "00:05:16,259 --> 00:05:28,000", "arabic": "إِنْ وَضَعْنَاكَ فِي الْعَسَسِ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Agar seni qorovullar orasiga qo'ysak, Abu al-Abbos.", "note": null},
  {"num": 69, "time": "00:05:28,000 --> 00:05:36,639", "arabic": "مَا كُنْتَ فَاعِلًا؟ خَلَعْتُ عَيْنِي فَلَا أَرَى إِلَّا بِعَيْنَيْكَ يَا مَوْلَايَ", "segs": [{"ar": "مَا كُنْتَ فَاعِلًا؟", "uz": "Nima qilarding?"}, {"ar": "خَلَعْتُ عَيْنِي فَلَا أَرَى إِلَّا بِعَيْنَيْكَ يَا مَوْلَايَ", "uz": "Ko'zimni chiqarib tashladim, endi faqat sizning ko'zlaringiz bilan ko'raman, xo'jayinim"}], "full_uz": "Nima qilarding? Ko'zimni chiqarib tashladim, endi faqat sizning ko'zlaringiz bilan ko'raman, xo'jayinim.", "note": null},
  {"num": 71, "time": "00:05:36,639 --> 00:05:40,899", "arabic": "وَأَصَمَمْتُ أُذُنِي فَلَا أَسْمَعُ إِلَّا مَا يُرِيدُ أَمِيرُ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Va qulog'imni kar qildim, faqat Amir al-Mo'minin istagan narsani eshitaman.", "note": null},
  {"num": 72, "time": "00:05:42,899 --> 00:05:53,500", "arabic": "سَنَرَى يَا أَبَا الْعَبَّاسِ حُسْنَ الْعَمَلِ بَعْدَ أَنْ رَأَيْنَا حَلَاوَةَ الْكَلَامِ", "segs": [{"ar": "سَنَرَى يَا أَبَا الْعَبَّاسِ حُسْنَ الْعَمَلِ", "uz": "Endi ish yaxshiligini ko'ramiz, Abu al-Abbos"}, {"ar": "بَعْدَ أَنْ رَأَيْنَا حَلَاوَةَ الْكَلَامِ", "uz": "gapning shirinligini ko'rganimizdan keyin"}], "full_uz": "Gapning shirinligini ko'rganimizdan keyin, endi ish yaxshiligini ko'ramiz, Abu al-Abbos.", "note": null},
  {"num": 74, "time": "00:05:53,500 --> 00:06:05,839", "arabic": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ", "segs": [{"ar": "أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "Rasululloh sollallohu alayhi va sallam aytmaganmidilar"}, {"ar": "مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ", "uz": "Sizlardan kim bir munkarni ko'rsa, uni qo'li bilan o'zgartirsin"}], "full_uz": "Rasululloh sollallohu alayhi va sallam aytmaganmidilar: «Sizlardan kim bir munkarni ko'rsa, uni qo'li bilan o'zgartirsin»?", "note": "Bu — Muslim rivoyat qilgan mashhur hadis, munkarni o'zgartirish darajalari haqida."},
  {"num": 77, "time": "00:06:05,839 --> 00:06:14,899", "arabic": "فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ", "segs": [{"ar": "فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ", "uz": "Agar qo'li bilan qila olmasa, tili bilan"}, {"ar": "فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ", "uz": "agar tili bilan ham qila olmasa, qalbi bilan — bu esa imonning eng zaifidir"}], "full_uz": "Agar qo'li bilan qila olmasa, tili bilan; agar tili bilan ham qila olmasa, qalbi bilan — bu esa imonning eng zaifidir.", "note": null},
  {"num": 79, "time": "00:06:14,899 --> 00:06:19,500", "arabic": "فَفِيمَ الصَّمْتُ إِذَنْ عَلَى مُنْكَرِ هَؤُلَاءِ الشِّرْذِمَةِ؟", "segs": null, "full_uz": "Unda bu bir hovuch guruhning munkariga nisbatan sukut nima uchun?", "note": null},
  {"num": 80, "time": "00:06:19,500 --> 00:06:28,939", "arabic": "خَشْيَةَ الْفِتْنَةِ يَا أَبَا نَصْرٍ، لَا نُرِيدُ أَنْ نُثِيرَ النَّاسَ عَلَى الْخَلِيفَةِ فَرُبَّمَا حَدَثَ فَسَادٌ أَكْبَرُ مِمَّا هُوَ وَاقِعٌ الْآنَ", "segs": [{"ar": "خَشْيَةَ الْفِتْنَةِ يَا أَبَا نَصْرٍ", "uz": "Fitnadan qo'rqib, Abu Nasr"}, {"ar": "لَا نُرِيدُ أَنْ نُثِيرَ النَّاسَ عَلَى الْخَلِيفَةِ", "uz": "odamlarni xalifaga qarshi qo'zg'atishni istamaymiz"}, {"ar": "فَرُبَّمَا حَدَثَ فَسَادٌ أَكْبَرُ مِمَّا هُوَ وَاقِعٌ الْآنَ", "uz": "balki hozirgidan kattaroq buzuqlik yuz berishi mumkin"}], "full_uz": "Fitnadan qo'rqib, Abu Nasr — odamlarni xalifaga qarshi qo'zg'atishni istamaymiz, balki hozirgidan kattaroq buzuqlik yuz berishi mumkin.", "note": null},
  {"num": 83, "time": "00:06:28,939 --> 00:06:40,780", "arabic": "وَهَلْ هُنَاكَ فَسَادٌ وَظُلْمٌ أَشَدُّ مِمَّا يَقَعُ؟ أَنْ نُثِيرَ النَّاسَ عَلَى السُّلْطَانِ حِينَ نَنْتَصِرُ لِدِينِنَا ضِدَّ الْمُبْتَدِعَةِ", "segs": [{"ar": "وَهَلْ هُنَاكَ فَسَادٌ وَظُلْمٌ أَشَدُّ مِمَّا يَقَعُ؟", "uz": "Hozir sodir bo'layotgandan kattaroq buzuqlik va zulm bormi?"}, {"ar": "أَنْ نُثِيرَ النَّاسَ عَلَى السُّلْطَانِ حِينَ نَنْتَصِرُ لِدِينِنَا ضِدَّ الْمُبْتَدِعَةِ", "uz": "Dinimizni bid'atchilarga qarshi himoya qilganimizda odamlarni sultonga qarshi qo'zg'atish emas"}], "full_uz": "Hozir sodir bo'layotgandan kattaroq buzuqlik va zulm bormi? Dinimizni bid'atchilarga qarshi himoya qilganimizda odamlarni sultonga qarshi qo'zg'atish emas.", "note": null},
  {"num": 85, "time": "00:06:40,780 --> 00:06:49,740", "arabic": "اَلَّذِينَ أُطْلِقَ لَهُمُ الْحَبْلُ عَلَى غَارِبِهِ، أَنْ نُثِيرَ النَّاسَ عَلَى السُّلْطَانِ حِينَ لَا نُنْكِرُ عَلَيْهِ وَعَلَيْهِمْ", "segs": [{"ar": "اَلَّذِينَ أُطْلِقَ لَهُمُ الْحَبْلُ عَلَى غَارِبِهِ", "uz": "Ular jilovi bo'sh qo'yib yuborilganlardir"}, {"ar": "أَنْ نُثِيرَ النَّاسَ عَلَى السُّلْطَانِ حِينَ لَا نُنْكِرُ عَلَيْهِ وَعَلَيْهِمْ", "uz": "odamlarni sultonga qarshi qo'zg'atish, unga va ularga qarshi e'tiroz bildirmaganimizdadir"}], "full_uz": "Ular jilovi bo'sh qo'yib yuborilganlardir — odamlarni sultonga qarshi qo'zg'atish, unga va ularga qarshi e'tiroz bildirmaganimizdadir.", "note": "أُطْلِقَ لَهُ الْحَبْلُ عَلَى غَارِبِهِ — «jilovi bo'sh qo'yildi», ya'ni to'liq erkinlik berildi ma'nosidagi ibora."},
  {"num": 87, "time": "00:06:49,740 --> 00:06:59,579", "arabic": "مَا مَلَأَ بِهِ آذَانَ الْعَامَّةِ مِنَ الْكُفْرِ وَالضَّلَالِ، إِذَا كَانَ الْأَمْرُ كَمَا تَقُولُونَ فَأَهْلًا بِهَا وَنَعِمَتْ", "segs": [{"ar": "مَا مَلَأَ بِهِ آذَانَ الْعَامَّةِ مِنَ الْكُفْرِ وَالضَّلَالِ", "uz": "Ular omma qulog'ini kufr va zalolat bilan to'ldirgan narsaga"}, {"ar": "إِذَا كَانَ الْأَمْرُ كَمَا تَقُولُونَ فَأَهْلًا بِهَا وَنَعِمَتْ", "uz": "agar aytganlaringizdek bo'lsa, xush kelibsan, ne yaxshi"}], "full_uz": "Ular omma qulog'ini kufr va zalolat bilan to'ldirgan narsaga — agar aytganlaringizdek bo'lsa, xush kelibsan, ne yaxshi.", "note": null},
  {"num": 89, "time": "00:06:59,579 --> 00:07:08,500", "arabic": "يَبْدُو أَنَّ الْخُزَاعِيَّ يُغَرِّدُ خَارِجَ السِّرْبِ، فَعُلَمَاءُ بَغْدَادَ مِنْ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ يَتَحَاشَوْنَ الِاسْتِضَامَةَ بِإِخْوَتِنَا", "segs": [{"ar": "يَبْدُو أَنَّ الْخُزَاعِيَّ يُغَرِّدُ خَارِجَ السِّرْبِ", "uz": "Ko'rinishidan, al-Xuzo'iy podadan tashqarida sayraydi"}, {"ar": "فَعُلَمَاءُ بَغْدَادَ مِنْ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ يَتَحَاشَوْنَ الِاسْتِضَامَةَ بِإِخْوَتِنَا", "uz": "chunki Bag'dodning ahli sunna va jamoa olimlari birodarlarimizga zarar yetkazishdan tiyilishadi"}], "full_uz": "Ko'rinishidan, al-Xuzo'iy podadan tashqarida sayraydi — chunki Bag'dodning ahli sunna va jamoa olimlari birodarlarimizga zarar yetkazishdan tiyilishadi.", "note": "يُغَرِّدُ خَارِجَ السِّرْبِ — «podadan tashqarida sayraydi», ya'ni ko'pchilikdan farqli tutadi, majoziy ibora."},
  {"num": 91, "time": "00:07:08,500 --> 00:07:16,339", "arabic": "لَكِنَّ الْخُزَاعِيَّ لَهُ طَبْعٌ يَخْتَلِفُ وَجَدٌّ يَدُلُّ بِهِ عَلَى الْعَبَّاسِيِّ", "segs": [{"ar": "لَكِنَّ الْخُزَاعِيَّ لَهُ طَبْعٌ يَخْتَلِفُ", "uz": "Ammo al-Xuzo'iyning tabiati farqli"}, {"ar": "وَجَدٌّ يَدُلُّ بِهِ عَلَى الْعَبَّاسِيِّ", "uz": "jaddi orqali abbosiylarga ishora qiladi"}], "full_uz": "Ammo al-Xuzo'iyning tabiati farqli — jaddi orqali abbosiylarga ishora qiladi.", "note": null},
  {"num": 93, "time": "00:07:17,560 --> 00:07:22,199", "arabic": "كَانَ جَدُّهُ وَاسْمُهُ مَالِكُ بْنُ الْهَيْثَمِ مِنْ أَكْبَرِ الدُّعَاةِ إِلَى دَوْلَةِ بَنِي الْعَبَّاسِ", "segs": [{"ar": "كَانَ جَدُّهُ وَاسْمُهُ مَالِكُ بْنُ الْهَيْثَمِ", "uz": "Uning bobosi — ismi Molik ibn al-Haysam edi"}, {"ar": "مِنْ أَكْبَرِ الدُّعَاةِ إِلَى دَوْلَةِ بَنِي الْعَبَّاسِ", "uz": "Bani Abbos davlatiga da'vat qiluvchilarning eng kattalaridan biri edi"}], "full_uz": "Uning bobosi — ismi Molik ibn al-Haysam — Bani Abbos davlatiga da'vat qiluvchilarning eng kattalaridan biri edi.", "note": null},
  {"num": 94, "time": "00:07:22,199 --> 00:07:32,060", "arabic": "وَكَانَ أَبُوهُ يَغْشَاهُ أَهْلُ الْحَدِيثِ وَقَدْ بَايَعُوهُ فِي سَنَةِ إِحْدَى وَمِئَتَيْنِ لِلْهِجْرَةِ عَلَى الْقِيَامِ بِالْأَمْرِ بِالْمَعْرُوفِ", "segs": [{"ar": "وَكَانَ أَبُوهُ يَغْشَاهُ أَهْلُ الْحَدِيثِ", "uz": "Otasiga hadis ahli tez-tez kelib turishardi"}, {"ar": "وَقَدْ بَايَعُوهُ فِي سَنَةِ إِحْدَى وَمِئَتَيْنِ لِلْهِجْرَةِ عَلَى الْقِيَامِ بِالْأَمْرِ بِالْمَعْرُوفِ", "uz": "ular hijriy 201-yilda unga ma'rufga buyurishni bajarishga bay'at berishgan"}], "full_uz": "Otasiga hadis ahli tez-tez kelib turishardi — ular hijriy 201-yilda unga ma'rufga buyurishni bajarishga bay'at berishgan.", "note": null},
  {"num": 96, "time": "00:07:32,060 --> 00:07:37,639", "arabic": "وَالنَّهْيِ عَنِ الْمُنْكَرِ حِينَ كَثُرَ الشُّطَّارُ وَالدُّعَّارُ فِي غَيْبَةِ الْمَأْمُونِ عَنْ بَغْدَادَ", "segs": [{"ar": "وَالنَّهْيِ عَنِ الْمُنْكَرِ حِينَ كَثُرَ الشُّطَّارُ وَالدُّعَّارُ", "uz": "Va munkardan qaytarishga — jinoyatchi va bezorilar ko'paygan paytda"}, {"ar": "فِي غَيْبَةِ الْمَأْمُونِ عَنْ بَغْدَادَ", "uz": "al-Ma'mun Bag'dodda yo'q vaqtida"}], "full_uz": "Va munkardan qaytarishga — al-Ma'mun Bag'dodda yo'q vaqtida jinoyatchi va bezorilar ko'paygan paytda.", "note": null},
  {"num": 97, "time": "00:07:37,639 --> 00:07:43,560", "arabic": "إِذَنْ فَهُوَ سَلِيلُ أُسْرَةٍ عَرِيقَةٍ فِي النِّزَاعَاتِ وَلَهُ سِجِلٌّ حَافِلٌ فِي الْمُطَارَحَاتِ", "segs": [{"ar": "إِذَنْ فَهُوَ سَلِيلُ أُسْرَةٍ عَرِيقَةٍ فِي النِّزَاعَاتِ", "uz": "Demak, u nizolarda qadimiy oiladan bo'lgan avlod"}, {"ar": "وَلَهُ سِجِلٌّ حَافِلٌ فِي الْمُطَارَحَاتِ", "uz": "munozaralarda mo'l tajribasi bor"}], "full_uz": "Demak, u nizolarda qadimiy oiladan bo'lgan avlod — va munozaralarda mo'l tajribasi bor.", "note": null},
  {"num": 98, "time": "00:07:43,560 --> 00:07:52,439", "arabic": "أَجَلْ يَا بَاتِرُ، وَلَكِنَّ جَيِّدٌ أَنَّكَ سَتُعْطَى إِخْرَاجَ أَحَدِهِمْ عَنْ صَمْتِهِ", "segs": [{"ar": "أَجَلْ يَا بَاتِرُ", "uz": "Ha, Botir"}, {"ar": "وَلَكِنَّ جَيِّدٌ أَنَّكَ سَتُعْطَى إِخْرَاجَ أَحَدِهِمْ عَنْ صَمْتِهِ", "uz": "ammo yaxshisi, sen ulardan birini sukutdan chiqarish imkoniga ega bo'lasan"}], "full_uz": "Ha, Botir — ammo yaxshisi, sen ulardan birini sukutdan chiqarish imkoniga ega bo'lasan.", "note": null},
  {"num": 100, "time": "00:07:52,439 --> 00:07:59,819", "arabic": "حَتَّى وَلَوْ كَانَ أَحْمَدَ بْنَ نَصْرٍ الْخُزَاعِيَّ، وَهَذَا مَا كُنَّا نَنْتَظِرُهُ مُنْذُ زَمَنٍ", "segs": [{"ar": "حَتَّى وَلَوْ كَانَ أَحْمَدَ بْنَ نَصْرٍ الْخُزَاعِيَّ", "uz": "Hatto u Ahmad ibn Nasr al-Xuzo'iy bo'lsa ham"}, {"ar": "وَهَذَا مَا كُنَّا نَنْتَظِرُهُ مُنْذُ زَمَنٍ", "uz": "Buni ancha vaqtdan beri kutib turgan edik"}], "full_uz": "Hatto u Ahmad ibn Nasr al-Xuzo'iy bo'lsa ham. Buni ancha vaqtdan beri kutib turgan edik.", "note": null},
  {"num": 102, "time": "00:07:59,819 --> 00:08:08,160", "arabic": "وَمَنْ تَرَكَ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ نَاسِيًا حَتَّى صَلَّى ثُمَّ تَذَكَّرَ بَعْدَ أَنْ فَرَغَ مِنْ صَلَاتِهِ", "segs": [{"ar": "وَمَنْ تَرَكَ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ نَاسِيًا حَتَّى صَلَّى", "uz": "Kim mazmaza va istinshoqni unutib qoldirib, namoz o'qisa"}, {"ar": "ثُمَّ تَذَكَّرَ بَعْدَ أَنْ فَرَغَ مِنْ صَلَاتِهِ", "uz": "so'ng namozini tugatgandan keyin eslasa"}], "full_uz": "Kim mazmaza va istinshoqni unutib qoldirib, namoz o'qib, namozini tugatgandan keyin eslasa.", "note": "اَلْمَضْمَضَة — og'izga suv olib chayqash; اَلِاسْتِنْشَاق — burunga suv tortib tozalash — tahoratning sunnatlaridan."},
  {"num": 103, "time": "00:08:08,160 --> 00:08:16,439", "arabic": "عَلَيْهِ أَنْ يَتَوَضَّأَ وَيَتَمَضْمَضَ وَيَسْتَنْشِقَ وَيُعِيدَ الصَّلَاةَ", "segs": null, "full_uz": "U qayta tahorat qilib, mazmaza va istinshoq qilib, namozni qaytadan o'qishi lozim.", "note": null},
  {"num": 105, "time": "00:08:17,360 --> 00:08:25,159", "arabic": "وَمَنْ تَذَكَّرَ وَهُوَ فِي الصَّلَاةِ انْصَرَفَ عَنْهَا وَتَوَضَّأَ وَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ صَلَّى", "segs": [{"ar": "وَمَنْ تَذَكَّرَ وَهُوَ فِي الصَّلَاةِ انْصَرَفَ عَنْهَا", "uz": "Kim namoz ichida esiga tushsa, undan chiqadi"}, {"ar": "وَتَوَضَّأَ وَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ صَلَّى", "uz": "tahorat qilib, mazmaza va istinshoq qilib, so'ng namoz o'qiydi"}], "full_uz": "Kim namoz ichida esiga tushsa, undan chiqib, tahorat qilib, mazmaza va istinshoq qilib, so'ng namoz o'qiydi.", "note": null},
  {"num": 107, "time": "00:08:25,159 --> 00:08:28,859", "arabic": "هِيَ أَنْتَ، مَاذَا تَفْعَلُ؟", "segs": null, "full_uz": "Hoy sen, nima qilyapsan?", "note": null},
  {"num": 108, "time": "00:08:28,859 --> 00:08:29,539", "arabic": "أَنَا يَا شَيْخُ", "segs": null, "full_uz": "Men, shayx.", "note": null},
  {"num": 109, "time": "00:08:29,539 --> 00:08:30,419", "arabic": "هَجَلِ أَنْتَ", "segs": null, "full_uz": "Sen-a?", "note": null},
  {"num": 110, "time": "00:08:30,419 --> 00:08:32,340", "arabic": "أَكْتُبُ مَا قُلْتَ يَا شَيْخُ", "segs": null, "full_uz": "Aytganingizni yozyapman, shayx.", "note": null},
  {"num": 111, "time": "00:08:32,340 --> 00:08:34,399", "arabic": "اِمْحُ مَا كَتَبْتَ عَنِّي يَرْحَمُكَ اللَّهُ", "segs": null, "full_uz": "O'zim haqimda yozganingni o'chir, Alloh senga rahmat qilsin.", "note": null},
  {"num": 112, "time": "00:08:34,399 --> 00:08:41,659", "arabic": "كَمَا تَشَاءُ يَا إِمَامُ، سَأَفْعَلُ، إِخْوَتِي فِي اللَّهِ", "segs": null, "full_uz": "Xohlaganingizdek, Imom, shunday qilaman. Meniing Alloh yo'lidagi birodarlarim.", "note": null},
  {"num": 114, "time": "00:08:41,659 --> 00:08:47,980", "arabic": "قُلْتُهَا لَكُمْ سَابِقًا وَسَأَقُولُهَا الْآنَ، لَا تُقَلِّدُونِي", "segs": null, "full_uz": "Sizga bundan avval aytgan edim va hozir ham aytaman — menga taqlid qilmang.", "note": null},
  {"num": 116, "time": "00:08:47,980 --> 00:08:56,240", "arabic": "وَلَا تُقَلِّدُوا مَالِكًا وَلَا الشَّافِعِيَّةَ وَلَا الْأَوْزَاعِيَّةَ وَلَا الثَّوْرِيَّةَ، بَلْ خُذُوا مِنْ حَيْثُ أَخَذُوا", "segs": [{"ar": "وَلَا تُقَلِّدُوا مَالِكًا وَلَا الشَّافِعِيَّةَ وَلَا الْأَوْزَاعِيَّةَ وَلَا الثَّوْرِيَّةَ", "uz": "Molikka ham, Shofi'iy, Avzoiy va Savriylarga ham taqlid qilmang"}, {"ar": "بَلْ خُذُوا مِنْ حَيْثُ أَخَذُوا", "uz": "balki ular olgan manbadan o'zingiz oling"}], "full_uz": "Molikka ham, Shofi'iy, Avzoiy va Savriylarga ham taqlid qilmang — balki ular olgan manbadan o'zingiz oling.", "note": "Bu — Imom Ahmad ibn Hanbalning taqliddan qaytarib, dalilga ergashishga chaqirgan mashhur so'zlaridan."},
  {"num": 118, "time": "00:08:56,240 --> 00:09:03,899", "arabic": "حَسَنًا أَيُّهَا الْإِخْوَةُ، سَنُعِيدُ مَا بَدَأْنَا بِهِ فِي بِدَايَةِ الدَّرْسِ", "segs": [{"ar": "حَسَنًا أَيُّهَا الْإِخْوَةُ", "uz": "Xo'p, birodarlar"}, {"ar": "سَنُعِيدُ مَا بَدَأْنَا بِهِ فِي بِدَايَةِ الدَّرْسِ", "uz": "darsning boshida boshlagan narsamizni qaytaramiz"}], "full_uz": "Xo'p, birodarlar — darsning boshida boshlagan narsamizni qaytaramiz.", "note": null},
  {"num": 120, "time": "00:09:03,899 --> 00:09:07,000", "arabic": "اِفْتَحُوا قَرَاطِيسَكُمْ", "segs": null, "full_uz": "Qog'ozlaringizni oching.", "note": null},
  {"num": 121, "time": "00:09:17,980 --> 00:09:34,800", "arabic": "كُلُّ ذَلِكَ بِسَبَبِ جَمَاعَتِكَ الْمُعْتَزِلَةِ", "segs": null, "full_uz": "Bularning barchasi sening Mo'tazila jamoating sababidandir.", "note": null},
  {"num": 122, "time": "00:09:34,800 --> 00:09:38,279", "arabic": "أَنْتَ تَتَحَامَلُ عَلَى إِخْوَتِي يَا أَبَا لَيْثٍ", "segs": null, "full_uz": "Sen birodarlarimga tuhmat qilyapsan, Abu Lays.", "note": null},
  {"num": 123, "time": "00:09:38,279 --> 00:09:45,920", "arabic": "أَتَحَامَلُ عَلَيْهِمْ؟ لَوْلَا تَسَلُّطُهُمْ عَلَى الْحُكْمِ وَتَرَدُّدُهُمْ لِكُلِّ مَنْ لَا يَدِينُ بِأَفْكَارِهِمْ", "segs": [{"ar": "أَتَحَامَلُ عَلَيْهِمْ؟", "uz": "Ularga tuhmat qilyapmanmi?"}, {"ar": "لَوْلَا تَسَلُّطُهُمْ عَلَى الْحُكْمِ وَتَرَدُّدُهُمْ لِكُلِّ مَنْ لَا يَدِينُ بِأَفْكَارِهِمْ", "uz": "Agar ular hukmga hukmronlik qilib, o'z fikrlariga qo'shilmagan har kimga qarshi chiqmaganida"}], "full_uz": "Ularga tuhmat qilyapmanmi? Agar ular hukmga hukmronlik qilib, o'z fikrlariga qo'shilmagan har kimga qarshi chiqmaganida.", "note": null},
  {"num": 125, "time": "00:09:45,919 --> 00:09:52,740", "arabic": "لَكُنْتُ الْآنَ عَلَى رَأْسِ عَمَلِي وَلَمْ أَحْتَجْ إِلَى تَدْرِيسِ بِضْعَةِ رِجَالٍ لَا يَفْقَهُونَ إِلَّا قَلِيلًا", "segs": [{"ar": "لَكُنْتُ الْآنَ عَلَى رَأْسِ عَمَلِي", "uz": "Hozir o'z ishim boshida bo'lardim"}, {"ar": "وَلَمْ أَحْتَجْ إِلَى تَدْرِيسِ بِضْعَةِ رِجَالٍ لَا يَفْقَهُونَ إِلَّا قَلِيلًا", "uz": "ozgina anglaydigan bir necha kishiga dars berishga hojatim ham bo'lmasdi"}], "full_uz": "Hozir o'z ishim boshida bo'lardim, ozgina anglaydigan bir necha kishiga dars berishga hojatim ham bo'lmasdi.", "note": null},
  {"num": 127, "time": "00:09:52,740 --> 00:09:59,599", "arabic": "اَلْمُعْتَزِلَةُ لَمْ يَتَسَلَّطُوا عَلَى الْحُكْمِ، بَلْ إِنَّ أَمِيرَ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ", "segs": [{"ar": "اَلْمُعْتَزِلَةُ لَمْ يَتَسَلَّطُوا عَلَى الْحُكْمِ", "uz": "Mo'tazila hukmga hukmron bo'lmagan"}, {"ar": "بَلْ إِنَّ أَمِيرَ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ", "uz": "balki Amir al-Mo'minin, Alloh uni saqlasin"}], "full_uz": "Mo'tazila hukmga hukmron bo'lmagan — balki Amir al-Mo'minin, Alloh uni saqlasin.", "note": null},
  {"num": 129, "time": "00:09:59,599 --> 00:10:04,360", "arabic": "هُوَ الَّذِي قَرَّبَهُمْ إِلَيْهِ بَعْدَ أَنْ نَوَّرَ اللَّهُ بَصِيرَتَهُ وَهَدَاهُ إِلَى الْحَقِّ", "segs": [{"ar": "هُوَ الَّذِي قَرَّبَهُمْ إِلَيْهِ", "uz": "U ularni o'ziga yaqinlashtirgan kishidir"}, {"ar": "بَعْدَ أَنْ نَوَّرَ اللَّهُ بَصِيرَتَهُ وَهَدَاهُ إِلَى الْحَقِّ", "uz": "Alloh uning basiratini yoritib, haqqa hidoyat qilgandan keyin"}], "full_uz": "U — Alloh uning basiratini yoritib, haqqa hidoyat qilgandan keyin ularni o'ziga yaqinlashtirgan kishidir.", "note": null},
  {"num": 130, "time": "00:10:04,360 --> 00:10:11,639", "arabic": "وَرَأَى فِيهِمْ إِخْلَاصًا لَيْسَ لِغَيْرِهِمْ، ثُمَّ أَلَا تَرَى الْفَرْقَ بَيْنَ أَنْ يَكُونَ الْمُعْتَزِلَةُ فِي الْحُكْمِ", "segs": [{"ar": "وَرَأَى فِيهِمْ إِخْلَاصًا لَيْسَ لِغَيْرِهِمْ", "uz": "Va ularda boshqalarda bo'lmagan sadoqatni ko'rgan"}, {"ar": "ثُمَّ أَلَا تَرَى الْفَرْقَ بَيْنَ أَنْ يَكُونَ الْمُعْتَزِلَةُ فِي الْحُكْمِ", "uz": "Yana, Mo'tazila hukmda bo'lishi bilan"}], "full_uz": "Va ularda boshqalarda bo'lmagan sadoqatni ko'rgan. Yana, Mo'tazila hukmda bo'lishi bilan.", "note": null},
  {"num": 132, "time": "00:10:11,639 --> 00:10:15,459", "arabic": "وَبَيْنَ أَنْ يَكُونَ غَيْرُهُمْ؟ نَعَمْ رَأَيْتُ الْفَرْقَ", "segs": null, "full_uz": "boshqasi bo'lishi orasidagi farqni ko'rmaysanmi? Ha, farqni ko'rdim.", "note": null},
  {"num": 134, "time": "00:10:15,460 --> 00:10:21,500", "arabic": "طَرَدُونَا مِنْ أَعْمَالِنَا، وَجَزَاكُمُ اللَّهُ خَيْرًا أَنْ مَنَحْتُمُونَا حَقَّ الْحَيَاةِ وَحَقَّ الْكَلَامِ", "segs": [{"ar": "طَرَدُونَا مِنْ أَعْمَالِنَا", "uz": "Bizni ishlarimizdan quvishdi"}, {"ar": "وَجَزَاكُمُ اللَّهُ خَيْرًا أَنْ مَنَحْتُمُونَا حَقَّ الْحَيَاةِ وَحَقَّ الْكَلَامِ", "uz": "hayot huquqi va gapirish huquqini bergani uchun Alloh sizga yaxshilik bersin"}], "full_uz": "Bizni ishlarimizdan quvishdi — hayot huquqi va gapirish huquqini bergani uchun Alloh sizga yaxshilik bersin.", "note": null},
  {"num": 136, "time": "00:10:21,500 --> 00:10:28,120", "arabic": "ثُمَّ مَنْ قَالَ إِنَّ أَهْلَ الْحَدِيثِ قَدْ طَارَدُوكُمْ", "segs": null, "full_uz": "Yana, hadis ahli sizni ta'qib qilgan deb kim aytdi?", "note": null},
  {"num": 137, "time": "00:10:28,120 --> 00:10:37,440", "arabic": "وَغَلَّبُوا السُّلْطَانَ عَلَيْكُمْ وَقَلَبُوا لَكُمْ ظَهْرَ الْمِجَنِّ، إِنَّ أَهْلَ الْحَدِيثِ أَوْعَى مِنْ حَمَاقَتِكُمْ وَأَعْقَلُ مِنْ جَهَالَتِكُمْ", "segs": [{"ar": "وَغَلَّبُوا السُّلْطَانَ عَلَيْكُمْ وَقَلَبُوا لَكُمْ ظَهْرَ الْمِجَنِّ", "uz": "Va sultonni sizga qarshi qo'ygan hamda sizga qalqonning orqasini o'girgan deb?"}, {"ar": "إِنَّ أَهْلَ الْحَدِيثِ أَوْعَى مِنْ حَمَاقَتِكُمْ وَأَعْقَلُ مِنْ جَهَالَتِكُمْ", "uz": "Hadis ahli sizning ahmoqligingizdan ongliroq, jaholatingizdan aqllirokdir"}], "full_uz": "Va sultonni sizga qarshi qo'ygan hamda sizga qalqonning orqasini o'girgan deb? Hadis ahli sizning ahmoqligingizdan ongliroq, jaholatingizdan aqllirokdir.", "note": "قَلَبَ لَهُ ظَهْرَ الْمِجَنِّ — «unga qalqonning orqasini o'girdi», ya'ni to'satdan dushmanlikka o'tdi ma'nosidagi ibora."},
  {"num": 139, "time": "00:10:37,440 --> 00:10:47,279", "arabic": "إِنَّ الْإِمَامَ الشَّافِعِيَّ عَلَى الرَّغْمِ مِنْ قَرَابَتِهِ لِهَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ إِلَّا أَنَّهُ لَمْ يَحْرِدْ يَوْمًا عَلَيْكُمْ", "segs": [{"ar": "إِنَّ الْإِمَامَ الشَّافِعِيَّ عَلَى الرَّغْمِ مِنْ قَرَابَتِهِ لِهَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "uz": "Imom ash-Shofi'iy Horun ar-Rashidga — Alloh unga rahmat qilsin — qarindosh bo'lsa-da"}, {"ar": "إِلَّا أَنَّهُ لَمْ يَحْرِدْ يَوْمًا عَلَيْكُمْ", "uz": "hech qachon sizlarga qarshi g'azablanmadi"}], "full_uz": "Imom ash-Shofi'iy Horun ar-Rashidga — Alloh unga rahmat qilsin — qarindosh bo'lsa-da, hech qachon sizlarga qarshi g'azablanmadi.", "note": null},
  {"num": 141, "time": "00:10:47,279 --> 00:10:54,799", "arabic": "إِذَنْ مَنِ الَّذِي أَغْرَى الرَّشِيدَ وَابْنَهُ الْأَمِينَ بِالتَّضْيِيقِ عَلَيْنَا؟", "segs": null, "full_uz": "Unda kim ar-Rashid va uning o'g'li al-Aminni bizga tor kelishga qutqidi?", "note": null},
  {"num": 142, "time": "00:10:54,799 --> 00:11:03,659", "arabic": "رُبَّمَا رَأَوْا أَنَّ فِي انْتِشَارِ أَفْكَارِكُمُ الضَّالَّةِ تَفْرِيقًا لِكَلِمَةِ الْمُسْلِمِينَ وَإِفْسَادًا لِدِينِهِمْ وَإِشْغَالَهُمْ بِمَا لَا يَنْفَعُ", "segs": [{"ar": "رُبَّمَا رَأَوْا أَنَّ فِي انْتِشَارِ أَفْكَارِكُمُ الضَّالَّةِ تَفْرِيقًا لِكَلِمَةِ الْمُسْلِمِينَ", "uz": "Balki ular sizning adashgan fikrlaringizning tarqalishida musulmonlar kalimasini bo'linishini ko'rgandirlar"}, {"ar": "وَإِفْسَادًا لِدِينِهِمْ وَإِشْغَالَهُمْ بِمَا لَا يَنْفَعُ", "uz": "dinlarini buzilishini va ularni foydasiz narsa bilan band bo'lishini ko'rgandirlar"}], "full_uz": "Balki ular sizning adashgan fikrlaringizning tarqalishida musulmonlar kalimasini bo'linishini, dinlarini buzilishini va ularni foydasiz narsa bilan band bo'lishini ko'rgandirlar.", "note": null},
  {"num": 144, "time": "00:11:03,659 --> 00:11:09,199", "arabic": "قُلْ لِي بِرَبِّكَ مَا خَوْضُكُمْ فِي عَالَمِ الْغَيْبِ وَأَنْتُمْ لَا تُدْرِكُونَ عِلْمَ الشَّهَادَةِ؟", "segs": [{"ar": "قُلْ لِي بِرَبِّكَ مَا خَوْضُكُمْ فِي عَالَمِ الْغَيْبِ", "uz": "Robbing haqi, ayt-chi, g'ayb olamiga aralashishingiz nima uchun"}, {"ar": "وَأَنْتُمْ لَا تُدْرِكُونَ عِلْمَ الشَّهَادَةِ؟", "uz": "shohidlik ilmini anglamas ekansiz?"}], "full_uz": "Robbing haqi, ayt-chi — shohidlik ilmini anglamas ekansiz, g'ayb olamiga aralashishingiz nima uchun?", "note": null},
  {"num": 145, "time": "00:11:09,199 --> 00:11:12,500", "arabic": "كَفَاكُمْ سَفَهًا وَضَلَالًا يَا رَجُلُ", "segs": null, "full_uz": "Bas qiling, ey odam — bas qiling sabеngiz va adashuvingiz.", "note": null},
  {"num": 146, "time": "00:11:12,500 --> 00:11:26,860", "arabic": "مَا لِي أَرَى لِسَانَكَ قَدْ عَجَزَ عَنِ الْكَلَامِ", "segs": null, "full_uz": "Senga nima bo'ldi — tiling gapdan ojiz qolganini ko'rmoqdaman.", "note": null},
  {"num": 147, "time": "00:11:26,860 --> 00:11:30,139", "arabic": "لَا، لَمْ يَعْجِزْ", "segs": null, "full_uz": "Yo'q, ojiz qolgani yo'q.", "note": null},
  {"num": 148, "time": "00:11:30,139 --> 00:11:34,659", "arabic": "وَلَكِنَّ الْجَدَلَ مَعَ أَخِي الْجَهَالَةِ لَا يَنْفَعُ", "segs": null, "full_uz": "Ammo jaholat birodari bilan bahslashish foyda bermaydi.", "note": null},
  {"num": 149, "time": "00:11:37,059 --> 00:11:43,559", "arabic": "تُذَكِّرُنِي بِأَبْيَاتٍ لِلشَّافِعِيِّ يَقُولُ فِيهَا: يُخَاطِبُنِي السَّفِيهُ بِكُلِّ قُبْحٍ", "segs": null, "full_uz": "Bu menga ash-Shofi'iyning quyidagi baytlarini eslatadi: «Sabeh kishi menga barcha yomonlik bilan murojaat qiladi».", "note": null},
  {"num": 151, "time": "00:11:43,559 --> 00:11:49,819", "arabic": "فَأَكْرَهُ أَنْ أَكُونَ لَهُ مُجِيبًا، أَزِيدُ سَفَاهَةً فَأَزِيدُ حِلْمًا", "segs": null, "full_uz": "Men esa unga javob berishni yomon ko'raman — u sabehligini oshirsa, men halimligimni oshiraman.", "note": null},
  {"num": 153, "time": "00:11:49,819 --> 00:11:52,779", "arabic": "كَعُودٍ زَادَهُ إِحْرَاقًا طِيبًا", "segs": null, "full_uz": "Xuddi yoqilganda ko'proq xushbo'y hid taratadigan ud yog'ochi kabi.", "note": "Bu — Imom ash-Shofi'iyning nafsni tiyish va halimlik haqidagi mashhur she'ridan."},
  {"num": 154, "time": "00:11:52,779 --> 00:12:04,039", "arabic": "لَبَّسَ عَلَيْكَ يَا أَبَا مَعْنٍ", "segs": null, "full_uz": "Senga chalkashlik solibdi, Abu Ma'n.", "note": null},
  {"num": 155, "time": "00:12:04,039 --> 00:12:08,139", "arabic": "لَوْلَا أَنَّ بَدْرًا كَلَاعِيًّا أَخْبَرَنِي أَنَّكَ مُتَوَعِّكٌ", "segs": null, "full_uz": "Agar Badr al-Kala'iy senga nogoron ekaningni aytmaganida.", "note": null},
  {"num": 156, "time": "00:12:08,139 --> 00:12:12,120", "arabic": "لَمَا عَلِمْتُ بِذَلِكَ، اَلْحَمْدُ لِلَّهِ عَلَى أَيِّ حَالٍ", "segs": null, "full_uz": "Bundan xabarim bo'lmasdi. Har holda alhamdulillah.", "note": null},
  {"num": 158, "time": "00:12:12,120 --> 00:12:16,639", "arabic": "اَلْحَمْدُ لِلَّهِ، وَكَيْفَ أَنْتَ الْآنَ بَعْدَ أَنْ رَآكَ الطَّبِيبُ؟", "segs": null, "full_uz": "Alhamdulillah. Tabib ko'rgandan keyin hozir o'zingizni qanday his qilyapsiz?", "note": null},
  {"num": 160, "time": "00:12:18,639 --> 00:12:23,820", "arabic": "اَلْحَقُّ أَقُولُ لَكَ يَا صَاحِبِي أَنَّنِي أَجِدُ نَفْسِي إِلَى نُقْصَانٍ", "segs": [{"ar": "اَلْحَقُّ أَقُولُ لَكَ يَا صَاحِبِي", "uz": "Haqiqatni aytsam, do'stim"}, {"ar": "أَنَّنِي أَجِدُ نَفْسِي إِلَى نُقْصَانٍ", "uz": "o'zimni kuchdan qolayotgandek his qilyapman"}], "full_uz": "Haqiqatni aytsam, do'stim — o'zimni kuchdan qolayotgandek his qilyapman.", "note": null},
  {"num": 161, "time": "00:12:23,820 --> 00:12:29,639", "arabic": "اَلطَّبِيبُ هُوَ اللَّهُ سُبْحَانَهُ، وَنَسْأَلُ اللَّهَ حُسْنَ الْخِتَامِ", "segs": null, "full_uz": "Tabib — bu Alloh subhonahu — Allohdan yaxshi yakun so'raymiz.", "note": null},
  {"num": 163, "time": "00:12:30,179 --> 00:12:34,639", "arabic": "لَا تَقُلْ مِثْلَ هَذَا الْكَلَامِ يَا أَبَا مَعْنٍ، أَمْ تُعَمِّرُ اللَّهُ بِكَ؟", "segs": [{"ar": "لَا تَقُلْ مِثْلَ هَذَا الْكَلَامِ يَا أَبَا مَعْنٍ", "uz": "Bunday gapni aytma, Abu Ma'n"}, {"ar": "أَمْ تُعَمِّرُ اللَّهُ بِكَ؟", "uz": "Alloh sen orqali yashasin demoqchimisan?"}], "full_uz": "Bunday gapni aytma, Abu Ma'n — Alloh sen orqali yashasin demoqchimisan?", "note": null},
  {"num": 164, "time": "00:12:34,639 --> 00:12:44,080", "arabic": "إِنَّمَا عَزَائِي أَنَّنِي رَأَيْتُ كَيْفَ أَعَزَّ اللَّهُ مَذْهَبَنَا", "segs": null, "full_uz": "Faqat taskinim shuki — Alloh mazhabimizni qanday aziz qilganini ko'rdim.", "note": null},
  {"num": 165, "time": "00:12:44,080 --> 00:12:52,919", "arabic": "وَنَصَرَنَا عَلَى أَهْلِ الْكُفْرِ وَالضَّلَالَةِ وَأَنَا حَيٌّ، كُلُّ ذَلِكَ لَمْ يَكُنْ لَوْلَا فَضْلُ اللَّهِ", "segs": [{"ar": "وَنَصَرَنَا عَلَى أَهْلِ الْكُفْرِ وَالضَّلَالَةِ وَأَنَا حَيٌّ", "uz": "Va tirikligimda bizni kufr va zalolat ahliga qarshi g'olib qildi"}, {"ar": "كُلُّ ذَلِكَ لَمْ يَكُنْ لَوْلَا فَضْلُ اللَّهِ", "uz": "bularning barchasi Allohning fazli bo'lmaganida bo'lmasdi"}], "full_uz": "Va tirikligimda bizni kufr va zalolat ahliga qarshi g'olib qildi — bularning barchasi Allohning fazli bo'lmaganida bo'lmasdi.", "note": null},
  {"num": 167, "time": "00:12:52,919 --> 00:12:57,460", "arabic": "ثُمَّ مَا بَذَلْتَهُ مِنْ نُصْحٍ وَإِرْشَادٍ يَا ابْنَ الْأَشْرَسِ", "segs": null, "full_uz": "Yana, siz bergan nasihat va yo'l-yo'riqlar tufayli, Ibn al-Ashras.", "note": null},
  {"num": 168, "time": "00:12:57,460 --> 00:13:06,480", "arabic": "كُلُّكُمْ مُحْسِنٌ يَا أَبَا عَبْدِ الرَّحْمَنِ، وَأَرْجُو أَلَّا يُخَيِّبَ اللَّهُ مَسْعَاكُمْ", "segs": [{"ar": "كُلُّكُمْ مُحْسِنٌ يَا أَبَا عَبْدِ الرَّحْمَنِ", "uz": "Barchangiz ihson qilgansiz, Abu Abd ar-Rahmon"}, {"ar": "وَأَرْجُو أَلَّا يُخَيِّبَ اللَّهُ مَسْعَاكُمْ", "uz": "Alloh sa'yingizni behuda qilmasin deb umid qilaman"}], "full_uz": "Barchangiz ihson qilgansiz, Abu Abd ar-Rahmon — Alloh sa'yingizni behuda qilmasin deb umid qilaman.", "note": null},
  {"num": 170, "time": "00:13:06,480 --> 00:13:16,400", "arabic": "وَلَا يُغَيِّرْ صَدْرَ أَمِيرِ الْمُؤْمِنِينَ عَلَيْكُمْ، فَفَوَاتُ جَنَابِ السُّلْطَانِ ضَيَاعٌ وَخِذْلَانٌ", "segs": [{"ar": "وَلَا يُغَيِّرْ صَدْرَ أَمِيرِ الْمُؤْمِنِينَ عَلَيْكُمْ", "uz": "Va Amir al-Mo'mininning ko'nglini sizga qarshi o'zgartirmasin"}, {"ar": "فَفَوَاتُ جَنَابِ السُّلْطَانِ ضَيَاعٌ وَخِذْلَانٌ", "uz": "sultonning yaqinligidan mahrum bo'lish esa zoye va xor bo'lishdir"}], "full_uz": "Va Amir al-Mo'mininning ko'nglini sizga qarshi o'zgartirmasin — sultonning yaqinligidan mahrum bo'lish esa zoye va xor bo'lishdir.", "note": null},
  {"num": 172, "time": "00:13:16,400 --> 00:13:23,040", "arabic": "لَا تَقُفْ، أَنَا حَرِيصٌ مِنْ هَذِهِ النَّاحِيَةِ، أَعْرِفُ يَا أَبَا عَبْدِ الرَّحْمَنِ أَعْرِفُ", "segs": [{"ar": "لَا تَقُفْ، أَنَا حَرِيصٌ مِنْ هَذِهِ النَّاحِيَةِ", "uz": "Bunga qayg'urmang — men bu tarafdan ehtiyot bo'laman"}, {"ar": "أَعْرِفُ يَا أَبَا عَبْدِ الرَّحْمَنِ أَعْرِفُ", "uz": "Bilaman, Abu Abd ar-Rahmon, bilaman"}], "full_uz": "Bunga qayg'urmang — men bu tarafdan ehtiyot bo'laman. Bilaman, Abu Abd ar-Rahmon, bilaman.", "note": null},
  {"num": 174, "time": "00:13:23,040 --> 00:13:30,300", "arabic": "وَلَكِنْ فِي نَفْسِي أَمْرٌ لَا أُرِيدُ أَنْ أَكْتُمَهُ عَنْكَ، قُلْ فِدَاكَ نَفْسِي", "segs": [{"ar": "وَلَكِنْ فِي نَفْسِي أَمْرٌ لَا أُرِيدُ أَنْ أَكْتُمَهُ عَنْكَ", "uz": "Ammo dilimda sizdan yashirmoqchi bo'lmagan bir gap bor"}, {"ar": "قُلْ فِدَاكَ نَفْسِي", "uz": "Ayting, jonim sizga fido"}], "full_uz": "Ammo dilimda sizdan yashirmoqchi bo'lmagan bir gap bor. Ayting, jonim sizga fido.", "note": null},
  {"num": 176, "time": "00:13:30,299 --> 00:13:45,500", "arabic": "اِسْمَعْ يَا أَبَا لَيْثٍ", "segs": null, "full_uz": "Eshit, Abu Lays.", "note": null},
  {"num": 177, "time": "00:13:45,500 --> 00:13:53,579", "arabic": "أَنْتَ صَدِيقِي وَتَعْرِفُ مَكَانَتَكَ فِي قَلْبِي وَأَعِدُكَ بِأَنَّنِي سَأُكَلِّمُ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ", "segs": [{"ar": "أَنْتَ صَدِيقِي وَتَعْرِفُ مَكَانَتَكَ فِي قَلْبِي", "uz": "Sen mening do'stimsan, qalbimdagi o'rningni bilasan"}, {"ar": "وَأَعِدُكَ بِأَنَّنِي سَأُكَلِّمُ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ", "uz": "va senga va'da beraman, vazir Ibn Abi Duvod bilan gaplashaman"}], "full_uz": "Sen mening do'stimsan, qalbimdagi o'rningni bilasan — va senga va'da beraman, vazir Ibn Abi Duvod bilan gaplashaman.", "note": null},
  {"num": 179, "time": "00:13:53,579 --> 00:14:02,039", "arabic": "كَيْ يُعِيدَكَ إِلَى عَمَلِكَ، جِدْ لِنَفْسِكَ عِنْدَ ابْنِ أَبِي دُؤَادٍ عَمَلًا أَوَّلًا قَبْلَ أَنْ تَتَحَنَّنَ عَلَيَّ", "segs": [{"ar": "كَيْ يُعِيدَكَ إِلَى عَمَلِكَ", "uz": "Seni ishingga qaytarish uchun"}, {"ar": "جِدْ لِنَفْسِكَ عِنْدَ ابْنِ أَبِي دُؤَادٍ عَمَلًا أَوَّلًا", "uz": "avval o'zing Ibn Abi Duvod nazdida ish top"}, {"ar": "قَبْلَ أَنْ تَتَحَنَّنَ عَلَيَّ", "uz": "menga achinishdan oldin"}], "full_uz": "Seni ishingga qaytarish uchun. Menga achinishdan oldin, o'zing Ibn Abi Duvod nazdida ish top.", "note": null},
  {"num": 181, "time": "00:14:02,039 --> 00:14:06,220", "arabic": "مَا أَسْمَجَكَ أَيُّهَا الشَّيْخُ", "segs": null, "full_uz": "Naqadar bema'nisan, shayx.", "note": null},
  {"num": 182, "time": "00:14:06,220 --> 00:14:13,820", "arabic": "أَلَا فَلْتَعْلَمْ أَنَّ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ أَلْحَقَنِي بِعَمَلٍ سَأَكُونُ خِلَالَ أَيَّامٍ عَلَى رَأْسِهِ", "segs": [{"ar": "أَلَا فَلْتَعْلَمْ أَنَّ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ أَلْحَقَنِي بِعَمَلٍ", "uz": "Bilib qo'y — vazir Ibn Abi Duvod meni bir ishga qo'ygan"}, {"ar": "سَأَكُونُ خِلَالَ أَيَّامٍ عَلَى رَأْسِهِ", "uz": "bir necha kundan keyin men uning boshida bo'laman"}], "full_uz": "Bilib qo'y — vazir Ibn Abi Duvod meni bir ishga qo'ygan, bir necha kundan keyin men uning boshida bo'laman.", "note": null},
  {"num": 183, "time": "00:14:13,820 --> 00:14:19,600", "arabic": "عَلَى رَأْسِ ابْنِ أَبِي دُؤَادٍ؟ وَمَا هُوَ هَذَا الْعَمَلُ؟", "segs": null, "full_uz": "Ibn Abi Duvod boshidami? Bu ish nima o'zi?", "note": null},
  {"num": 185, "time": "00:14:19,600 --> 00:14:24,820", "arabic": "أُسْنِدَ إِلَيَّ دِيوَانُ الْحِسْبَةِ، أَحَقٌّ مَا تَقُولُ؟", "segs": null, "full_uz": "Menga hisba devoni topshirildi. Aytganing rostmi?", "note": "دِيوَانُ الْحِسْبَة — bozorlar va jamoat axloqini nazorat qiluvchi davlat idorasi."},
  {"num": 187, "time": "00:14:25,120 --> 00:14:34,120", "arabic": "أَجَلْ، كُنْتُ أُرِيدُ إِخْبَارَكَ وَلَكِنَّكَ أَحْسَنْتَ اسْتِقْبَالِي مُتَذَمِّرًا شَاكِيًا، مَا رَأْيُكَ؟", "segs": [{"ar": "أَجَلْ، كُنْتُ أُرِيدُ إِخْبَارَكَ", "uz": "Ha, senga aytmoqchi edim"}, {"ar": "وَلَكِنَّكَ أَحْسَنْتَ اسْتِقْبَالِي مُتَذَمِّرًا شَاكِيًا، مَا رَأْيُكَ؟", "uz": "ammo sen meni g'ijinib, shikoyat qilib qarshi olding. Fikring qanday?"}], "full_uz": "Ha, senga aytmoqchi edim, ammo sen meni g'ijinib, shikoyat qilib qarshi olding. Fikring qanday?", "note": null},
  {"num": 189, "time": "00:14:34,120 --> 00:14:42,779", "arabic": "هَلْ أُكَلِّمُ الْوَزِيرَ بِشَأْنِكَ؟ وَلَكِنِّي لَسْتُ مِنَ الْمَنْهَجِ وَلَسْتُ مِمَّنْ يَسْتَسِيغُ أَفْكَارَهُمْ", "segs": [{"ar": "هَلْ أُكَلِّمُ الْوَزِيرَ بِشَأْنِكَ؟", "uz": "Vazir bilan sening haqingda gaplashaymi?"}, {"ar": "وَلَكِنِّي لَسْتُ مِنَ الْمَنْهَجِ وَلَسْتُ مِمَّنْ يَسْتَسِيغُ أَفْكَارَهُمْ", "uz": "Ammo men bu yo'nalishdan emasman va ularning fikrlarini yoqtiradiganlardan ham emasman"}], "full_uz": "Vazir bilan sening haqingda gaplashaymi? Ammo men bu yo'nalishdan emasman va ularning fikrlarini yoqtiradiganlardan ham emasman.", "note": null},
  {"num": 191, "time": "00:14:42,779 --> 00:14:48,379", "arabic": "لَا يُهِمُّ، لَا أَحَدَ سَيَسْأَلُكَ عَنْ ذَلِكَ إِنْ لَمْ تُجَاهِرْ بِالْعَدَاوَةِ لِإِخْوَتِنَا", "segs": [{"ar": "لَا يُهِمُّ، لَا أَحَدَ سَيَسْأَلُكَ عَنْ ذَلِكَ", "uz": "Farqi yo'q — hech kim sendan bu haqda so'ramaydi"}, {"ar": "إِنْ لَمْ تُجَاهِرْ بِالْعَدَاوَةِ لِإِخْوَتِنَا", "uz": "birodarlarimizga dushmanlikni oshkor qilmasang"}], "full_uz": "Farqi yo'q — birodarlarimizga dushmanlikni oshkor qilmasang, hech kim sendan bu haqda so'ramaydi.", "note": null},
  {"num": 192, "time": "00:14:48,379 --> 00:14:54,579", "arabic": "وَمَا شَأْنِي بِهِمْ حَتَّى أُجَاهِرَ بِعَدَاوَتِهِمْ؟ جَيِّدٌ", "segs": null, "full_uz": "Ularga qanday aloqam bor, dushmanligimni oshkor qilishga? Yaxshi.", "note": null},
  {"num": 194, "time": "00:14:54,579 --> 00:15:00,620", "arabic": "هَذَا هُوَ الْمَطْلُوبُ، لَا تُرَدِّدْ مَا يَقُولُهُ الْغَوْغَاءُ عَنَّا", "segs": null, "full_uz": "Talab qilingani shu — biz haqimizda ommaning aytadigan gapini takrorlama.", "note": null},
  {"num": 196, "time": "00:15:00,620 --> 00:15:08,539", "arabic": "وَلَنْ يَعْتَرِضَ طَرِيقَكَ أَحَدٌ، وَأَنَا أَعِدُكَ بِأَنْ أُكَلِّمَ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ فِي شَأْنِكَ", "segs": [{"ar": "وَلَنْ يَعْتَرِضَ طَرِيقَكَ أَحَدٌ", "uz": "Va yo'lingga hech kim to'siq bo'lmaydi"}, {"ar": "وَأَنَا أَعِدُكَ بِأَنْ أُكَلِّمَ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ فِي شَأْنِكَ", "uz": "men senga vazir Ibn Abi Duvod bilan sening haqingda gaplashishga va'da beraman"}], "full_uz": "Va yo'lingga hech kim to'siq bo'lmaydi — men senga vazir Ibn Abi Duvod bilan sening haqingda gaplashishga va'da beraman.", "note": null},
  {"num": 198, "time": "00:15:08,539 --> 00:15:17,639", "arabic": "مَا هِيَ أَحْوَالُ الرَّعِيَّةِ يَا أَبَا الْعَبَّاسِ؟ إِنَّهُمْ عَلَى مَا يُحِبُّ مَوْلَايَ وَيَرْضَى", "segs": [{"ar": "مَا هِيَ أَحْوَالُ الرَّعِيَّةِ يَا أَبَا الْعَبَّاسِ؟", "uz": "Raiyat ahvoli qanday, Abu al-Abbos?"}, {"ar": "إِنَّهُمْ عَلَى مَا يُحِبُّ مَوْلَايَ وَيَرْضَى", "uz": "Ular xo'jayinim sevadigan va rozi bo'ladigan holatda"}], "full_uz": "Raiyat ahvoli qanday, Abu al-Abbos? Ular xo'jayinim sevadigan va rozi bo'ladigan holatda.", "note": null},
  {"num": 200, "time": "00:15:17,639 --> 00:15:21,639", "arabic": "عَلَى أَنَّ هُنَاكَ بَعْضَ التَّذَمُّرِ يَا مَوْلَايَ، تَذَمُّرٌ؟", "segs": null, "full_uz": "Ammo bir oz g'ing'illash bor, xo'jayinim. G'ing'illashmi?", "note": null},
  {"num": 202, "time": "00:15:22,419 --> 00:15:28,599", "arabic": "وَمِمَّاذَا التَّذَمُّرُ؟ بَعْضُ الْفُقَهَاءِ وَأَهْلِ الْحَدِيثِ خَاصَّةً", "segs": null, "full_uz": "Nimadan g'ing'illashmoqda? Ayniqsa ba'zi fuqaho va hadis ahli.", "note": null},
  {"num": 204, "time": "00:15:28,599 --> 00:15:32,539", "arabic": "لَمْ يُعْجِبْهُمْ أَنْ نُجَاهِرَ بِمُعْتَقَدَاتِنَا وَآرَائِنَا عَلَى رُءُوسِ الْأَشْهَادِ", "segs": null, "full_uz": "Ularga aqidalarimiz va fikrlarimizni ochiq-oydin izhor qilishimiz yoqmadi.", "note": null},
  {"num": 205, "time": "00:15:32,539 --> 00:15:43,599", "arabic": "أَيُّ عُقُولٍ تِلْكَ؟ أَلَا يَجْدُرُ بِهِمْ أَنْ يَحْمَدُوا اللَّهَ عَلَى أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَمَحَ لَهُمْ بِالْمُجَاهَرَةِ بِمُعْتَقَدَاتِهِمُ الْفَاسِدَةِ؟", "segs": [{"ar": "أَيُّ عُقُولٍ تِلْكَ؟", "uz": "Bu qanday aqllar o'zi?"}, {"ar": "أَلَا يَجْدُرُ بِهِمْ أَنْ يَحْمَدُوا اللَّهَ عَلَى أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَمَحَ لَهُمْ بِالْمُجَاهَرَةِ بِمُعْتَقَدَاتِهِمُ الْفَاسِدَةِ؟", "uz": "Amir al-Mo'minin ularga o'z buzuq e'tiqodlarini ochiq izhor qilishga ruxsat berganidan Allohga hamd aytishlari kerak emasmi?"}], "full_uz": "Bu qanday aqllar o'zi? Amir al-Mo'minin ularga o'z buzuq e'tiqodlarini ochiq izhor qilishga ruxsat berganidan Allohga hamd aytishlari kerak emasmi?", "note": null},
  {"num": 208, "time": "00:15:44,159 --> 00:15:49,599", "arabic": "أَيُّ لَا مُصَاحَبَ الْحَقِّ عَلَى إِظْهَارِهِ يَا أَبَا الْعَبَّاسِ؟ وَمِمَّنْ؟ مِمَّنْ هُمْ أَقْرَبُ إِلَى الضَّلَالَةِ؟", "segs": [{"ar": "أَيُّ لَا مُصَاحَبَ الْحَقِّ عَلَى إِظْهَارِهِ يَا أَبَا الْعَبَّاسِ؟", "uz": "Haqni izhor qilishga qaysi safdosh yo'q, Abu al-Abbos?"}, {"ar": "وَمِمَّنْ؟ مِمَّنْ هُمْ أَقْرَبُ إِلَى الضَّلَالَةِ؟", "uz": "Va kimdan? Zalolatga yaqinroq bo'lganlardanmi?"}], "full_uz": "Haqni izhor qilishga qaysi safdosh yo'q, Abu al-Abbos? Va kimdan? Zalolatga yaqinroq bo'lganlardanmi?", "note": null},
  {"num": 210, "time": "00:15:49,600 --> 00:15:58,540", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، قُلْ لِي مَاذَا عَنْ أَصْحَابِكَ الْمُعْتَزِلَةِ؟", "segs": [{"ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "uz": "La havla va la quvvata illa billah"}, {"ar": "قُلْ لِي مَاذَا عَنْ أَصْحَابِكَ الْمُعْتَزِلَةِ؟", "uz": "Ayt-chi, Mo'tazila do'stlaring haqida nima deysan?"}], "full_uz": "La havla va la quvvata illa billah. Ayt-chi, Mo'tazila do'stlaring haqida nima deysan?", "note": null},
  {"num": 212, "time": "00:15:58,540 --> 00:16:07,200", "arabic": "إِنَّهُمْ يَرْتَعُونَ فِي نِعْمَةِ أَمِيرِ الْمُؤْمِنِينَ وَيَنْعَمُونَ بِرَاحَةِ الْبَالِ، وَلَا تَزِدْهُمْ يَا مَوْلَايَ إِلَّا سَعْيًا فِي دَعْوَتِهِمْ", "segs": [{"ar": "إِنَّهُمْ يَرْتَعُونَ فِي نِعْمَةِ أَمِيرِ الْمُؤْمِنِينَ وَيَنْعَمُونَ بِرَاحَةِ الْبَالِ", "uz": "Ular Amir al-Mo'mininning ne'matida o'ynab, ko'ngil xotirjamligidan bahramand"}, {"ar": "وَلَا تَزِدْهُمْ يَا مَوْلَايَ إِلَّا سَعْيًا فِي دَعْوَتِهِمْ", "uz": "xo'jayinim, ularga faqat o'z da'vatlarida g'ayrat qo'shing"}], "full_uz": "Ular Amir al-Mo'mininning ne'matida o'ynab, ko'ngil xotirjamligidan bahramand — xo'jayinim, ularga faqat o'z da'vatlarida g'ayrat qo'shing.", "note": null},
  {"num": 214, "time": "00:16:07,200 --> 00:16:12,620", "arabic": "وَدَأَبًا فِي نَشْرِ عَقِيدَتِهِمْ وَمَذْهَبِهِمْ، لَعَلَّهُمْ يَتَذَمَّرُونَ أَيْضًا", "segs": null, "full_uz": "Va aqida hamda mazhablarini tarqatishda tinim bermang. Balki ular ham g'ing'illar.", "note": null},
  {"num": 216, "time": "00:16:12,620 --> 00:16:16,960", "arabic": "قَوْلُكَ حَقٌّ يَا مَوْلَايَ، إِنَّ رِضَا النَّاسِ غَايَةٌ لَا تُدْرَكُ", "segs": [{"ar": "قَوْلُكَ حَقٌّ يَا مَوْلَايَ", "uz": "Gapingiz haq, xo'jayinim"}, {"ar": "إِنَّ رِضَا النَّاسِ غَايَةٌ لَا تُدْرَكُ", "uz": "odamlarning roziligi yetib bo'lmaydigan maqsaddir"}], "full_uz": "Gapingiz haq, xo'jayinim — odamlarning roziligi yetib bo'lmaydigan maqsaddir.", "note": null},
  {"num": 218, "time": "00:16:16,960 --> 00:16:26,240", "arabic": "أَنَا أَعْلَمُ مَا يُرِيدُونَ يَا أَبَا الْعَبَّاسِ، يُرِيدُونَ مِنِّي أَنْ أُضَيِّقَ عَلَى الْفُقَهَاءِ وَأَهْلِ الْحَدِيثِ", "segs": [{"ar": "أَنَا أَعْلَمُ مَا يُرِيدُونَ يَا أَبَا الْعَبَّاسِ", "uz": "Ular nima istayotganini bilaman, Abu al-Abbos"}, {"ar": "يُرِيدُونَ مِنِّي أَنْ أُضَيِّقَ عَلَى الْفُقَهَاءِ وَأَهْلِ الْحَدِيثِ", "uz": "mendan fuqaho va hadis ahliga tor kelishimni istashadi"}], "full_uz": "Ular nima istayotganini bilaman, Abu al-Abbos — mendan fuqaho va hadis ahliga tor kelishimni istashadi.", "note": null},
  {"num": 220, "time": "00:16:26,240 --> 00:16:31,379", "arabic": "إِنَّ الْأَمِيرَ أَدْرَى بِمَا يَكُونُ وَمَا يَجِبُ أَنْ يَكُونَ", "segs": null, "full_uz": "Amir nima bo'lishi va nima bo'lishi lozimligini yaxshiroq biladi.", "note": null},
  {"num": 222, "time": "00:16:31,379 --> 00:16:37,460", "arabic": "مَاذَا تَقْصِدُ يَا أَبَا الْعَبَّاسِ؟", "segs": null, "full_uz": "Nimani nazarda tutyapsan, Abu al-Abbos?", "note": null},
  {"num": 223, "time": "00:16:37,460 --> 00:16:43,860", "arabic": "ثَمَّةَ أُمُورٌ تَجْرِي لِأَطْمَئِنَّ لَهَا، وَلَكِنَّنِي سَأُؤَجِّلُ نَقْلَهَا إِلَى مَوْلَايَ حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهَا", "segs": [{"ar": "ثَمَّةَ أُمُورٌ تَجْرِي لِأَطْمَئِنَّ لَهَا", "uz": "Bir qancha voqealar bo'layapti, ularga ishonch hosil qilmoqchiman"}, {"ar": "وَلَكِنَّنِي سَأُؤَجِّلُ نَقْلَهَا إِلَى مَوْلَايَ حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهَا", "uz": "ammo ularning to'g'riligiga aminmaguncha, xo'jayinimga yetkazishni kechiktiraman"}], "full_uz": "Bir qancha voqealar bo'layapti, ularga ishonch hosil qilmoqchiman — ammo ularning to'g'riligiga aminmaguncha, xo'jayinimga yetkazishni kechiktiraman.", "note": null},
  {"num": 225, "time": "00:16:43,860 --> 00:16:48,580", "arabic": "أَيَجْدُرُ بِمَوْلَاكَ الْقَلَقُ يَا أَبَا الْعَبَّاسِ؟", "segs": null, "full_uz": "Xo'jayiningizga xavotirlanish yarashadimi, Abu al-Abbos?", "note": null},
  {"num": 226, "time": "00:16:48,580 --> 00:16:52,360", "arabic": "لَا أَقْلَقَ اللَّهُ رَاحَةَ مَوْلَايَ، إِنَّمَا الْقَلَقُ شَأْنُنَا", "segs": null, "full_uz": "Alloh xo'jayinimning xotirjamligini bezovta qilmasin — xavotirlanish bizning ishimizdir.", "note": null},
  {"num": 228, "time": "00:16:52,360 --> 00:16:57,600", "arabic": "وَلَكِنِ اعْذُرْنِي يَا مَوْلَايَ عَنِ الْإِدْلَاءِ بِشَيْءٍ حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهِ", "segs": [{"ar": "وَلَكِنِ اعْذُرْنِي يَا مَوْلَايَ عَنِ الْإِدْلَاءِ بِشَيْءٍ", "uz": "Ammo, xo'jayinim, biror narsa aytmasligimni ma'zur tuting"}, {"ar": "حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهِ", "uz": "to'g'riligiga aminmaguncha"}], "full_uz": "Ammo, xo'jayinim, to'g'riligiga aminmaguncha biror narsa aytmasligimni ma'zur tuting.", "note": null},
  {"num": 230, "time": "00:17:03,180 --> 00:17:04,099", "arabic": "تَقَبَّلَ اللَّهُ", "segs": null, "full_uz": "Alloh qabul qilsin.", "note": null},
  {"num": 231, "time": "00:17:04,099 --> 00:17:05,380", "arabic": "مَا بِكَ؟ أَخْبِرْنِي", "segs": null, "full_uz": "Senga nima bo'ldi? Ayt menga.", "note": null},
  {"num": 232, "time": "00:17:05,380 --> 00:17:26,380", "arabic": "أَلَمْ أَخَلْكُمْ إِنَّهُ يَبِيعُكُمْ لِلْمَأْمُونِ؟", "segs": null, "full_uz": "Sizlarga aytmaganmidim — u sizlarni al-Ma'munga sotib qo'yayotganini?", "note": null},
  {"num": 233, "time": "00:17:26,380 --> 00:17:33,720", "arabic": "أَعْرِفُ أَمْثَالَ هَؤُلَاءِ، مِمَّنْ يُخْفُونَ وَرَاءَ الِابْتِسَامَةِ خُبْثًا زُعَافًا", "segs": null, "full_uz": "Bunday kishilarni tanimayman deb o'ylaysanmi — tabassum ortida achchiq yovuzlikni yashiradiganlarni.", "note": "زُعَاف — juda achchiq, kuchli zaharga o'xshash yovuzlik."},
  {"num": 235, "time": "00:17:33,720 --> 00:17:41,000", "arabic": "هَؤُلَاءِ الَّذِينَ يَسْعَوْنَ وَرَاءَ الدُّنْيَا لَا يَرْدَعُهُمْ دِينٌ وَلَا ضَمِيرٌ", "segs": [{"ar": "هَؤُلَاءِ الَّذِينَ يَسْعَوْنَ وَرَاءَ الدُّنْيَا", "uz": "Dunyoni quvib yuradigan bunday kishilarni"}, {"ar": "لَا يَرْدَعُهُمْ دِينٌ وَلَا ضَمِيرٌ", "uz": "na din, na vijdon to'sa oladi"}], "full_uz": "Dunyoni quvib yuradigan bunday kishilarni na din, na vijdon to'sa oladi.", "note": null},
  {"num": 237, "time": "00:17:41,000 --> 00:17:45,120", "arabic": "مَعَكَ حَقٌّ، مَعَكَ حَقٌّ، لَيْسَ ذَلِكَ مَا يَشْغَلُونَ الْآنَ", "segs": null, "full_uz": "Haqsan, haqsan — hozir ularni band qilayotgan narsa bu emas.", "note": null},
  {"num": 239, "time": "00:17:45,120 --> 00:17:48,819", "arabic": "قُلْ لِي مَا الْعَمَلُ، وَتَسْأَلُ مَا الْعَمَلُ", "segs": null, "full_uz": "Ayt menga, nima qilish kerak. Sen esa nima qilish kerakligini so'raysan.", "note": null},
  {"num": 241, "time": "00:17:48,819 --> 00:18:33,700", "arabic": "مَنْ يَقِفُ عُقْبَةً فِي طَرِيقِنَا يُسْتَأْصَلُ، تُقْضَى", "segs": null, "full_uz": "Yo'limizda to'siq bo'lgan kishi ildizidan qo'porib tashlanadi — bitiriladi.", "note": null},
  {"num": 245, "time": "00:18:33,720 --> 00:18:46,160", "arabic": "لَا بُدَّ أَنَّ اللُّصُوصَ قَتَلُوهُ طَمَعًا فِي مَالِهِ", "segs": null, "full_uz": "Uni albatta o'g'rilar moliga ko'z tikib o'ldirishgan bo'lsa kerak.", "note": null},
  {"num": 246, "time": "00:18:46,160 --> 00:18:53,279", "arabic": "أُولَئِكَ الْعَيَّارُونَ يُحِبُّونَ الْمَالَ حُبَّ قَارُونَ وَيَتَعَطَّشُونَ لِلدَّمِ", "segs": [{"ar": "أُولَئِكَ الْعَيَّارُونَ يُحِبُّونَ الْمَالَ حُبَّ قَارُونَ", "uz": "O'sha bezorilar molni Qorun sevganidek sevishadi"}, {"ar": "وَيَتَعَطَّشُونَ لِلدَّمِ", "uz": "va qonga tashna bo'lishadi"}], "full_uz": "O'sha bezorilar molni Qorun sevganidek sevib, qonga tashna bo'lishadi.", "note": "قَارُون (Qorun) — Qur'onda o'z boyligi bilan mashhur bo'lgan, undan darsdek eslatiladigan shaxs."},
  {"num": 249, "time": "00:18:53,279 --> 00:19:01,400", "arabic": "كَمَا قَابَلَ، لَا أَظُنُّ ذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Shu tarzda uchrashganidek. Bunday deb o'ylamayman, Ibn Abi Duvod.", "note": null},
  {"num": 251, "time": "00:19:01,400 --> 00:19:08,580", "arabic": "إِذَنْ مَاذَا يَظُنُّ مَوْلَايَ؟", "segs": null, "full_uz": "Unda xo'jayinim nima deb o'ylaydi?", "note": null},
  {"num": 252, "time": "00:19:08,580 --> 00:19:13,880", "arabic": "أَظُنُّ أَنَّهُ أَمْرٌ دُبِّرَ بِلَيْلٍ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "O'ylashimcha, bu tunda tayyorlangan bir tadbir, Ibn Abi Duvod.", "note": null},
  {"num": 253, "time": "00:19:13,880 --> 00:19:21,540", "arabic": "وَأَنَّ مَنْ أَرَادَ قَتْلَ أَبِي الْعَبَّاسِ إِنَّمَا أَرَادَ أَنْ يُقْبَرَ مَعَهُ سِرٌّ كَبِيرٌ", "segs": [{"ar": "وَأَنَّ مَنْ أَرَادَ قَتْلَ أَبِي الْعَبَّاسِ", "uz": "Abu al-Abbosni o'ldirmoqchi bo'lgan kishi"}, {"ar": "إِنَّمَا أَرَادَ أَنْ يُقْبَرَ مَعَهُ سِرٌّ كَبِيرٌ", "uz": "u bilan birga katta bir sirni ham dafn qilishni istagan"}], "full_uz": "Abu al-Abbosni o'ldirmoqchi bo'lgan kishi, u bilan birga katta bir sirni ham dafn qilishni istagan.", "note": null},
  {"num": 255, "time": "00:19:21,540 --> 00:19:29,500", "arabic": "إِنْ شَاءَ مَوْلَايَ، مَا حُصِّنَ الْأَمْرُ حَتَّى نَقِفَ عَلَى حَقِيقَتِهِ", "segs": [{"ar": "إِنْ شَاءَ مَوْلَايَ", "uz": "Xo'jayinim xohlasa"}, {"ar": "مَا حُصِّنَ الْأَمْرُ حَتَّى نَقِفَ عَلَى حَقِيقَتِهِ", "uz": "ish hali mustahkamlanmagan, toki uning haqiqatini bilib olamiz"}], "full_uz": "Xo'jayinim xohlasa, ish hali mustahkamlanmagan, toki uning haqiqatini bilib olamiz.", "note": null},
  {"num": 257, "time": "00:19:29,500 --> 00:19:38,940", "arabic": "فَنَرْدَعَ مُرْتَكِبَهُ بِمَا يَسْتَحِقُّ مِنَ الْعِقَابِ، مُرْنِي يَا أَمِيرَ الْمُؤْمِنِ", "segs": [{"ar": "فَنَرْدَعَ مُرْتَكِبَهُ بِمَا يَسْتَحِقُّ مِنَ الْعِقَابِ", "uz": "Va uni sodir etganni loyiq jazosi bilan to'xtatamiz"}, {"ar": "مُرْنِي يَا أَمِيرَ الْمُؤْمِنِ", "uz": "Buyuring, Amir al-Mo'minin"}], "full_uz": "Va uni sodir etganni loyiq jazosi bilan to'xtatamiz. Buyuring, Amir al-Mo'minin.", "note": null},
  {"num": 259, "time": "00:19:38,940 --> 00:19:45,940", "arabic": "لَا يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Yo'q, Ibn Abi Duvod.", "note": null},
  {"num": 260, "time": "00:19:45,940 --> 00:19:52,799", "arabic": "دَعِ الْأُمُورَ تَجْرِي بِقَدَرِهَا، رَحِمَ اللَّهُ أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Ishlarni o'z taqdiri bilan yurishiga qo'y. Alloh Abu al-Abbosga rahmat qilsin.", "note": null},
  {"num": 262, "time": "00:19:52,799 --> 00:20:29,480", "arabic": "رَحَلَ بِسِرِّهِ", "segs": null, "full_uz": "U o'z siri bilan bu dunyodan ketdi.", "note": null},
  {"num": 264, "time": "00:20:29,480 --> 00:20:31,480", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 265, "time": "00:20:34,480 --> 00:20:36,480", "arabic": "مَا وَرَاءَكَ يَا ابْنَ نُوحٍ؟", "segs": null, "full_uz": "Xabaring nima, Ibn Nuh?", "note": null},
  {"num": 266, "time": "00:20:38,480 --> 00:20:41,480", "arabic": "أَحْسَنَ اللَّهُ عَزَاءَكَ فِي أَبِي عَبْدِ اللَّهِ", "segs": null, "full_uz": "Alloh Abu Abdulloh haqidagi ta'ziyangizni go'zal qilsin.", "note": null},
  {"num": 267, "time": "00:20:41,480 --> 00:20:43,480", "arabic": "مُحَمَّدِ بْنِ إِدْرِيسَ الشَّافِعِيِّ", "segs": null, "full_uz": "Muhammad ibn Idris ash-Shofi'iy.", "note": null},
  {"num": 268, "time": "00:20:46,480 --> 00:20:48,480", "arabic": "فَقَدْ وَصَلَتْنَا الْأَخْبَارُ مِنْ مِصْرَ", "segs": null, "full_uz": "Bizga Misrdan xabar yetib keldi.", "note": null},
  {"num": 269, "time": "00:20:48,480 --> 00:20:50,480", "arabic": "أَنَّ الْمَنِيَّةَ قَدْ وَفَدَتْ", "segs": null, "full_uz": "Ajal yetib kelgani haqida.", "note": null},
  {"num": 270, "time": "00:20:54,480 --> 00:20:56,480", "arabic": "حَسْبِيَ اللَّهُ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Menga Alloh yetarli, Ibn Nuh.", "note": null},
  {"num": 271, "time": "00:20:59,480 --> 00:22:59,460", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": null},
  {"num": 275, "time": "00:22:59,480 --> 00:23:15,599", "arabic": "يَوْمٌ صَالِحٌ، يَوْمٌ صَالِحٌ", "segs": null, "full_uz": "Solih kuni, Solih kuni.", "note": "Bu yerda \"صالح\" so'zi bilan o'g'il ismi \"Solih\" o'rtasidagi so'z o'yiniga ishora bo'lishi mumkin."},
  {"num": 277, "time": "00:23:15,599 --> 00:23:21,599", "arabic": "نَحْنُ ذَاهِبُونَ إِنْ شَاءَ اللَّهُ، أَتُرِيدِينَ شَيْئًا؟ أَسَيَخْرُجُ مَعَكَ وَلَدُنَا صَالِحٌ؟", "segs": [{"ar": "نَحْنُ ذَاهِبُونَ إِنْ شَاءَ اللَّهُ، أَتُرِيدِينَ شَيْئًا؟", "uz": "Alloh xohlasa, ketyapmiz. Biror narsa kerakmi?"}, {"ar": "أَسَيَخْرُجُ مَعَكَ وَلَدُنَا صَالِحٌ؟", "uz": "O'g'limiz Solih ham sen bilan chiqadimi?"}], "full_uz": "Alloh xohlasa, ketyapmiz. Biror narsa kerakmi? O'g'limiz Solih ham sen bilan chiqadimi?", "note": null},
  {"num": 279, "time": "00:23:21,599 --> 00:23:24,180", "arabic": "سَيَصْحَبُنِي فِي طَرِيقِي إِلَى حَلْقَةِ شَيْخِهِ", "segs": null, "full_uz": "U men bilan shayxining darsxonasiga qadar hamroh bo'ladi.", "note": null},
  {"num": 280, "time": "00:23:24,180 --> 00:23:28,900", "arabic": "لَنْ تُفْلِتَ إِذَنْ مِنْ يَدِ أَبِيكَ يَا صَالِحُ، وَلَنْ تَذْهَبَ إِلَى أَيِّ مَكَانٍ", "segs": [{"ar": "لَنْ تُفْلِتَ إِذَنْ مِنْ يَدِ أَبِيكَ يَا صَالِحُ", "uz": "Unda otangning qo'lidan qutulolmaysan, Solih"}, {"ar": "وَلَنْ تَذْهَبَ إِلَى أَيِّ مَكَانٍ", "uz": "va hech qayerga bormaysan"}], "full_uz": "Unda otangning qo'lidan qutulolmaysan, Solih, va hech qayerga bormaysan.", "note": null},
  {"num": 282, "time": "00:23:28,900 --> 00:23:32,280", "arabic": "إِلَّا إِلَى الْحَلْقَةِ، اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Faqat darsxonaga. Assalomu alaykum.", "note": null},
  {"num": 284, "time": "00:23:32,280 --> 00:23:34,780", "arabic": "فِي حِفْظِ اللَّهِ وَرِعَايَتِهِ", "segs": null, "full_uz": "Allohning himoyasi va nazoratida bo'ling.", "note": null},
  {"num": 285, "time": "00:23:34,780 --> 00:23:48,360", "arabic": "أَيُّهَا الْوَافِدُ", "segs": null, "full_uz": "Ey kelgan mehmon.", "note": null},
  {"num": 286, "time": "00:23:48,360 --> 00:23:52,240", "arabic": "إِنَّ السِّنِينَ قَدْ نَالَتْ مِنْ عَمِّكَ كَمَا تَرَى", "segs": null, "full_uz": "Yillar amakingga ta'sir qilgan, ko'rib turganingdek.", "note": null},
  {"num": 287, "time": "00:23:52,240 --> 00:23:56,640", "arabic": "فِي ذَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ، إِنَّكَ أَفْتُ مِنْ أَنْ تَقُولَ ذَلِكَ", "segs": [{"ar": "فِي ذَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ", "uz": "Jonim shunga fido, Amir al-Mo'minin"}, {"ar": "إِنَّكَ أَفْتُ مِنْ أَنْ تَقُولَ ذَلِكَ", "uz": "Buni aytish sizga yarashmaydi"}], "full_uz": "Jonim shunga fido, Amir al-Mo'minin. Buni aytish sizga yarashmaydi.", "note": null},
  {"num": 289, "time": "00:23:56,640 --> 00:24:01,500", "arabic": "وَأَعْلَمُ أَنَّكَ لَوْ شَهَرْتَ سَيْفَكَ الْآنَ لَفَرَّ مِنْكَ أَبْنَاءُ الْمَعَارِكِ", "segs": [{"ar": "وَأَعْلَمُ أَنَّكَ لَوْ شَهَرْتَ سَيْفَكَ الْآنَ", "uz": "Bilamanki, hozir qilichingizni sug'ursangiz"}, {"ar": "لَفَرَّ مِنْكَ أَبْنَاءُ الْمَعَارِكِ", "uz": "jang farzandlari ham sizdan qochib ketardi"}], "full_uz": "Bilamanki, hozir qilichingizni sug'ursangiz, jang farzandlari ham sizdan qochib ketardi.", "note": null},
  {"num": 290, "time": "00:24:01,500 --> 00:24:10,780", "arabic": "عَمُّكَ الْآنَ شَيْخٌ هَارِمٌ مَرِيضٌ مُتْعَبٌ، أَلَا قُلْ لِي مَا الْأَخْبَارُ عَنْ أَبِيكَ؟", "segs": [{"ar": "عَمُّكَ الْآنَ شَيْخٌ هَارِمٌ مَرِيضٌ مُتْعَبٌ", "uz": "Amaking endi qarigan, kasal, charchagan bir chol"}, {"ar": "أَلَا قُلْ لِي مَا الْأَخْبَارُ عَنْ أَبِيكَ؟", "uz": "Ayt-chi, otang haqida yangiliklar bormi?"}], "full_uz": "Amaking endi qarigan, kasal, charchagan bir chol. Ayt-chi, otang haqida yangiliklar bormi?", "note": null},
  {"num": 292, "time": "00:24:10,780 --> 00:24:16,500", "arabic": "بَعَثْتُ إِلَى أَبِي أُخْبِرُهُ عَنْ مَرَضِ أَمِيرِ الْمُؤْمِنِينَ، وَكَانَ اللَّهُ فِي عَوْنِهِ إِنْ عَلِمَ ذَلِكَ", "segs": [{"ar": "بَعَثْتُ إِلَى أَبِي أُخْبِرُهُ عَنْ مَرَضِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Otamga xat yubordim, Amir al-Mo'mininning kasalligi haqida xabar berdim"}, {"ar": "وَكَانَ اللَّهُ فِي عَوْنِهِ إِنْ عَلِمَ ذَلِكَ", "uz": "buni bilsa, Alloh unga yordamchi bo'lsin"}], "full_uz": "Otamga xat yubordim, Amir al-Mo'mininning kasalligi haqida xabar berdim — buni bilsa, Alloh unga yordamchi bo'lsin.", "note": null},
  {"num": 294, "time": "00:24:16,500 --> 00:24:22,680", "arabic": "حَفِظَكَ اللَّهُ يَا ابْنَ أَخِي وَأَبْقَى أَبَاكَ", "segs": null, "full_uz": "Alloh seni asrasin, jiyanim, va otangni omon saqlasin.", "note": null},
  {"num": 295, "time": "00:24:22,680 --> 00:24:27,080", "arabic": "عِشْقُهُ لِلثُّغُورِ حَرَمَهُ مِنْ أَكْثَرِ مَتَاعِ الْحَيَاةِ", "segs": null, "full_uz": "Chegaralarga bo'lgan ishqi uni hayotning ko'p ne'matlaridan mahrum qildi.", "note": null},
  {"num": 296, "time": "00:24:27,080 --> 00:24:31,680", "arabic": "مَوْلَايَ، أَمَا زِلْتَ تُعَانِي مِنْ مَرَضِكَ؟", "segs": null, "full_uz": "Xo'jayinim, hali ham kasalligingizdan aziyat chekyapsizmi?", "note": null},
  {"num": 297, "time": "00:24:33,380 --> 00:24:36,680", "arabic": "إِنَّ مَرَضِي يَزْدَادُ يَوْمًا بَعْدَ يَوْمٍ يَا ابْنَ أَخِي", "segs": null, "full_uz": "Kasalligim kundan-kunga ortmoqda, jiyanim.", "note": null},
  {"num": 298, "time": "00:24:36,680 --> 00:24:46,560", "arabic": "لَمْ أَسْأَلْ أَحَدًا عَنْهُ إِلَّا وَمَدَحَهُ كَثِيرًا", "segs": null, "full_uz": "Undan so'ragan har kim uni ko'p maqtadi.", "note": null},
  {"num": 299, "time": "00:24:46,560 --> 00:24:52,299", "arabic": "هُوَ رَجُلٌ مَيْسُورُ الْحَالِ وَذُو أَخْلَاقٍ حَمِيدَةٍ، لَمْ يَذْكُرْ أَحَدٌ شَيْئًا يَعِيبُهُ", "segs": [{"ar": "هُوَ رَجُلٌ مَيْسُورُ الْحَالِ وَذُو أَخْلَاقٍ حَمِيدَةٍ", "uz": "U farovon hol va yaxshi axloq egasi"}, {"ar": "لَمْ يَذْكُرْ أَحَدٌ شَيْئًا يَعِيبُهُ", "uz": "hech kim unga nuqson bo'ladigan biror narsani zikr qilmadi"}], "full_uz": "U farovon hol va yaxshi axloq egasi — hech kim unga nuqson bo'ladigan biror narsani zikr qilmadi.", "note": null},
  {"num": 301, "time": "00:24:52,299 --> 00:24:58,720", "arabic": "أَمُتَأَكِّدٌ أَنْتَ يَا قَيْسُ؟ أَنْتَ تَعْرِفُ أَنَّ سَعَادَةَ هِيَ ابْنَتِي الصُّغْرَى وَأُرِيدُ أَنْ أَطْمَئِنَّ عَلَيْهِ", "segs": [{"ar": "أَمُتَأَكِّدٌ أَنْتَ يَا قَيْسُ؟", "uz": "Ishonchingiz komilmi, Qays?"}, {"ar": "أَنْتَ تَعْرِفُ أَنَّ سَعَادَةَ هِيَ ابْنَتِي الصُّغْرَى", "uz": "Bilasiz — Sa'ada mening kenja qizim"}, {"ar": "وَأُرِيدُ أَنْ أَطْمَئِنَّ عَلَيْهِ", "uz": "unga ishonch hosil qilishni istayman"}], "full_uz": "Ishonchingiz komilmi, Qays? Bilasiz — Sa'ada mening kenja qizim, unga ishonch hosil qilishni istayman.", "note": null},
  {"num": 302, "time": "00:24:58,720 --> 00:25:03,940", "arabic": "لَا تَدَعْ خَوْفَكَ يَقِفُ فِي طَرِيقِهَا يَا أَبَا فَوْزَ وَاتَّكِلْ عَلَى اللَّهِ", "segs": [{"ar": "لَا تَدَعْ خَوْفَكَ يَقِفُ فِي طَرِيقِهَا يَا أَبَا فَوْزَ", "uz": "Qo'rquvingiz uning yo'lida to'siq bo'lib qolishiga yo'l qo'ymang, Abu Favz"}, {"ar": "وَاتَّكِلْ عَلَى اللَّهِ", "uz": "Allohga tavakkal qiling"}], "full_uz": "Qo'rquvingiz uning yo'lida to'siq bo'lib qolishiga yo'l qo'ymang, Abu Favz — Allohga tavakkal qiling.", "note": null},
  {"num": 303, "time": "00:25:03,940 --> 00:25:12,559", "arabic": "وَهُوَ كَذَلِكَ وَنِعْمَ الِاتِّكَالُ، تَفَضَّلْ", "segs": null, "full_uz": "Shunday bo'lsin, naqadar yaxshi tavakkal. Marhamat.", "note": null},
  {"num": 306, "time": "00:25:12,559 --> 00:25:20,220", "arabic": "حَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ يَا مَوْلَايَ، أَرَاكَ الْيَوْمَ بِصِحَّةٍ جَيِّدَةٍ", "segs": [{"ar": "حَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ يَا مَوْلَايَ", "uz": "Salomat bo'lganingiz uchun Allohga hamd bo'lsin, xo'jayinim"}, {"ar": "أَرَاكَ الْيَوْمَ بِصِحَّةٍ جَيِّدَةٍ", "uz": "bugun sizni yaxshi sog'liqda ko'ryapman"}], "full_uz": "Salomat bo'lganingiz uchun Allohga hamd bo'lsin, xo'jayinim — bugun sizni yaxshi sog'liqda ko'ryapman.", "note": null},
  {"num": 308, "time": "00:25:20,220 --> 00:25:25,900", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Har holda alhamdulillah, Ibn Abi Duvod.", "note": null},
  {"num": 310, "time": "00:25:25,900 --> 00:25:32,519", "arabic": "لَقَدْ رَأَيْتُ أَنْ أُرْسِلَ إِلَى وَالِيكُمْ فِي بَغْدَادَ إِسْحَاقَ بْنِ إِبْرَاهِيمَ بْنِ مُصْعَبٍ", "segs": [{"ar": "لَقَدْ رَأَيْتُ أَنْ أُرْسِلَ إِلَى وَالِيكُمْ فِي بَغْدَادَ", "uz": "Bag'doddagi hokimingizga xat yuborishni ma'qul ko'rdim"}, {"ar": "إِسْحَاقَ بْنِ إِبْرَاهِيمَ بْنِ مُصْعَبٍ", "uz": "Ishoq ibn Ibrohim ibn Mus'abga"}], "full_uz": "Bag'doddagi hokimingiz Ishoq ibn Ibrohim ibn Mus'abga xat yuborishni ma'qul ko'rdim.", "note": null},
  {"num": 312, "time": "00:25:32,519 --> 00:25:40,720", "arabic": "أَنْ يَسْأَلَ الْقُضَاةَ هُنَاكَ وَمَنْ يَتَصَدَّرُونَ حَلَقَاتِ الْعِلْمِ فِي الْمَسَاجِدِ عَنْ قَوْلِهِمْ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ", "segs": [{"ar": "أَنْ يَسْأَلَ الْقُضَاةَ هُنَاكَ وَمَنْ يَتَصَدَّرُونَ حَلَقَاتِ الْعِلْمِ فِي الْمَسَاجِدِ", "uz": "U yerdagi qozilardan va masjidlarda ilm halqalariga boshchilik qiluvchilardan so'rasin"}, {"ar": "عَنْ قَوْلِهِمْ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ", "uz": "Qur'onning yaratilganligi masalasidagi fikrlarini"}], "full_uz": "U yerdagi qozilardan va masjidlarda ilm halqalariga boshchilik qiluvchilardan Qur'onning yaratilganligi masalasidagi fikrlarini so'rasin.", "note": null},
  {"num": 315, "time": "00:25:40,720 --> 00:25:50,360", "arabic": "أَتَظُنُّ الْوَقْتَ مُنَاسِبًا لِذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ؟", "segs": null, "full_uz": "Bunga vaqt munosib deb bilasanmi, Ibn Abi Duvod?", "note": null},
  {"num": 316, "time": "00:25:50,360 --> 00:25:57,240", "arabic": "اَلْحِفَاظُ عَلَى عَقِيدَةِ الرَّعِيَّةِ مِنْ مَهَامِّ وَلِيِّ الْأَمْرِ يَا مَوْلَايَ، أَخْشَى أَنْ يُفْسِدَ عَلَى النَّاسِ اعْتِقَادَهُمْ", "segs": [{"ar": "اَلْحِفَاظُ عَلَى عَقِيدَةِ الرَّعِيَّةِ مِنْ مَهَامِّ وَلِيِّ الْأَمْرِ يَا مَوْلَايَ", "uz": "Raiyat aqidasini saqlash hokimning vazifalaridan biridir, xo'jayinim"}, {"ar": "أَخْشَى أَنْ يُفْسِدَ عَلَى النَّاسِ اعْتِقَادَهُمْ", "uz": "odamlarning e'tiqodini buzib qo'yishidan qo'rqaman"}], "full_uz": "Raiyat aqidasini saqlash hokimning vazifalaridan biridir, xo'jayinim — odamlarning e'tiqodini buzib qo'yishidan qo'rqaman.", "note": null},
  {"num": 318, "time": "00:25:57,240 --> 00:26:03,100", "arabic": "بَعْضُ دُعَاةِ الْعِلْمِ مِنْ أَهْلِ الْحَدِيثِ، إِلَى مَتَى نَصْبِرُ عَلَى أَمْرٍ لَا يَرْضَاهُ اللَّهُ يَا مَوْلَايَ؟", "segs": [{"ar": "بَعْضُ دُعَاةِ الْعِلْمِ مِنْ أَهْلِ الْحَدِيثِ", "uz": "Hadis ahlidan ba'zi ilm da'vatgorlari"}, {"ar": "إِلَى مَتَى نَصْبِرُ عَلَى أَمْرٍ لَا يَرْضَاهُ اللَّهُ يَا مَوْلَايَ؟", "uz": "Alloh rozi bo'lmaydigan ishga qachongacha sabr qilamiz, xo'jayinim?"}], "full_uz": "Hadis ahlidan ba'zi ilm da'vatgorlari. Alloh rozi bo'lmaydigan ishga qachongacha sabr qilamiz, xo'jayinim?", "note": null},
  {"num": 319, "time": "00:26:03,100 --> 00:26:10,240", "arabic": "لَقَدْ أَمْهَلْنَا هَؤُلَاءِ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ دَهْرًا أَنْ يَرْجِعُوا عَنْ غَيِّهِمْ، فَمَا رَجَعُوا؟", "segs": [{"ar": "لَقَدْ أَمْهَلْنَا هَؤُلَاءِ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ دَهْرًا أَنْ يَرْجِعُوا عَنْ غَيِّهِمْ", "uz": "Bu fuqaho va hadis ahliga adashuvlaridan qaytishlari uchun uzoq vaqt muhlat berdik"}, {"ar": "فَمَا رَجَعُوا؟", "uz": "Qaytishmadimi?"}], "full_uz": "Bu fuqaho va hadis ahliga adashuvlaridan qaytishlari uchun uzoq vaqt muhlat berdik — qaytishmadimi?", "note": null},
  {"num": 321, "time": "00:26:10,720 --> 00:26:14,720", "arabic": "فَمَنْ شَاءَ يَبْقَى عَلَى ضَلَالَتِهِ فَلْيَبْقَ", "segs": null, "full_uz": "Kim o'z adashuvida qolishni istasa, qolaversin.", "note": null},
  {"num": 322, "time": "00:26:14,720 --> 00:26:24,759", "arabic": "نَحْنُ يَا مَوْلَايَ لَا نُكْرِهُ النَّاسَ عَلَى أَنْ يُصْبِحُوا مُؤْمِنِينَ، لَكِنَّنَا لَنْ نَتَحَمَّلَ جَرِيرَةَ ذَلِكَ", "segs": [{"ar": "نَحْنُ يَا مَوْلَايَ لَا نُكْرِهُ النَّاسَ عَلَى أَنْ يُصْبِحُوا مُؤْمِنِينَ", "uz": "Biz, xo'jayinim, odamlarni mo'min bo'lishga majburlamaymiz"}, {"ar": "لَكِنَّنَا لَنْ نَتَحَمَّلَ جَرِيرَةَ ذَلِكَ", "uz": "ammo buning jinoyatiga chidamaymiz"}], "full_uz": "Biz, xo'jayinim, odamlarni mo'min bo'lishga majburlamaymiz — ammo buning jinoyatiga chidamaymiz.", "note": null},
  {"num": 324, "time": "00:26:24,759 --> 00:26:31,140", "arabic": "إِلَى مَتَى نَتْرُكُهُمْ يُطِلُّونَ النَّاسَ بِأَقَاوِيلِهِمُ الْبَاطِلَةِ؟", "segs": null, "full_uz": "Ularni odamlarni botil so'zlari bilan zaharlashiga qachongacha yo'l qo'yamiz?", "note": null},
  {"num": 325, "time": "00:26:31,140 --> 00:26:47,759", "arabic": "إِنْ كَانَ الْأَمْرُ كَذَلِكَ فَلَا بَأْسَ، أَطَالَ اللَّهُ فِي عُمُرِكَ يَا مَوْلَايَ مُصِيرًا لِلْحَقِّ مُدَافِعًا عَنْ أَتْبَاعِهِ", "segs": [{"ar": "إِنْ كَانَ الْأَمْرُ كَذَلِكَ فَلَا بَأْسَ", "uz": "Bunday bo'lsa, zarari yo'q"}, {"ar": "أَطَالَ اللَّهُ فِي عُمُرِكَ يَا مَوْلَايَ مُصِيرًا لِلْحَقِّ", "uz": "Alloh umringizni uzun qilsin, xo'jayinim — haqning yordamchisi"}, {"ar": "مُدَافِعًا عَنْ أَتْبَاعِهِ", "uz": "izdoshlarining himoyachisi bo'lib"}], "full_uz": "Bunday bo'lsa, zarari yo'q. Alloh umringizni uzun qilsin, xo'jayinim — haqning yordamchisi, izdoshlarining himoyachisi bo'lib.", "note": null},
  {"num": 327, "time": "00:26:47,759 --> 00:26:53,580", "arabic": "أَنَا الْأَوَانُ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا وَكَلِمَةُ الْبَاطِلِ هِيَ السُّفْلَى", "segs": [{"ar": "أَنَا الْأَوَانُ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا", "uz": "Alloh kalimasi ustun bo'ladigan vaqt keldi"}, {"ar": "وَكَلِمَةُ الْبَاطِلِ هِيَ السُّفْلَى", "uz": "botil kalimasi past bo'ladigan"}], "full_uz": "Alloh kalimasi ustun, botil kalimasi past bo'ladigan vaqt keldi.", "note": null},
  {"num": 328, "time": "00:26:53,580 --> 00:27:02,680", "arabic": "غَدًا إِنْ شَاءَ اللَّهُ سَأَبْعَثُ لِوَالِينَا فِي بَغْدَادَ لِيَكُونَ الْقَوْلُ فِي خَلْقِ الْقُرْآنِ هُوَ مِيزَانَ الْحَقِّ", "segs": [{"ar": "غَدًا إِنْ شَاءَ اللَّهُ سَأَبْعَثُ لِوَالِينَا فِي بَغْدَادَ", "uz": "Ertaga, Alloh xohlasa, Bag'doddagi hokimimizga xat yuboraman"}, {"ar": "لِيَكُونَ الْقَوْلُ فِي خَلْقِ الْقُرْآنِ هُوَ مِيزَانَ الْحَقِّ", "uz": "Qur'onning yaratilganligi haqidagi so'z haqiqat mezoni bo'lsin"}], "full_uz": "Ertaga, Alloh xohlasa, Bag'doddagi hokimimizga xat yuboraman — Qur'onning yaratilganligi haqidagi so'z haqiqat mezoni bo'lsin.", "note": null},
  {"num": 329, "time": "00:27:02,680 --> 00:27:23,840", "arabic": "وَمَنْ خَالَفَ ذَلِكَ عَاقَبْنَاهُ بِحُكْمِهِ", "segs": null, "full_uz": "Va bunga qarshi chiqqanni o'z hukmi bilan jazolaymiz.", "note": null},
  {"num": 331, "time": "00:27:23,840 --> 00:27:31,280", "arabic": "تَفَقَّدُوا الْمَسَاجِينَ وَاحْرِصُوا عَلَى حُسْنِ سَيْرِ الْأُمُورِ وَاخْذُوا حَذَرَكُمْ", "segs": null, "full_uz": "Mahbuslarni tekshiring, ishlarning yaxshi yurishiga e'tibor bering va ehtiyot bo'ling.", "note": null},
  {"num": 334, "time": "00:27:31,280 --> 00:27:39,380", "arabic": "أَمْرُكَ سَيِّدِي، اِبْنُ مَيْسَرَةَ؟", "segs": null, "full_uz": "Xo'p bo'ladi, xo'jayin. Ibn Maysara?", "note": null},
  {"num": 336, "time": "00:27:39,380 --> 00:27:42,220", "arabic": "أَجَلْ، عَوْفُ بْنُ مَيْسَرَةَ الدِّمَشْقِيُّ", "segs": null, "full_uz": "Ha, Avf ibn Maysara ad-Dimashqiy.", "note": null},
  {"num": 337, "time": "00:27:42,220 --> 00:27:47,440", "arabic": "رَجُلٌ ذُو مَكَانَةٍ وَحُظْوَةٍ بَيْنَ النَّاسِ وَهُوَ مِنَ التُّجَّارِ الْمَيْسُورِينَ", "segs": [{"ar": "رَجُلٌ ذُو مَكَانَةٍ وَحُظْوَةٍ بَيْنَ النَّاسِ", "uz": "Odamlar orasida martaba va e'tiborga ega"}, {"ar": "وَهُوَ مِنَ التُّجَّارِ الْمَيْسُورِينَ", "uz": "farovon savdogarlardan biri"}], "full_uz": "Odamlar orasida martaba va e'tiborga ega, farovon savdogarlardan biri.", "note": null},
  {"num": 339, "time": "00:27:47,440 --> 00:27:58,860", "arabic": "كَأَنَّ الْأَمْرَ لَمْ يُعْجِبْكَ، لَيْسَ الْأَمْرُ كَذَلِكَ يَا أَبَا فَوْزَ", "segs": [{"ar": "كَأَنَّ الْأَمْرَ لَمْ يُعْجِبْكَ", "uz": "Xuddi bu ish senga yoqmagandek"}, {"ar": "لَيْسَ الْأَمْرُ كَذَلِكَ يَا أَبَا فَوْزَ", "uz": "Unday emas, Abu Favz"}], "full_uz": "Xuddi bu ish senga yoqmagandek. Unday emas, Abu Favz.", "note": null},
  {"num": 341, "time": "00:27:58,860 --> 00:28:06,120", "arabic": "لَكِنَّكَ تَعْلَمُ أَنَّ سَعَادَةَ هِيَ ابْنَتُنَا الصُّغْرَى وَسَيَصْعُبُ عَلَيَّ فِرَاقُهَا", "segs": [{"ar": "لَكِنَّكَ تَعْلَمُ أَنَّ سَعَادَةَ هِيَ ابْنَتُنَا الصُّغْرَى", "uz": "Ammo bilasiz — Sa'ada bizning kenja qizimiz"}, {"ar": "وَسَيَصْعُبُ عَلَيَّ فِرَاقُهَا", "uz": "undan ajralish menga qiyin bo'ladi"}], "full_uz": "Ammo bilasiz — Sa'ada bizning kenja qizimiz, undan ajralish menga qiyin bo'ladi.", "note": null},
  {"num": 343, "time": "00:28:07,380 --> 00:28:11,680", "arabic": "اَلْبِنْتُ ضَيْفَةٌ فِي بَيْتِ أَبِيهَا يَا أُمَّ فَوْزَ، سُرْعَانَ مَا تُغَادِرُ", "segs": [{"ar": "اَلْبِنْتُ ضَيْفَةٌ فِي بَيْتِ أَبِيهَا يَا أُمَّ فَوْزَ", "uz": "Qiz otasining uyida mehmondir, Ummu Favz"}, {"ar": "سُرْعَانَ مَا تُغَادِرُ", "uz": "tez orada chiqib ketadi"}], "full_uz": "Qiz otasining uyida mehmondir, Ummu Favz — tez orada chiqib ketadi.", "note": null},
  {"num": 345, "time": "00:28:11,680 --> 00:28:17,780", "arabic": "وَإِذَا جَاءَكُمْ رَجُلٌ تَرْضَوْنَهُ زَوْجًا فَزَوِّجُوهُ، لَا أَعْرِفُ يَا مَرْوَانُ", "segs": [{"ar": "وَإِذَا جَاءَكُمْ رَجُلٌ تَرْضَوْنَهُ زَوْجًا فَزَوِّجُوهُ", "uz": "Rozi bo'ladigan bir er kelsa, uzating"}, {"ar": "لَا أَعْرِفُ يَا مَرْوَانُ", "uz": "Bilmayman, Marvon"}], "full_uz": "Rozi bo'ladigan bir er kelsa, uzating. Bilmayman, Marvon.", "note": null},
  {"num": 347, "time": "00:28:17,780 --> 00:28:21,200", "arabic": "دَعْنِي أُفَكِّرُ قَلِيلًا، كَمَا تَشَاءُ", "segs": null, "full_uz": "Menga bir oz o'ylashga imkon bering. Xohlaganingizcha.", "note": null},
  {"num": 349, "time": "00:28:21,200 --> 00:28:26,240", "arabic": "وَلَكِنْ اعْلَمِي أَنَّ الزَّوْجَةَ الصَّالِحَةَ نِعْمَةُ الْمُهْدَاةِ وَهَدِيَّةُ الْمُزْدَادِ", "segs": null, "full_uz": "Ammo bilingki, solih xotin — Allohning berilgan ne'mati va ortiqcha ehsonidir.", "note": null},
  {"num": 351, "time": "00:28:26,240 --> 00:28:28,340", "arabic": "لَا يَنْبَغِي التَّفْرِيطُ فِيهِ", "segs": null, "full_uz": "Unga sustkashlik qilish yarashmaydi.", "note": null},
  {"num": 352, "time": "00:28:28,340 --> 00:28:36,720", "arabic": "حَدَّثَنَا عَبْدُ الرَّزَّاقِ حَدَّثَنَا مَعْمَرٌ", "segs": null, "full_uz": "Bizga Abdurazzaq rivoyat qildi, bizga Ma'mar rivoyat qildi.", "note": null},
  {"num": 354, "time": "00:28:36,720 --> 00:28:43,920", "arabic": "عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ قَالَتْ", "segs": null, "full_uz": "Az-Zuhriydan, u Urvadan, u Oyishadan — u dedi.", "note": null},
  {"num": 356, "time": "00:28:43,920 --> 00:28:48,620", "arabic": "كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ", "segs": [{"ar": "كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ", "uz": "Rasululloh sollallohu alayhi va sallam kechasi namoz o'qirdilar"}], "full_uz": "Rasululloh sollallohu alayhi va sallam kechasi namoz o'qirdilar.", "note": null},
  {"num": 357, "time": "00:28:48,620 --> 00:28:56,019", "arabic": "إِحْدَى عَشْرَةَ رَكْعَةً", "segs": null, "full_uz": "O'n bir rakat.", "note": null},
  {"num": 359, "time": "00:28:56,019 --> 00:29:04,940", "arabic": "فَإِذَا فَجَرَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ", "segs": null, "full_uz": "Tong otganida esa ikki yengil rakat o'qirdilar.", "note": null},
  {"num": 361, "time": "00:29:06,720 --> 00:29:10,740", "arabic": "ثُمَّ اتَّكَأَ عَلَى شِقِّهِ الْأَيْمَنِ", "segs": null, "full_uz": "So'ng o'ng biqiniga suyanib yotardilar.", "note": null},
  {"num": 362, "time": "00:29:10,740 --> 00:29:18,059", "arabic": "حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ يُؤَذِّنُهُ لِلصَّلَاةِ، هَاتِي نَوِّلِينِي أَقْرَأُ مَا كَتَبْتُ", "segs": [{"ar": "حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ يُؤَذِّنُهُ لِلصَّلَاةِ", "uz": "Toki muazzin namozga azon aytish uchun kelguncha"}, {"ar": "هَاتِي نَوِّلِينِي أَقْرَأُ مَا كَتَبْتُ", "uz": "Ber, ko'ray yozganimni o'qiy"}], "full_uz": "Toki muazzin namozga azon aytish uchun kelguncha. Ber, ko'ray yozganimni o'qiy.", "note": null},
  {"num": 364, "time": "00:29:18,059 --> 00:29:23,620", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "La havla va la quvvata illa billah.", "note": null},
  {"num": 365, "time": "00:29:23,620 --> 00:29:25,740", "arabic": "عَبَّاسَةُ قَدْ نَامَ صَالِحٌ", "segs": null, "full_uz": "Abbosa, Solih uxlab qoldi.", "note": null},
  {"num": 366, "time": "00:29:25,740 --> 00:29:33,220", "arabic": "دَعْهُ يَرْتَاحُ قَلِيلًا", "segs": null, "full_uz": "Qo'y, bir oz dam olsin.", "note": null},
  {"num": 367, "time": "00:29:33,220 --> 00:29:41,480", "arabic": "أَمْ تَظُنُّهُ فِي مِثْلِ جَلَدِكَ وَصَبْرِكَ يَا أَبَا عَبْدِ اللَّهِ؟ اَلْعِلْمُ لَا يُنَالُ بِالرَّاحَةِ، يَظْفَرُ بِهِ مَنْ جَدَّ وَتَعِبَ", "segs": [{"ar": "أَمْ تَظُنُّهُ فِي مِثْلِ جَلَدِكَ وَصَبْرِكَ يَا أَبَا عَبْدِ اللَّهِ؟", "uz": "Yoki uni sizning bardosh va sabringizga o'xshaydi deb o'ylaysizmi, Abu Abdulloh?"}, {"ar": "اَلْعِلْمُ لَا يُنَالُ بِالرَّاحَةِ، يَظْفَرُ بِهِ مَنْ جَدَّ وَتَعِبَ", "uz": "Ilmga rohat bilan erishilmaydi — unga tirishib, mehnat qilgan kishi erishadi"}], "full_uz": "Yoki uni sizning bardosh va sabringizga o'xshaydi deb o'ylaysizmi, Abu Abdulloh? Ilmga rohat bilan erishilmaydi — unga tirishib, mehnat qilgan kishi erishadi.", "note": null},
  {"num": 369, "time": "00:29:41,480 --> 00:29:44,640", "arabic": "رَحِمَكِ اللَّهُ يَا أُمِّي", "segs": null, "full_uz": "Alloh sizga rahmat qilsin, onajon.", "note": null},
  {"num": 370, "time": "00:29:44,640 --> 00:29:46,799", "arabic": "تَعَالَيْ وَانْظُرِي وَلَدَ أَحْمَدَ", "segs": null, "full_uz": "Kel, Ahmadning bolasiga qara.", "note": null},
  {"num": 371, "time": "00:29:46,799 --> 00:29:51,860", "arabic": "أَظُنُّهَا كَانَتْ سَتَتْرُكُهُ يَخْلُدُ إِلَى النَّوْمِ وَتَتْرُكُ الْحَلَّ", "segs": null, "full_uz": "O'ylaymanki, u uni uyquga qoldirib, muammoni hal qilishni tashlab ketardi.", "note": null},
  {"num": 372, "time": "00:30:03,220 --> 00:30:12,220", "arabic": "إِنْ كَانَ الْأَمْرُ يُضَايِقُكَ إِلَى هَذَا الْحَدِّ، لِمَ لَا تَتْرُكُهُ وَتَتَفَرَّغُ لِأَعْمَالِكَ؟", "segs": [{"ar": "إِنْ كَانَ الْأَمْرُ يُضَايِقُكَ إِلَى هَذَا الْحَدِّ", "uz": "Agar bu ish sizni shu darajada bezovta qilsa"}, {"ar": "لِمَ لَا تَتْرُكُهُ وَتَتَفَرَّغُ لِأَعْمَالِكَ؟", "uz": "nega uni tashlab, o'z ishlaringizga bag'ishlanmaysiz?"}], "full_uz": "Agar bu ish sizni shu darajada bezovta qilsa, nega uni tashlab, o'z ishlaringizga bag'ishlanmaysiz?", "note": null},
  {"num": 374, "time": "00:30:13,940 --> 00:30:16,059", "arabic": "أَتْرُكُ أَعْمَالِي؟ أَجَلْ", "segs": null, "full_uz": "Ishlarimni tashlaymanmi? Ha.", "note": null},
  {"num": 376, "time": "00:30:16,059 --> 00:30:23,220", "arabic": "فَإِنْ لَمْ تَسْتَطِعْ أَنْ تُحِبَّ مَا تَعْمَلُ فَاعْمَلْ مَا تُحِبُّ، لَدَيْكَ دَكَاكِينُكَ إِنْ كُنْتَ تَكْرَهُ الْجُلُوسَ فِي الْبَيْتِ", "segs": [{"ar": "فَإِنْ لَمْ تَسْتَطِعْ أَنْ تُحِبَّ مَا تَعْمَلُ فَاعْمَلْ مَا تُحِبُّ", "uz": "Agar qilayotgan ishingizni sevishning iloji bo'lmasa, sevganingizni qiling"}, {"ar": "لَدَيْكَ دَكَاكِينُكَ إِنْ كُنْتَ تَكْرَهُ الْجُلُوسَ فِي الْبَيْتِ", "uz": "uyda o'tirishni yomon ko'rsangiz, do'konlaringiz bor-ku"}], "full_uz": "Agar qilayotgan ishingizni sevishning iloji bo'lmasa, sevganingizni qiling — uyda o'tirishni yomon ko'rsangiz, do'konlaringiz bor-ku.", "note": null},
  {"num": 378, "time": "00:30:25,660 --> 00:30:32,120", "arabic": "أَنَا رَجُلٌ أَمْضَى عُمْرَهُ مَعَ الْعَسْكَرِ، لَا أَجِدُ نَفْسِي إِلَّا بَيْنَ الْجُنْدِ وَقَعْقَعَةِ السُّيُوفِ", "segs": [{"ar": "أَنَا رَجُلٌ أَمْضَى عُمْرَهُ مَعَ الْعَسْكَرِ", "uz": "Men umrimni askarlar bilan o'tkazgan odamman"}, {"ar": "لَا أَجِدُ نَفْسِي إِلَّا بَيْنَ الْجُنْدِ وَقَعْقَعَةِ السُّيُوفِ", "uz": "o'zimni faqat qo'shin va qilichlar shovqini orasida topaman"}], "full_uz": "Men umrimni askarlar bilan o'tkazgan odamman — o'zimni faqat qo'shin va qilichlar shovqini orasida topaman.", "note": null},
  {"num": 380, "time": "00:30:32,119 --> 00:30:35,319", "arabic": "زَوْجِي رَجُلٌ وَلُوعٌ بِالْمَتَاعِبِ", "segs": null, "full_uz": "Erim mashaqqatlarga ishqiy bir kishidir.", "note": null},
  {"num": 381, "time": "00:30:35,319 --> 00:30:37,619", "arabic": "أَلَسْتَ غَيْرَ رَاضٍ عَنْ عَمَلِكَ؟", "segs": null, "full_uz": "Ishingizdan norozi emasmisiz?", "note": null},
  {"num": 382, "time": "00:30:37,619 --> 00:30:42,439", "arabic": "إِنَّ الَّذِينَ جَاءُوا مِنْ بَعْدِهِ يَتَوَلَّوْنَ الْآنَ قِيَادَةَ الْجُنْدِ وَالدَّوَاوِينِ", "segs": [{"ar": "إِنَّ الَّذِينَ جَاءُوا مِنْ بَعْدِهِ", "uz": "Undan keyin kelganlar"}, {"ar": "يَتَوَلَّوْنَ الْآنَ قِيَادَةَ الْجُنْدِ وَالدَّوَاوِينِ", "uz": "hozir qo'shin va devonlar boshchiligini egallab olishmoqda"}], "full_uz": "Undan keyin kelganlar hozir qo'shin va devonlar boshchiligini egallab olishmoqda.", "note": null},
  {"num": 384, "time": "00:30:42,439 --> 00:30:48,439", "arabic": "وَأَنَا أُلْقَى بِي إِلَى السِّجْنِ، فَلَسْتُ أَدْرِي مَاذَا بَعْدَ السِّجْنِ", "segs": [{"ar": "وَأَنَا أُلْقَى بِي إِلَى السِّجْنِ", "uz": "Men esa qamoqqa tashlanaman"}, {"ar": "فَلَسْتُ أَدْرِي مَاذَا بَعْدَ السِّجْنِ", "uz": "qamoqdan keyin nima bo'lishini bilmayman"}], "full_uz": "Men esa qamoqqa tashlanaman — qamoqdan keyin nima bo'lishini bilmayman.", "note": null},
  {"num": 386, "time": "00:30:48,439 --> 00:30:51,619", "arabic": "إِنَّهُ الْبَيْتُ", "segs": null, "full_uz": "Bu — uy.", "note": null},
  {"num": 387, "time": "00:30:51,619 --> 00:30:56,759", "arabic": "غَرِيبٌ أَمْرُكَ وَاللَّهِ، تَصْبِرُ عَلَى الْعَمَلِ مَعَهُمْ وَلَا اسْتِمَاعَ عَلَى وِفَاقٍ", "segs": [{"ar": "غَرِيبٌ أَمْرُكَ وَاللَّهِ", "uz": "Ishing g'aroyib, Alloh haqi"}, {"ar": "تَصْبِرُ عَلَى الْعَمَلِ مَعَهُمْ وَلَا اسْتِمَاعَ عَلَى وِفَاقٍ", "uz": "ular bilan ishlashga chidaysan, ammo kelishuvga quloq solmaysan"}], "full_uz": "Ishing g'aroyib, Alloh haqi — ular bilan ishlashga chidaysan, ammo kelishuvga quloq solmaysan.", "note": null},
  {"num": 389, "time": "00:30:56,759 --> 00:31:01,659", "arabic": "لَا أَنْ تَتَلَيَّنَ لَهُمْ أَوْ تَعْتَنِقَ مَذْهَبَهُمْ وَلَا هُمْ كَذَلِكَ، لَا يَا فَوْزُ", "segs": [{"ar": "لَا أَنْ تَتَلَيَّنَ لَهُمْ أَوْ تَعْتَنِقَ مَذْهَبَهُمْ", "uz": "Ularga yumshamasang yoki mazhablarini qabul qilmasang ham"}, {"ar": "وَلَا هُمْ كَذَلِكَ، لَا يَا فَوْزُ", "uz": "ular ham shunday emas-ku. Yo'q, Favz"}], "full_uz": "Ularga yumshamasang yoki mazhablarini qabul qilmasang ham, ular ham shunday emas-ku. Yo'q, Favz.", "note": null},
  {"num": 391, "time": "00:31:01,660 --> 00:31:05,080", "arabic": "هُمْ أَخْوَنُ مِنْ أَنْ أُدَاهِنَهُمْ وَأَخْضَعَ لَهُمْ", "segs": null, "full_uz": "Ular ularga xushomad qilishim va bo'ysunishim uchun juda xoin.", "note": null},
  {"num": 392, "time": "00:31:05,080 --> 00:31:08,340", "arabic": "لَسْتُ أَنَا مَنْ يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا", "segs": null, "full_uz": "Men dinimni dunyoning arzimas narsasiga sotadigan kishi emasman.", "note": null},
  {"num": 393, "time": "00:31:08,340 --> 00:31:09,440", "arabic": "سُحْقًا لَهُ", "segs": null, "full_uz": "Unga la'nat bo'lsin.", "note": null},
  {"num": 394, "time": "00:31:09,440 --> 00:31:15,120", "arabic": "وَكُلَّ يَوْمٍ يَبْلُغُ إِجْلَالِي لَكَ مَدَاهُ يَا شَفِيعُ", "segs": null, "full_uz": "Har kuni senga bo'lgan hurmatim yangi chekkasiga yetadi, Shafi'.", "note": null},
  {"num": 395, "time": "00:31:15,120 --> 00:32:01,640", "arabic": "فَاصْبِرْ، إِنَّ اللَّهَ مَعَ الصَّابِرِينَ", "segs": null, "full_uz": "Sabr qil — albatta, Alloh sabr qiluvchilar bilan birga.", "note": null},
  {"num": 398, "time": "00:32:01,660 --> 00:32:11,940", "arabic": "هُوَ خَرَجَ مُمْتَعِضًا أَيْضًا كَعَادَتِهِ هَدَاهُ اللَّهُ", "segs": null, "full_uz": "U ham odatidagidek g'azablangan holda chiqib ketdi — Alloh uni hidoyat qilsin.", "note": null},
  {"num": 399, "time": "00:32:11,940 --> 00:32:18,840", "arabic": "مَا بِكَ يَا أَبَا نَصْرٍ؟ تَبْدُو عَلَى غَيْرِ سَجِيَّتِكَ هَذَا الْيَوْمَ", "segs": [{"ar": "مَا بِكَ يَا أَبَا نَصْرٍ؟", "uz": "Senga nima bo'ldi, Abu Nasr?"}, {"ar": "تَبْدُو عَلَى غَيْرِ سَجِيَّتِكَ هَذَا الْيَوْمَ", "uz": "Bugun odatingdan farqli ko'rinasan"}], "full_uz": "Senga nima bo'ldi, Abu Nasr? Bugun odatingdan farqli ko'rinasan.", "note": null},
  {"num": 400, "time": "00:32:18,840 --> 00:32:25,880", "arabic": "لَا أَكْتُمُكَ سِرًّا يَا ابْنَ نُوحٍ، اَلْأَخْبَارُ غَيْرُ مُطْمَئِنَّةٍ", "segs": null, "full_uz": "Sirni sendan yashirmayman, Ibn Nuh — xabarlar tinchlantiruvchi emas.", "note": null},
  {"num": 402, "time": "00:32:25,880 --> 00:32:27,660", "arabic": "أَيُّ أَخْبَارٍ؟", "segs": null, "full_uz": "Qanday xabarlar?", "note": null},
  {"num": 403, "time": "00:32:28,400 --> 00:32:32,660", "arabic": "أَخْبَارُ قَصْرِ الْخِلَافَةِ، أَتَقْصِدُ مَا وُشِيَ عَنْ مَرَضِ الْمَأْمُونِ؟", "segs": null, "full_uz": "Xalifalik saroyi xabarlari. Al-Ma'munning kasalligi haqida aytilgan gapni nazarda tutyapsanmi?", "note": null},
  {"num": 405, "time": "00:32:34,660 --> 00:32:43,660", "arabic": "لَا، اَلْأَمْرُ أَخْطَرُ مِنْ ذَلِكَ، وَلَكِنَّنِي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ", "segs": [{"ar": "لَا، اَلْأَمْرُ أَخْطَرُ مِنْ ذَلِكَ", "uz": "Yo'q, ish bundan xavfliroq"}, {"ar": "وَلَكِنَّنِي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ", "uz": "ammo hali unga ishonch hosil qilmadim"}], "full_uz": "Yo'q, ish bundan xavfliroq — ammo hali unga ishonch hosil qilmadim.", "note": null},
  {"num": 406, "time": "00:32:44,660 --> 00:32:48,660", "arabic": "لَقَدْ زِدْتَنِي قَلَقًا فَوْقَ قَلَقِي يَا أَبَا نَصْرٍ، فَمَا الْخَطْبُ؟", "segs": [{"ar": "لَقَدْ زِدْتَنِي قَلَقًا فَوْقَ قَلَقِي يَا أَبَا نَصْرٍ", "uz": "Meni xavotirim ustiga xavotir qo'shding, Abu Nasr"}, {"ar": "فَمَا الْخَطْبُ؟", "uz": "Nima gap?"}], "full_uz": "Meni xavotirim ustiga xavotir qo'shding, Abu Nasr — nima gap?", "note": null},
  {"num": 407, "time": "00:32:49,660 --> 00:32:57,660", "arabic": "سَمِعْتُ مِنْ أَحَدِ الْإِخْوَةِ الَّذِينَ يَعْمَلُونَ فِي الْقَصْرِ أَنَّ الْمَأْمُونَ يُبَيِّتُ أَمْرًا بِلَيْلٍ", "segs": [{"ar": "سَمِعْتُ مِنْ أَحَدِ الْإِخْوَةِ الَّذِينَ يَعْمَلُونَ فِي الْقَصْرِ", "uz": "Saroyda ishlaydigan birodarlaridan biridan eshitdim"}, {"ar": "أَنَّ الْمَأْمُونَ يُبَيِّتُ أَمْرًا بِلَيْلٍ", "uz": "al-Ma'mun tunda bir ish rejalashtirmoqda"}], "full_uz": "Saroyda ishlaydigan birodarlaridan biridan eshitdim — al-Ma'mun tunda bir ish rejalashtirmoqda.", "note": null},
  {"num": 408, "time": "00:32:57,660 --> 00:33:04,660", "arabic": "اَلْمَأْمُونُ سَيَفْرِضُ مَذْهَبَ الِاعْتِزَالِ دِينًا لِلدَّوْلَةِ", "segs": null, "full_uz": "Al-Ma'mun Mo'tazila mazhabini davlat dini sifatida majburiy qiladi.", "note": null},
  {"num": 409, "time": "00:33:04,660 --> 00:33:06,660", "arabic": "أَعُوذُ بِاللَّهِ مِنْ مَقْتِ اللَّهِ", "segs": null, "full_uz": "Allohning g'azabidan Allohga sig'inaman.", "note": null},
  {"num": 410, "time": "00:33:06,660 --> 00:33:08,660", "arabic": "سَلِّمْ يَا رَبِّ سَلِّمْ", "segs": null, "full_uz": "Salomat qil, Rabbim, salomat qil.", "note": null},
  {"num": 411, "time": "00:33:08,660 --> 00:33:12,660", "arabic": "لَمْ أَتَأَكَّدْ بَعْدُ مِنَ الْخَبَرِ كَمَا قُلْتُ لَكَ", "segs": null, "full_uz": "Aytganimdek, xabarga hali ishonch hosil qilmadim.", "note": null},
  {"num": 412, "time": "00:33:12,660 --> 00:33:16,660", "arabic": "فَاجْعَلْ مَا ذَكَرْتُ طَيَّ الْكِتْمَانِ", "segs": null, "full_uz": "Aytganimni sir sifatida saqla.", "note": null},
  {"num": 413, "time": "00:33:18,660 --> 00:33:29,100", "arabic": "وَلَكِنَّهُ إِنْ كَانَ صَحِيحًا فَنَحْنُ أَمَامَ أَيَّامِ الْمَوْتِ، وَنَحْنُ أَمَامَ أَيَّامِ الْمِحَنِ وَالِابْتِلَاءِ", "segs": [{"ar": "وَلَكِنَّهُ إِنْ كَانَ صَحِيحًا فَنَحْنُ أَمَامَ أَيَّامِ الْمَوْتِ", "uz": "Ammo agar bu to'g'ri bo'lsa, biz o'lim kunlari oldida turibmiz"}, {"ar": "وَنَحْنُ أَمَامَ أَيَّامِ الْمِحَنِ وَالِابْتِلَاءِ", "uz": "biz mihna va sinov kunlari oldida turibmiz"}], "full_uz": "Ammo agar bu to'g'ri bo'lsa, biz o'lim kunlari oldida turibmiz — biz mihna va sinov kunlari oldida turibmiz.", "note": null},
  {"num": 416, "time": "00:33:29,100 --> 00:33:33,160", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "La havla va la quvvata illa billah.", "note": null},
  {"num": 417, "time": "00:33:33,160 --> 00:33:46,660", "arabic": "لَيْتَ أَبِي يَأْذَنُ لِي بِالْعَمَلِ مَعَكَ يَا عُمَرُ", "segs": null, "full_uz": "Koshki otam sen bilan ishlashimga ruxsat bersa, Umar.", "note": null},
  {"num": 418, "time": "00:33:46,660 --> 00:33:49,160", "arabic": "عَجَبًا يَا صَالِحُ", "segs": null, "full_uz": "Ajablanarli, Solih.", "note": null},
  {"num": 419, "time": "00:33:49,160 --> 00:33:56,299", "arabic": "أَيَسْتَبْدِلُ عَاقِلٌ طَلَبَ الْعِلْمِ بِإِصْلَاحِ نِعَالِ النَّاسِ؟ يَبْدُو أَنَّكَ لَمْ تَرِثْ عَنْ أَبِيكَ حُبَّهُ لِلْعِلْمِ", "segs": [{"ar": "أَيَسْتَبْدِلُ عَاقِلٌ طَلَبَ الْعِلْمِ بِإِصْلَاحِ نِعَالِ النَّاسِ؟", "uz": "Aqlli odam ilm izlashni odamlarning poyafzalini tuzatish bilan almashtiradimi?"}, {"ar": "يَبْدُو أَنَّكَ لَمْ تَرِثْ عَنْ أَبِيكَ حُبَّهُ لِلْعِلْمِ", "uz": "Otangdan ilmga bo'lgan sevgisini meros olmaganga o'xshaysan"}], "full_uz": "Aqlli odam ilm izlashni odamlarning poyafzalini tuzatish bilan almashtiradimi? Otangdan ilmga bo'lgan sevgisini meros olmaganga o'xshaysan.", "note": null},
  {"num": 421, "time": "00:33:56,299 --> 00:34:01,480", "arabic": "وَمَنْ لَا يُحِبُّ الْعِلْمَ يَا عُمَرُ؟ وَلَكِنَّنِي أُرِيدُ أَنْ أُسَاعِدَ أَبِي عَلَى تَكَالِيفِ الْحَيَاةِ", "segs": [{"ar": "وَمَنْ لَا يُحِبُّ الْعِلْمَ يَا عُمَرُ؟", "uz": "Kim ilmni sevmaydi, Umar?"}, {"ar": "وَلَكِنَّنِي أُرِيدُ أَنْ أُسَاعِدَ أَبِي عَلَى تَكَالِيفِ الْحَيَاةِ", "uz": "Ammo otamga hayot xarajatlarida yordam berishni istayman"}], "full_uz": "Kim ilmni sevmaydi, Umar? Ammo otamga hayot xarajatlarida yordam berishni istayman.", "note": null},
  {"num": 423, "time": "00:34:01,480 --> 00:34:06,900", "arabic": "أَتَعْلَمُ إِنْ رَآكَ الْإِمَامُ عِنْدِي مَاذَا سَيَفْعَلُ؟ سَيَطْرُدُنَا مَعًا", "segs": null, "full_uz": "Bilasanmi, Imom seni yonimda ko'rsa nima qiladi? Ikkimizni ham quvib chiqaradi.", "note": null},
  {"num": 426, "time": "00:34:06,900 --> 00:34:11,579", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatulloh.", "note": null},
  {"num": 429, "time": "00:34:11,579 --> 00:34:17,559", "arabic": "كَيْفَ هِيَ الْأَسْعَارُ لَدَيْكَ الْيَوْمَ؟", "segs": null, "full_uz": "Bugun sizdagi narxlar qanday?", "note": null},
  {"num": 430, "time": "00:34:17,559 --> 00:34:20,559", "arabic": "كَمَا كَانَتْ بِالْأَمْسِ أَيُّهَا الْمُحْتَسِبُ", "segs": null, "full_uz": "Kechagidek, ey muhtasib.", "note": "اَلْمُحْتَسِب — bozor va jamoat axloqini nazorat qiluvchi mansabdor."},
  {"num": 431, "time": "00:34:20,559 --> 00:34:27,139", "arabic": "وَكَيْفَ كَانَتْ فِي الْأَمْسِ؟ أَظُنُّكَ سَتَقُولُ لِي كَمَا كَانَتْ قَبْلَ أَمْسٍ", "segs": [{"ar": "وَكَيْفَ كَانَتْ فِي الْأَمْسِ؟", "uz": "Kecha qanday edi?"}, {"ar": "أَظُنُّكَ سَتَقُولُ لِي كَمَا كَانَتْ قَبْلَ أَمْسٍ", "uz": "O'ylashimcha, o'tgan kundagidek deysan menga"}], "full_uz": "Kecha qanday edi? O'ylashimcha, o'tgan kundagidek deysan menga.", "note": null},
  {"num": 432, "time": "00:34:27,139 --> 00:34:36,579", "arabic": "نَحْنُ لَسْنَا مِنْ أُولَئِكَ الَّذِينَ يَتَلَاعَبُونَ بِالْأَسْعَارِ", "segs": null, "full_uz": "Biz narxlar bilan o'ynaydiganlardan emasmiz.", "note": null},
  {"num": 433, "time": "00:34:36,579 --> 00:34:39,920", "arabic": "نَحْنُ نَخَافُ اللَّهَ، اَللَّهَ فَقَطْ", "segs": null, "full_uz": "Biz Allohdan qo'rqamiz — faqat Allohdan.", "note": null},
  {"num": 434, "time": "00:34:39,920 --> 00:34:42,440", "arabic": "جَيِّدٌ جَيِّدٌ", "segs": null, "full_uz": "Yaxshi, yaxshi.", "note": null},
  {"num": 435, "time": "00:34:42,440 --> 00:34:47,940", "arabic": "فَبَعْضُ مَنْ لَا دِينَ لَهُ وَلَا ضَمِيرَ عِنْدَهُ يَحْتَجُّ بِالْبَاطِلِ كَيْ يَرْفَعَ الْأَسْعَارَ كَيْفَمَا شَاءَ", "segs": [{"ar": "فَبَعْضُ مَنْ لَا دِينَ لَهُ وَلَا ضَمِيرَ عِنْدَهُ", "uz": "Dini yo'q, vijdoni yo'q ba'zi kishilar esa"}, {"ar": "يَحْتَجُّ بِالْبَاطِلِ كَيْ يَرْفَعَ الْأَسْعَارَ كَيْفَمَا شَاءَ", "uz": "xohlagancha narxni ko'tarish uchun botilga bahona qidiradi"}], "full_uz": "Dini yo'q, vijdoni yo'q ba'zi kishilar esa xohlagancha narxni ko'tarish uchun botilga bahona qidiradi.", "note": null},
  {"num": 436, "time": "00:34:50,559 --> 00:34:52,239", "arabic": "مَا اسْمُكَ أَيُّهَا الْفَتَى؟", "segs": null, "full_uz": "Isming nima, yigitcha?", "note": null},
  {"num": 437, "time": "00:34:52,239 --> 00:34:55,019", "arabic": "صَالِحُ ابْنُ أَحْمَدَ بْنِ حَنْبَلٍ الشَّيْبَانِيِّ", "segs": null, "full_uz": "Solih ibn Ahmad ibn Hanbal ash-Shayboniy.", "note": null},
  {"num": 438, "time": "00:34:55,019 --> 00:35:03,980", "arabic": "اِبْنُ أَحْمَدَ بْنِ حَنْبَلٍ؟", "segs": null, "full_uz": "Ahmad ibn Hanbalning o'g'limi?", "note": null},
  {"num": 440, "time": "00:35:03,980 --> 00:35:06,420", "arabic": "إِنَّهُ ابْنُ الْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ", "segs": null, "full_uz": "U Imom Ahmad ibn Hanbalning o'g'lidir.", "note": null},
  {"num": 441, "time": "00:35:06,420 --> 00:35:11,559", "arabic": "شَيْخِ بَغْدَادَ وَإِمَامِي، اَلشَّيْخِ وَالْإِمَامِ؟", "segs": null, "full_uz": "Bag'dodning shayxi va mening imomim. Shayx va imommi?", "note": null},
  {"num": 443, "time": "00:35:12,340 --> 00:35:13,559", "arabic": "هَلْ خَلَطَهُ مَا يُضْحِكُ؟", "segs": null, "full_uz": "Unga kulgili biror narsa aralashib qoldimi?", "note": null},
  {"num": 444, "time": "00:35:16,860 --> 00:35:23,800", "arabic": "اِنْتَبِهْ لِكَلَامِكَ أَيُّهَا الرَّجُلُ وَإِلَّا سَتَكُونُ الْعَوَاقِبُ وَخِيمَةً", "segs": null, "full_uz": "So'zingga ehtiyot bo'l, ey odam — aks holda oqibati og'ir bo'ladi.", "note": null},
  {"num": 447, "time": "00:35:37,300 --> 00:35:44,620", "arabic": "وَلَا بُدَّ لِلْمُسْلِمِينَ مِنْ حَاكِمٍ مُسْلِمٍ بِالشُّرُوطِ الَّتِي حَدَّدَهَا الشَّرْعُ وَإِلَّا ضَاعَتْ حُقُوقُ النَّاسِ", "segs": [{"ar": "وَلَا بُدَّ لِلْمُسْلِمِينَ مِنْ حَاكِمٍ مُسْلِمٍ بِالشُّرُوطِ الَّتِي حَدَّدَهَا الشَّرْعُ", "uz": "Musulmonlarga shariat belgilagan shartlar bilan musulmon hokim albatta zarur"}, {"ar": "وَإِلَّا ضَاعَتْ حُقُوقُ النَّاسِ", "uz": "aks holda odamlarning huquqlari zoye bo'ladi"}], "full_uz": "Musulmonlarga shariat belgilagan shartlar bilan musulmon hokim albatta zarur — aks holda odamlarning huquqlari zoye bo'ladi.", "note": null},
  {"num": 450, "time": "00:35:44,620 --> 00:35:49,600", "arabic": "فَإِذَا كَانَ السُّلْطَانُ صَالِحًا فَهُوَ خَيْرٌ مِنْ صَالِحِي الْأُمَّةِ", "segs": null, "full_uz": "Agar sulton solih bo'lsa, u ummatning solihlaridan yaxshiroqdir.", "note": null},
  {"num": 452, "time": "00:35:49,600 --> 00:35:53,920", "arabic": "وَإِذَا كَانَ فَاسِقًا فَصَالِحُو الْأُمَّةِ خَيْرٌ مِنْهُ", "segs": null, "full_uz": "Agar u fosiq bo'lsa, ummatning solihlari undan yaxshiroqdir.", "note": null},
  {"num": 454, "time": "00:35:53,920 --> 00:35:57,380", "arabic": "وَلَا أَرَى الْخُرُوجَ عَلَيْهِ وَإِنْ كَانَ فَاسِقًا", "segs": null, "full_uz": "Fosiq bo'lsa ham, unga qarshi qo'zg'olon ko'tarishni to'g'ri deb bilmayman.", "note": null},
  {"num": 455, "time": "00:35:57,380 --> 00:36:04,280", "arabic": "وَمَنْ خَرَجَ عَلَى إِمَامٍ مِنْ أَئِمَّةِ الْمُسْلِمِينَ وَقَدِ اجْتَمَعَ عَلَيْهِ النَّاسُ وَأَقَرُّوا لَهُ بِالْخِلَافَةِ", "segs": [{"ar": "وَمَنْ خَرَجَ عَلَى إِمَامٍ مِنْ أَئِمَّةِ الْمُسْلِمِينَ", "uz": "Kim musulmonlarning imomlaridan biriga qarshi qo'zg'olon ko'tarsa"}, {"ar": "وَقَدِ اجْتَمَعَ عَلَيْهِ النَّاسُ وَأَقَرُّوا لَهُ بِالْخِلَافَةِ", "uz": "odamlar birlashib, xalifaligini tan olgan bo'lsa"}], "full_uz": "Kim musulmonlarning imomlaridan biriga qarshi qo'zg'olon ko'tarsa — u odamlar birlashib, xalifaligini tan olgan bo'lsa.", "note": null},
  {"num": 458, "time": "00:36:05,019 --> 00:36:10,600", "arabic": "فَقَدْ شَقَّ عَصَى الْمُسْلِمِينَ، أَدَانَ اللَّهُ وَإِيَّاهُمْ إِلَى الْحَقِّ", "segs": null, "full_uz": "U musulmonlarning birligini buzgan bo'ladi. Alloh bizni va ularni haqqa hidoyat qilsin.", "note": "شَقَّ عَصَا الْمُسْلِمِينَ — musulmonlar birligini buzish, ularga qarshi chiqish ma'nosidagi mashhur ibora."},
  {"num": 460, "time": "00:36:10,600 --> 00:36:11,740", "arabic": "آمِينَ", "segs": null, "full_uz": "Omin.", "note": null},
  {"num": 461, "time": "00:36:11,740 --> 00:36:18,360", "arabic": "وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ، وَالسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": [{"ar": "وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ", "uz": "Alloh sarvarimiz Muhammadga, uning ahli va sahobalariga salovot va salom yo'llasin"}, {"ar": "وَالسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "uz": "Va assalomu alaykum va rahmatulloh"}], "full_uz": "Alloh sarvarimiz Muhammadga, uning ahli va sahobalariga salovot va salom yo'llasin. Va assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 463, "time": "00:36:18,360 --> 00:36:19,519", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
  {"num": 464, "time": "00:36:19,519 --> 00:36:42,440", "arabic": "بَدَأَ الْمُعْتَزِلَةُ يَنْشُرُونَ أَقْوَالًا لَا أَدْرِي مَدَى صِحَّتِهَا، وَلَكِنَّهَا إِنْ صَدَقَتْ فَتِلْكَ هِيَ الطَّامَّةُ", "segs": [{"ar": "بَدَأَ الْمُعْتَزِلَةُ يَنْشُرُونَ أَقْوَالًا لَا أَدْرِي مَدَى صِحَّتِهَا", "uz": "Mo'tazila to'g'riligini bilmagan gaplarimni tarqata boshladi"}, {"ar": "وَلَكِنَّهَا إِنْ صَدَقَتْ فَتِلْكَ هِيَ الطَّامَّةُ", "uz": "agar to'g'ri chiqsa, mana bu falokatning o'zi bo'ladi"}], "full_uz": "Mo'tazila to'g'riligini bilmagan gaplarimni tarqata boshladi — agar to'g'ri chiqsa, mana bu falokatning o'zi bo'ladi.", "note": null},
  {"num": 466, "time": "00:36:42,440 --> 00:36:49,760", "arabic": "هَذَا اللَّهُ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ فَقَدْ سَمَحَ لِكُلِّ مُبْتَدِعٍ أَنْ يَتَكَلَّمَ فِي دِينِ اللَّهِ بِأَهْوَائِهِ", "segs": [{"ar": "هَذَا اللَّهُ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ", "uz": "Alloh Amir al-Mo'minin al-Ma'munni"}, {"ar": "فَقَدْ سَمَحَ لِكُلِّ مُبْتَدِعٍ أَنْ يَتَكَلَّمَ فِي دِينِ اللَّهِ بِأَهْوَائِهِ", "uz": "har bir bid'atchi Alloh dini haqida o'z havoyi bilan gapirishga ruxsat berdi"}], "full_uz": "Alloh Amir al-Mo'minin al-Ma'munni... har bir bid'atchi Alloh dini haqida o'z havoyi bilan gapirishga ruxsat berdi.", "note": null},
  {"num": 468, "time": "00:36:49,760 --> 00:36:53,860", "arabic": "أَسْأَلُ اللَّهَ لَنَا وَلَهُ الْعَافِيَةَ", "segs": null, "full_uz": "Alloh biz uchun ham, u uchun ham salomatlik so'rayman.", "note": null},
  {"num": 469, "time": "00:36:53,860 --> 00:36:54,700", "arabic": "آمِينَ", "segs": null, "full_uz": "Omin.", "note": null},
  {"num": 470, "time": "00:36:54,700 --> 00:36:59,740", "arabic": "يَا إِمَامُ، لِمَاذَا لَا تَطْلُبُ الدُّخُولَ عَلَى الْمَأْمُونِ وَوُزَرَائِهِ وَأُمَرَائِهِ", "segs": [{"ar": "يَا إِمَامُ، لِمَاذَا لَا تَطْلُبُ الدُّخُولَ عَلَى الْمَأْمُونِ", "uz": "Ey imom, nega al-Ma'mun huzuriga kirishni so'ramaysiz"}, {"ar": "وَوُزَرَائِهِ وَأُمَرَائِهِ", "uz": "va uning vazirlari hamda amirlari huzuriga"}], "full_uz": "Ey imom, nega al-Ma'mun va uning vazirlari hamda amirlari huzuriga kirishni so'ramaysiz.", "note": null},
  {"num": 472, "time": "00:36:59,740 --> 00:37:02,500", "arabic": "وَتُزْدِي لَهُمْ نُصْحًا؟ لَا يَصْلُحُ", "segs": null, "full_uz": "va ularga nasihat qilmaysiz? Bu to'g'ri kelmaydi.", "note": null},
  {"num": 474, "time": "00:37:02,500 --> 00:37:10,180", "arabic": "اَلدُّنُوُّ مِنْهُمْ فِتْنَةٌ وَالْجُلُوسُ مَعَهُمْ فِتْنَةٌ وَنَحْنُ مُتَبَاعِدُونَ مِنْهُمْ لَا نَسْلَمُ", "segs": [{"ar": "اَلدُّنُوُّ مِنْهُمْ فِتْنَةٌ وَالْجُلُوسُ مَعَهُمْ فِتْنَةٌ", "uz": "Ularga yaqinlashish fitna, ular bilan o'tirish ham fitna"}, {"ar": "وَنَحْنُ مُتَبَاعِدُونَ مِنْهُمْ لَا نَسْلَمُ", "uz": "biz ulardan yiroq bo'lsak ham omon qolmaymiz"}], "full_uz": "Ularga yaqinlashish fitna, ular bilan o'tirish ham fitna — biz ulardan yiroq bo'lsak ham omon qolmaymiz.", "note": null},
  {"num": 477, "time": "00:37:10,180 --> 00:37:14,820", "arabic": "فَكَيْفَ لَوْ قَرُبْنَا مِنْهُمْ؟ وَمَاذَا تَرَى يَا أَبَا عَبْدِ اللَّهِ؟", "segs": [{"ar": "فَكَيْفَ لَوْ قَرُبْنَا مِنْهُمْ؟", "uz": "Ularga yaqinlashsak-chi, qanday bo'ladi?"}, {"ar": "وَمَاذَا تَرَى يَا أَبَا عَبْدِ اللَّهِ؟", "uz": "Fikringiz qanday, Abu Abdulloh?"}], "full_uz": "Ularga yaqinlashsak-chi, qanday bo'ladi? Fikringiz qanday, Abu Abdulloh?", "note": null},
  {"num": 479, "time": "00:37:14,820 --> 00:37:22,620", "arabic": "يَا رَبِّ، عَلَيْكَ نَفْسَكَ", "segs": null, "full_uz": "Ey Robbim... O'zingga tayan.", "note": null},
  {"num": 481, "time": "00:37:22,620 --> 00:37:27,000", "arabic": "وَادْعُ مَنْ حَوْلَكَ وَاهْجُرْ صَاحِبَ الْبِدْعَةِ", "segs": null, "full_uz": "Atrofingdagilarni da'vat qil va bid'at sohibidan yiroqlash.", "note": null},
  {"num": 483, "time": "00:37:27,000 --> 00:37:32,740", "arabic": "وَتَمَسَّكْ بِالْقُرْآنِ وَالسُّنَّةِ وَدَعْ مَا سِوَاهُمَا فَفِيهِمَا النَّجَاةُ", "segs": null, "full_uz": "Qur'on va Sunnatga mahkam yopish, boshqasini tashla — najot ikkovida.", "note": null},
  {"num": 485, "time": "00:37:32,740 --> 00:37:37,400", "arabic": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا", "segs": [{"ar": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "Rasululloh sollallohu alayhi va sallam aytdilar"}, {"ar": "إِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا", "uz": "«Sizlardan kim yashasa, ko'p ixtiloflarni ko'radi»"}], "full_uz": "Rasululloh sollallohu alayhi va sallam aytdilar: «Sizlardan kim yashasa, ko'p ixtiloflarni ko'radi».", "note": "Bu — Abu Dovud va Termiziy rivoyat qilgan mashhur hadis, bid'atdan qaytarish haqida."},
  {"num": 487, "time": "00:37:37,400 --> 00:37:48,660", "arabic": "فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ بَعْدِي فَعَضُّوا عَلَيْهَا بِالنَّوَاجِذِ", "segs": [{"ar": "فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ بَعْدِي", "uz": "Mening sunnatimga va mendan keyingi to'g'ri yo'lga hidoyat qilingan xalifalarning sunnatiga yopishinglar"}, {"ar": "فَعَضُّوا عَلَيْهَا بِالنَّوَاجِذِ", "uz": "uni tishlaringiz bilan mahkam tuting"}], "full_uz": "Mening sunnatimga va mendan keyingi to'g'ri yo'lga hidoyat qilingan xalifalarning sunnatiga yopishinglar, uni tishlaringiz bilan mahkam tuting.", "note": null},
  {"num": 491, "time": "00:37:48,660 --> 00:37:53,600", "arabic": "وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ فَإِنَّ كُلَّ مُحْدَثَةٍ ضَلَالَةٌ", "segs": null, "full_uz": "Va yangi paydo bo'lgan ishlardan hazir bo'lingiz — chunki har bir yangilik zalolatdir.", "note": null},
  {"num": 493, "time": "00:38:12,840 --> 00:38:24,880", "arabic": "قُلْتُ لَكَ غَيْرَ مَرَّةٍ يَا وَلَدُ أَنْ تَلِينَ فِي كَلَامِكَ مَعَ السَّيِّدِ الْمُحْتَسِبِ", "segs": [{"ar": "قُلْتُ لَكَ غَيْرَ مَرَّةٍ يَا وَلَدُ", "uz": "Sanga bir necha marta aytdim, o'g'lim"}, {"ar": "أَنْ تَلِينَ فِي كَلَامِكَ مَعَ السَّيِّدِ الْمُحْتَسِبِ", "uz": "sayyid muhtasib bilan gaplashganda yumshoq bo'l"}], "full_uz": "Sanga bir necha marta aytdim, o'g'lim — sayyid muhtasib bilan gaplashganda yumshoq bo'l.", "note": null},
  {"num": 494, "time": "00:38:24,880 --> 00:38:27,320", "arabic": "أَلَا تَدْرِي مَا قَدْ يُصْنَعُ بِنَا؟", "segs": null, "full_uz": "Bizga nima qilinishi mumkinligini bilmaysanmi?", "note": null},
  {"num": 495, "time": "00:38:27,320 --> 00:38:31,320", "arabic": "إِنَّمَا أُعَامِلُهُ بِمَا يَسْتَحِقُّ، فَهَؤُلَاءِ سُيُوفٌ عَلَى رِقَابِنَا بِلَا فَارِسٍ", "segs": [{"ar": "إِنَّمَا أُعَامِلُهُ بِمَا يَسْتَحِقُّ", "uz": "Men unga loyiq bo'lgan muomalani qilyapman"}, {"ar": "فَهَؤُلَاءِ سُيُوفٌ عَلَى رِقَابِنَا بِلَا فَارِسٍ", "uz": "ular suvoriysiz bo'ynimizga tegib turgan qilichlardir"}], "full_uz": "Men unga loyiq bo'lgan muomalani qilyapman — ular suvoriysiz bo'ynimizga tegib turgan qilichlardir.", "note": null},
  {"num": 497, "time": "00:38:31,320 --> 00:38:35,680", "arabic": "خَفْ عَلَى نَفْسِكَ يَا عُمَرُ فَإِنَّكَ تَكَادُ أَنْ تُودِيَ بِنَفْسِكَ وَبِنَا إِلَى التَّهْلُكَةِ", "segs": [{"ar": "خَفْ عَلَى نَفْسِكَ يَا عُمَرُ", "uz": "O'zingdan qo'rq, Umar"}, {"ar": "فَإِنَّكَ تَكَادُ أَنْ تُودِيَ بِنَفْسِكَ وَبِنَا إِلَى التَّهْلُكَةِ", "uz": "o'zingni ham, bizni ham halokatga olib borishga yaqin qolding"}], "full_uz": "O'zingdan qo'rq, Umar — o'zingni ham, bizni ham halokatga olib borishga yaqin qolding.", "note": null},
  {"num": 499, "time": "00:38:35,680 --> 00:38:41,420", "arabic": "قُلْ لِي مَاذَا تَكْرَهُ فِي الدُّنْيَا، أَقُولُ لَكَ أَنْ أَرَى وَجْهَ مُعْتَزِلِيٍّ، إِذَنْ لَا تَنْظُرْ فِي وَجْهِهِ", "segs": [{"ar": "قُلْ لِي مَاذَا تَكْرَهُ فِي الدُّنْيَا", "uz": "Ayt-chi, dunyoda nimani yomon ko'rasan?"}, {"ar": "أَقُولُ لَكَ أَنْ أَرَى وَجْهَ مُعْتَزِلِيٍّ", "uz": "Aytaman senga — Mo'tazila yuzini ko'rishni"}, {"ar": "إِذَنْ لَا تَنْظُرْ فِي وَجْهِهِ", "uz": "Unda uning yuziga qarama"}], "full_uz": "Ayt-chi, dunyoda nimani yomon ko'rasan? Aytaman senga — Mo'tazila yuzini ko'rishni. Unda uning yuziga qarama.", "note": null},
  {"num": 501, "time": "00:38:41,420 --> 00:38:46,579", "arabic": "لَوْ رَأَيْتَهُ كَيْفَ كَانَ يُخَاطِبُ ابْنَ الْإِمَامِ لَمَا قُلْتَ هَذَا يَا أَبِي", "segs": [{"ar": "لَوْ رَأَيْتَهُ كَيْفَ كَانَ يُخَاطِبُ ابْنَ الْإِمَامِ", "uz": "Uni Imomning o'g'liga qanday murojaat qilganini ko'rganingda"}, {"ar": "لَمَا قُلْتَ هَذَا يَا أَبِي", "uz": "buni aytmasding, otajon"}], "full_uz": "Uni Imomning o'g'liga qanday murojaat qilganini ko'rganingda, otajon, buni aytmasding.", "note": null},
  {"num": 502, "time": "00:38:46,579 --> 00:38:54,099", "arabic": "يَا عُمَرُ، تَعْرِفُ أَنَّ الْمُعْتَزِلَةَ لَا يُطِيقُونَ فُقَهَاءَ بَغْدَادَ وَأَئِمَّتَهَا وَيَتَرَقَّبُونَ يَوْمَ الْفَتْكِ وَالْخَلَاصِ مِنْهُمْ", "segs": [{"ar": "يَا عُمَرُ، تَعْرِفُ أَنَّ الْمُعْتَزِلَةَ لَا يُطِيقُونَ فُقَهَاءَ بَغْدَادَ وَأَئِمَّتَهَا", "uz": "Umar, bilasan — Mo'tazila Bag'dod fuqaho va imomlariga chidamaydi"}, {"ar": "وَيَتَرَقَّبُونَ يَوْمَ الْفَتْكِ وَالْخَلَاصِ مِنْهُمْ", "uz": "ulardan qutulish va halokat kunini kutmoqda"}], "full_uz": "Umar, bilasan — Mo'tazila Bag'dod fuqaho va imomlariga chidamaydi, ulardan qutulish va halokat kunini kutmoqda.", "note": null},
  {"num": 504, "time": "00:38:54,099 --> 00:38:59,320", "arabic": "بَلْ قُلْ لَا يُطِيقُونَ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ، وَمَا جَدْوَى الْحَدِيثِ عَنْهُمْ", "segs": [{"ar": "بَلْ قُلْ لَا يُطِيقُونَ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ", "uz": "Yo'q, ahli sunna va jamoaga chidamaydi degin"}, {"ar": "وَمَا جَدْوَى الْحَدِيثِ عَنْهُمْ", "uz": "ular haqida gapirishning nima foydasi bor"}], "full_uz": "Yo'q, ahli sunna va jamoaga chidamaydi degin — ular haqida gapirishning nima foydasi bor.", "note": null},
  {"num": 506, "time": "00:38:59,320 --> 00:39:06,320", "arabic": "اِسْمَعْ يَا وَلَدُ، نَحْنُ لَسْنَا أَهْلًا لِاسْتِعْدَاءِ الْمُعْتَزِلَةِ، اَلْوَلَدُ الَّذِي تَتَحَدَّثُ عَنْهُ صَارَ رَجُلًا يَا أَبِي", "segs": [{"ar": "اِسْمَعْ يَا وَلَدُ، نَحْنُ لَسْنَا أَهْلًا لِاسْتِعْدَاءِ الْمُعْتَزِلَةِ", "uz": "Eshit, o'g'lim — biz Mo'tazilani o'zimizga dushman qilishga yaraymizmi?"}, {"ar": "اَلْوَلَدُ الَّذِي تَتَحَدَّثُ عَنْهُ صَارَ رَجُلًا يَا أَبِي", "uz": "Siz gapirayotgan o'sha bola endi erkak bo'ldi, otajon"}], "full_uz": "Eshit, o'g'lim — biz Mo'tazilani o'zimizga dushman qilishga yaraymizmi? Siz gapirayotgan o'sha bola endi erkak bo'ldi, otajon.", "note": null},
  {"num": 508, "time": "00:39:06,320 --> 00:39:11,280", "arabic": "يَعْلَمُ مَا يَجْرِي حَوْلَهُ وَلَنْ يَكُونَ يَوْمًا ظَهِيرًا لِمَنْ يَتَطَاوَلُ عَلَى الدِّينِ وَفُقَهَائِهِ", "segs": [{"ar": "يَعْلَمُ مَا يَجْرِي حَوْلَهُ", "uz": "U atrofida nima bo'layotganini biladi"}, {"ar": "وَلَنْ يَكُونَ يَوْمًا ظَهِيرًا لِمَنْ يَتَطَاوَلُ عَلَى الدِّينِ وَفُقَهَائِهِ", "uz": "va dinga va uning fuqaholariga tajovuz qiluvchiga hech qachon yordamchi bo'lmaydi"}], "full_uz": "U atrofida nima bo'layotganini biladi va dinga va uning fuqaholariga tajovuz qiluvchiga hech qachon yordamchi bo'lmaydi.", "note": null},
  {"num": 509, "time": "00:39:11,280 --> 00:39:17,300", "arabic": "يَا وَلَدِي، يَقْصِدُ أَبُوكَ أَنَّ عُلَمَاءَ بَغْدَادَ قَادِرُونَ عَلَى التَّصَدِّي لِهَؤُلَاءِ الْقَوْمِ", "segs": [{"ar": "يَا وَلَدِي، يَقْصِدُ أَبُوكَ", "uz": "O'g'lim, otang"}, {"ar": "أَنَّ عُلَمَاءَ بَغْدَادَ قَادِرُونَ عَلَى التَّصَدِّي لِهَؤُلَاءِ الْقَوْمِ", "uz": "Bag'dod olimlari bu qavmga qarshi tura olishini nazarda tutyapti"}], "full_uz": "O'g'lim, otang Bag'dod olimlari bu qavmga qarshi tura olishini nazarda tutyapti.", "note": null},
  {"num": 510, "time": "00:39:17,300 --> 00:39:24,519", "arabic": "أَمَّا نَحْنُ الْمَسَاكِينُ فَقَدْ نَضِيعُ تَحْتَ سَنَابِكِ الْفَرِيقَيْنِ، سُكُوتُنَا هُوَ مَا جَرَّأَ أَهْلَ الضَّلَالِ عَلَى النَّيْلِ مِنْ عُلَمَائِنَا", "segs": [{"ar": "أَمَّا نَحْنُ الْمَسَاكِينُ فَقَدْ نَضِيعُ تَحْتَ سَنَابِكِ الْفَرِيقَيْنِ", "uz": "Biz esa, miskinlar, ikki tomonning tuyoqlari ostida yo'q bo'lib ketishimiz mumkin"}, {"ar": "سُكُوتُنَا هُوَ مَا جَرَّأَ أَهْلَ الضَّلَالِ عَلَى النَّيْلِ مِنْ عُلَمَائِنَا", "uz": "Sukutimiz — bu zalolat ahlining olimlarimizga tajovuz qilishga jur'at etishiga sabab bo'ldi"}], "full_uz": "Biz esa, miskinlar, ikki tomonning tuyoqlari ostida yo'q bo'lib ketishimiz mumkin. Sukutimiz — bu zalolat ahlining olimlarimizga tajovuz qilishga jur'at etishiga sabab bo'ldi.", "note": null},
  {"num": 512, "time": "00:39:24,519 --> 00:39:29,680", "arabic": "إِنْ لَمْ نَتَصَدَّ لِهَؤُلَاءِ فَالْخَطَرُ قَادِمٌ لَا مَحَالَةَ وَسَيَغْرَقُ الْجَمِيعُ الطُّوفَانُ", "segs": [{"ar": "إِنْ لَمْ نَتَصَدَّ لِهَؤُلَاءِ فَالْخَطَرُ قَادِمٌ لَا مَحَالَةَ", "uz": "Agar ularga qarshi turmasak, xavf muqarrar keladi"}, {"ar": "وَسَيَغْرَقُ الْجَمِيعُ الطُّوفَانُ", "uz": "va barchamiz to'fonda cho'kib ketamiz"}], "full_uz": "Agar ularga qarshi turmasak, xavf muqarrar keladi va barchamiz to'fonda cho'kib ketamiz.", "note": null},
  {"num": 513, "time": "00:39:29,680 --> 00:39:34,700", "arabic": "جِدْ لِابْنِكَ حَلًّا يَا أَبِي قَبْلَ أَنْ يُؤْذِيَ بِنَفْسِهِ وَبِنَا إِلَى التَّهْلُكَةِ", "segs": [{"ar": "جِدْ لِابْنِكَ حَلًّا يَا أَبِي", "uz": "Otajon, o'g'lingizga chora toping"}, {"ar": "قَبْلَ أَنْ يُؤْذِيَ بِنَفْسِهِ وَبِنَا إِلَى التَّهْلُكَةِ", "uz": "u o'ziga ham, bizga ham zarar yetkazib, halokatga olib bormasdan"}], "full_uz": "Otajon, o'g'lingizga chora toping — u o'ziga ham, bizga ham zarar yetkazib, halokatga olib bormasdan.", "note": null},
  {"num": 514, "time": "00:39:34,700 --> 00:39:42,480", "arabic": "لَا بُدَّ أَنْ أَجِدَ لَهُ حَلًّا فَلَسْنَا بِحَاجَةٍ إِلَى مَزِيدٍ مِنَ الْمَشَاكِلِ، مَاذَا سَتَفْعَلُ يَا عَامِرُ؟", "segs": [{"ar": "لَا بُدَّ أَنْ أَجِدَ لَهُ حَلًّا", "uz": "Unga albatta chora topishim kerak"}, {"ar": "فَلَسْنَا بِحَاجَةٍ إِلَى مَزِيدٍ مِنَ الْمَشَاكِلِ", "uz": "bizga ko'proq muammo hojati yo'q"}, {"ar": "مَاذَا سَتَفْعَلُ يَا عَامِرُ؟", "uz": "Nima qilmoqchisiz, Omir?"}], "full_uz": "Unga albatta chora topishim kerak — bizga ko'proq muammo hojati yo'q. Nima qilmoqchisiz, Omir?", "note": null},
  {"num": 516, "time": "00:39:42,480 --> 00:39:46,760", "arabic": "سَأَمْلَأُ عَلَيْهِ يَوْمَهُ وَلَيْلَهُ، لَا يَسْتَطِيعُ فَكَاكًا", "segs": null, "full_uz": "Uning kunini ham, tunini ham to'ldiraman — qutulishga imkoni bo'lmaydi.", "note": null},
  {"num": 518, "time": "00:39:46,760 --> 00:39:48,480", "arabic": "سَأُزَوِّجُهُ", "segs": null, "full_uz": "Uni uylantiraman.", "note": null},
  {"num": 519, "time": "00:39:48,480 --> 00:39:51,440", "arabic": "وَكَيْفَ سَيَكُونُ زَوَاجُهُ حَلًّا؟", "segs": null, "full_uz": "Uning nikohi qanday chora bo'ladi?", "note": null},
  {"num": 520, "time": "00:39:51,440 --> 00:39:58,639", "arabic": "اِسْمَعْ يَا وَلَدُ، إِنَّهُ إِنْ تَزَوَّجَ سَيَصُبُّ جَامَ غَضَبِهِ عَلَى زَوْجِهِ فَيَكُفُّ عَنِ التَّعَرُّضِ لِلْمُعْتَزِلَةِ", "segs": [{"ar": "اِسْمَعْ يَا وَلَدُ، إِنَّهُ إِنْ تَزَوَّجَ سَيَصُبُّ جَامَ غَضَبِهِ عَلَى زَوْجِهِ", "uz": "Eshit, o'g'lim — agar u uylansa, g'azabini xotiniga to'kadi"}, {"ar": "فَيَكُفُّ عَنِ التَّعَرُّضِ لِلْمُعْتَزِلَةِ", "uz": "va Mo'tazilaga tegishdan to'xtaydi"}], "full_uz": "Eshit, o'g'lim — agar u uylansa, g'azabini xotiniga to'kadi va Mo'tazilaga tegishdan to'xtaydi.", "note": null},
  {"num": 523, "time": "00:39:58,639 --> 00:40:02,820", "arabic": "تَقْصِدُ الْمُعْتَزِلَةَ؟ أَيًّا كَانَ لَا فَرْقَ", "segs": null, "full_uz": "Mo'tazilani nazarda tutyapsizmi? Qanday bo'lmasin, farqi yo'q.", "note": null},
  {"num": 525, "time": "00:40:02,820 --> 00:40:09,659", "arabic": "لَا حَرَمَنَا اللَّهُ مِنْ ذَكَائِكَ وَحُسْنِ تَدْبِيرِكَ يَا أَبَا عُمَيْرٍ", "segs": [{"ar": "لَا حَرَمَنَا اللَّهُ مِنْ ذَكَائِكَ وَحُسْنِ تَدْبِيرِكَ", "uz": "Alloh bizni aqlingiz va yaxshi tadbiringizdan mahrum qilmasin"}, {"ar": "يَا أَبَا عُمَيْرٍ", "uz": "Abu Umayr"}], "full_uz": "Alloh bizni aqlingiz va yaxshi tadbiringizdan mahrum qilmasin, Abu Umayr.", "note": null},
  {"num": 526, "time": "00:40:09,659 --> 00:40:24,059", "arabic": "فَاجْمَعْ مَنْ بِحَضْرَتِكَ مِنَ الْقُضَاةِ وَاقْرَأْ عَلَيْهِمْ كِتَابَ أَمِيرِ الْمُؤْمِنِينَ هَذَا إِلَيْكَ", "segs": [{"ar": "فَاجْمَعْ مَنْ بِحَضْرَتِكَ مِنَ الْقُضَاةِ", "uz": "Huzuringizdagi qozilarni yig'ing"}, {"ar": "وَاقْرَأْ عَلَيْهِمْ كِتَابَ أَمِيرِ الْمُؤْمِنِينَ هَذَا إِلَيْكَ", "uz": "Amir al-Mo'mininning senga bu xatini ularga o'qib bering"}], "full_uz": "Huzuringizdagi qozilarni yig'ib, Amir al-Mo'mininning senga bu xatini ularga o'qib bering.", "note": null},
  {"num": 528, "time": "00:40:24,059 --> 00:40:31,599", "arabic": "فَابْدَأْ بِامْتِحَانِهِمْ فِيمَا يَقُولُونَ وَمَا يَعْتَقِدُونَ فِي خَلْقِ اللَّهِ الْقُرْآنَ وَإِحْدَاثِهِ", "segs": [{"ar": "فَابْدَأْ بِامْتِحَانِهِمْ فِيمَا يَقُولُونَ", "uz": "Ularni aytadigan gaplari bo'yicha sinovdan boshlang"}, {"ar": "وَمَا يَعْتَقِدُونَ فِي خَلْقِ اللَّهِ الْقُرْآنَ وَإِحْدَاثِهِ", "uz": "va Alloh Qur'onni yaratganligi hamda hodisa qilganligi haqidagi e'tiqodlari bo'yicha"}], "full_uz": "Ularni Alloh Qur'onni yaratganligi va uni hodisa qilganligi haqidagi so'z va e'tiqodlari bo'yicha sinovdan boshlang.", "note": null},
  {"num": 530, "time": "00:40:31,599 --> 00:40:38,839", "arabic": "وَعَلِّمْهُمْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ غَيْرُ مُسْتَعِينٍ فِي عَمَلِهِ وَلَا وَاثِقٍ", "segs": [{"ar": "وَعَلِّمْهُمْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ", "uz": "Va bilib qo'yishsinki, Amir al-Mo'minin"}, {"ar": "غَيْرُ مُسْتَعِينٍ فِي عَمَلِهِ وَلَا وَاثِقٍ", "uz": "o'z ishida ishonch bildirmaydi va yordam olmaydi"}], "full_uz": "Va bilib qo'yishsinki, Amir al-Mo'minin o'z ishida ishonch bildirmaydi va yordam olmaydi.", "note": null},
  {"num": 532, "time": "00:40:38,840 --> 00:40:48,900", "arabic": "فِيمَا قَلَّدَهُ اللَّهُ وَاسْتَحْفَظَهُ مِنْ أُمُورِ رَعِيَّتِهِ بِمَنْ لَا يَثِقُ بِدِينِهِ", "segs": [{"ar": "فِيمَا قَلَّدَهُ اللَّهُ وَاسْتَحْفَظَهُ مِنْ أُمُورِ رَعِيَّتِهِ", "uz": "Alloh unga topshirgan va raiyati ishlarida amonat qilgan narsada"}, {"ar": "بِمَنْ لَا يَثِقُ بِدِينِهِ", "uz": "dinidan ishonchsiz kishilardan foydalanmaydi"}], "full_uz": "Alloh unga topshirgan va raiyati ishlarida amonat qilgan narsada, dinidan ishonchsiz kishilardan foydalanmaydi.", "note": null},
  {"num": 535, "time": "00:40:48,900 --> 00:41:00,840", "arabic": "مَا لَنَا نَحْنُ بِهَذِهِ الْمَسَائِلِ؟", "segs": null, "full_uz": "Bu masalalarga bizning nima aloqamiz bor?", "note": null},
  {"num": 536, "time": "00:41:00,840 --> 00:41:03,840", "arabic": "أَلَا يَرْعَوُونَ عَنْ هَذِهِ الْأُمُورِ؟", "segs": null, "full_uz": "Bu ishlardan tiyilishmaydimi?", "note": "اِرْعَوَى عَنِ الشَّيْءِ — biror ishdan qaytish, tiyilish."},
  {"num": 537, "time": "00:41:03,840 --> 00:41:09,319", "arabic": "خَلْقُ الْقُرْآنِ، أَنْ يُوجَدَ بِهَا مِنْ وَرَاءِ ذَلِكَ لَا أَدْرِي", "segs": [{"ar": "خَلْقُ الْقُرْآنِ", "uz": "Qur'onning yaratilishi"}, {"ar": "أَنْ يُوجَدَ بِهَا مِنْ وَرَاءِ ذَلِكَ لَا أَدْرِي", "uz": "buning ortida nima borligini bilmayman"}], "full_uz": "Qur'onning yaratilishi — buning ortida nima borligini bilmayman.", "note": null},
  {"num": 539, "time": "00:41:09,319 --> 00:41:16,119", "arabic": "كُلَّ حِينٍ يَخُوضُونَ عَلَيْنَا بِمُصِيبَةٍ جَدِيدَةٍ تُفَتِّرُ النَّاسَ", "segs": null, "full_uz": "Har safar ustimizga odamlarni sovutadigan yangi bir musibat bilan kirib kelishadi.", "note": null},
  {"num": 540, "time": "00:41:16,119 --> 00:41:20,439", "arabic": "أَفَرَّ اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh Amir al-Mo'mininga mag'firat qilsin.", "note": null},
  {"num": 541, "time": "00:41:32,439 --> 00:41:34,839", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 542, "time": "00:41:34,840 --> 00:41:37,760", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Va alaykum assalom va rahmatullohi va barakatuh.", "note": null},
  {"num": 543, "time": "00:41:37,760 --> 00:41:40,700", "arabic": "أَهْلًا بِالْأَمِيرِ أَبِي عَبْدِ اللَّهِ", "segs": null, "full_uz": "Amir Abu Abdullohga xush kelibsiz.", "note": null},
  {"num": 544, "time": "00:41:40,700 --> 00:41:43,840", "arabic": "وَصَلَكَ كِتَابُ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Amir al-Mo'mininning xati senga yetib keldimi?", "note": null},
  {"num": 545, "time": "00:41:44,680 --> 00:41:45,840", "arabic": "أَعِنْدَكَ عِلْمٌ بِذَلِكَ؟", "segs": null, "full_uz": "Bundan xabaring bormi?", "note": null},
  {"num": 546, "time": "00:41:47,539 --> 00:41:52,900", "arabic": "تَعْرِفُ أَنَّ قَاضِيَ الْقُضَاةِ الْأَمِيرَ ابْنَ أَبِي دُؤَادٍ يَحْرِصُ عَلَى أَنْ يُطْلِعَنِي عَلَى دَقَائِقِ الْأُمُورِ", "segs": [{"ar": "تَعْرِفُ أَنَّ قَاضِيَ الْقُضَاةِ الْأَمِيرَ ابْنَ أَبِي دُؤَادٍ", "uz": "Bilasiz — bosh qozi Amir Ibn Abi Duvod"}, {"ar": "يَحْرِصُ عَلَى أَنْ يُطْلِعَنِي عَلَى دَقَائِقِ الْأُمُورِ", "uz": "ishlarning mayda-chuydasidan meni xabardor qilishga alohida e'tibor beradi"}], "full_uz": "Bilasiz — bosh qozi Amir Ibn Abi Duvod ishlarning mayda-chuydasidan meni xabardor qilishga alohida e'tibor beradi.", "note": null},
  {"num": 547, "time": "00:41:52,900 --> 00:41:55,579", "arabic": "أَعْرِفُ أَعْرِفُ، وَلَكِنْ يَا أَبَا", "segs": null, "full_uz": "Bilaman, bilaman. Ammo...", "note": null},
  {"num": 548, "time": "00:41:55,579 --> 00:42:01,120", "arabic": "هَلْ أَرْسَلْتَ فِي طَلَبِ الْقَوْمِ؟", "segs": null, "full_uz": "Odamlar orqasidan yubordingizmi?", "note": null},
  {"num": 549, "time": "00:42:01,120 --> 00:42:03,660", "arabic": "لَمْ يَكَدِ الْكِتَابُ يَصِلُنِي يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Xat hozirgina yetib kelgan edi, Abu Abdulloh.", "note": null},
  {"num": 550, "time": "00:42:04,840 --> 00:42:11,519", "arabic": "هَذِهِ الْأُمُورُ يُفْسِدُهَا التَّوَانِي وَالتَّأَنِّي أَيُّهَا الْوَالِي، وَالْأَجْدَرُ الْإِسْرَاعُ بِإِنْفَاذِهَا", "segs": [{"ar": "هَذِهِ الْأُمُورُ يُفْسِدُهَا التَّوَانِي وَالتَّأَنِّي أَيُّهَا الْوَالِي", "uz": "Bu ishlarni bo'shashish va shoshilmaslik buzadi, ey hokim"}, {"ar": "وَالْأَجْدَرُ الْإِسْرَاعُ بِإِنْفَاذِهَا", "uz": "uni ijro etishga shoshilish munosibroqdir"}], "full_uz": "Bu ishlarni bo'shashish va shoshilmaslik buzadi, ey hokim — uni ijro etishga shoshilish munosibroqdir.", "note": null},
  {"num": 552, "time": "00:42:11,519 --> 00:42:16,440", "arabic": "سَأَحْرِصُ عَلَى ذَلِكَ بِمَا أَمَرْتَ وَبِسُرْعَةٍ", "segs": null, "full_uz": "Buyurganingizdek va tezlik bilan shunga rioya qilaman.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}